import { type MonsterDetails } from "@hunt/hunt-data/monarch";
import { useCallback, useEffect, useRef, useState } from "react";
import {
  DEFAULT_FISH_WIDTH,
  FISH_SPAWN_INTERVAL,
  MAX_FISH_SPEED,
  MIN_FISH_SPEED,
} from "./constants";
import {
  getInitialFishPosition,
  getRoundMultiplier,
  shouldRemoveFish,
  updateFishPosition,
} from "./fishBehaviors";
import { type Fish, type GameState } from "./types";
import { stateIsPlaying } from "./utils";

type UseFishManagerProps = {
  gameState: GameState;
  puzzmonData: MonsterDetails[] | undefined;
  getNextWord: { fn: () => [string, string] | undefined };
  roundNumber: number;
};

export function useFishManager({
  gameState,
  puzzmonData,
  getNextWord,
  roundNumber,
}: UseFishManagerProps) {
  const [fish, setFish] = useState<Fish[]>([]);
  const fishIdCounter = useRef(0);
  const animationFrameRef = useRef<number | null>(null);
  const lastSpawnTimeRef = useRef(0);
  const [wordsExhausted, setWordsExhausted] = useState(false);
  const [roundFinished, setRoundFinished] = useState(false);

  // Get random puzzmon with typing words (all behaviors except pop_out)
  const getRandomTypingPuzzmon = useCallback(() => {
    if (!puzzmonData || puzzmonData.length === 0) return null;
    return puzzmonData[
      Math.floor(Math.random() * puzzmonData.length)
    ] as MonsterDetails;
  }, [puzzmonData]);

  // Get width for a puzzmon from its MonsterDetails, or use default
  const getPuzzmonWidth = useCallback((puzzmon: MonsterDetails): number => {
    const width = puzzmon.bubbleCoveTypingTask?.width;
    if (typeof width === "number") {
      return width;
    }
    return DEFAULT_FISH_WIDTH;
  }, []);

  // Spawn a new fish with typing word
  const spawnFish = useCallback(() => {
    const puzzmon = getRandomTypingPuzzmon();
    if (!puzzmon?.bubbleCoveTypingTask) return;

    const behavior = puzzmon.bubbleCoveTypingTask.behavior;
    const { baseY, x, direction } = getInitialFishPosition(behavior);

    const nextWord = getNextWord.fn();
    if (nextWord === undefined) {
      setWordsExhausted(true);
      return;
    }

    const newFish: Fish = {
      id: `fish-${fishIdCounter.current++}`,
      puzzmon,
      x,
      baseX: x,
      text: nextWord[1] ?? "",
      answer: nextWord[0] ?? "",
      baseY,
      completed: false,
      y: baseY, // Start at base position
      speed: MIN_FISH_SPEED + Math.random() * (MAX_FISH_SPEED - MIN_FISH_SPEED),
      spawnTime: performance.now(),
      meanderPhase: Math.random() * Math.PI * 2, // Random phase offset (0 to 2π)
      meanderFrequency: 0.3 + Math.random() * 0.7, // Random frequency (0.3 to 1.0)
      meanderAmplitude: 0.5 + Math.random() * 1.0, // Random amplitude (0.5 to 1.5)
      meanderDirection: -0.3 + Math.random() * 0.6, // Random direction change (-0.3 to 0.3)
      width: getPuzzmonWidth(puzzmon), // Width from MonsterDetails or default
      direction,
      behavior,
      rotation: puzzmon.bubbleCoveTypingTask.rotation || 0,
      spiralPhase: Math.random() * Math.PI * 2, // Random starting phase for spiral
      side:
        behavior === "pop_out"
          ? direction === 1
            ? "right"
            : "left"
          : undefined,
    };

    setFish((prev) => [...prev, newFish]);
  }, [getRandomTypingPuzzmon, getNextWord, getPuzzmonWidth]);

  useEffect(() => {
    if (fish.length === 0 && wordsExhausted) {
      setRoundFinished(true);
    }
  }, [wordsExhausted, fish]);

  useEffect(() => {
    setRoundFinished(false);
    setWordsExhausted(false);
    lastSpawnTimeRef.current = 0;
  }, [gameState]);

  // Update fish positions
  useEffect(() => {
    if (!stateIsPlaying(gameState)) return;

    let lastTime = performance.now();

    const updateFish = (currentTime: number) => {
      const deltaTime = (currentTime - lastTime) / 1000; // Convert to seconds
      lastTime = currentTime;

      // Update swimming fish with behavior-specific logic
      setFish((prev) =>
        prev
          .filter((f) => {
            const timeSinceSpawn = (currentTime - f.spawnTime) / 1000;
            return !shouldRemoveFish(f, timeSinceSpawn, roundNumber);
          })
          .map((f) => {
            const timeSinceSpawn = (currentTime - f.spawnTime) / 1000;
            const speedPercentPerSecond = f.speed;

            const {
              x: newX,
              y: newY,
              rotation: newRotation,
              isMovingBack,
            } = updateFishPosition(
              f,
              timeSinceSpawn,
              deltaTime,
              speedPercentPerSecond,
              roundNumber,
            );

            return {
              ...f,
              x: newX,
              y: newY,
              rotation: newRotation,
              isMovingBack,
            };
          }),
      );

      animationFrameRef.current = requestAnimationFrame(updateFish);
    };

    animationFrameRef.current = requestAnimationFrame(updateFish);

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, [gameState, roundNumber]);

  // Spawn swimming fish periodically
  useEffect(() => {
    if (!stateIsPlaying(gameState)) return;

    const now = Date.now();
    if (
      now - lastSpawnTimeRef.current >=
      FISH_SPAWN_INTERVAL / getRoundMultiplier(roundNumber)
    ) {
      spawnFish();
      lastSpawnTimeRef.current = now;
    }

    const interval = setInterval(
      () => {
        spawnFish();
        lastSpawnTimeRef.current = Date.now();
      },
      FISH_SPAWN_INTERVAL / getRoundMultiplier(roundNumber),
    );

    return () => {
      clearInterval(interval);
    };
  }, [gameState, roundNumber, spawnFish]);

  const clearFish = useCallback(() => {
    setFish([]);
  }, []);

  const markFishCompleted = useCallback((fishId: string) => {
    setFish((prev) =>
      prev.map((f) => (f.id === fishId ? { ...f, completed: true } : f)),
    );
  }, []);

  return {
    fish,
    spawnFish,
    clearFish,
    markFishCompleted,
    roundFinished,
  };
}
