const QUOTE =
  "Dam Bor glued each of his six eyes to the lenses of the cosmoscope";

const processWord = (word: string) => {
  return word
    .replace(/[^a-zA-Z]/g, "")
    .toUpperCase()
    .trim();
};

// Shuffles an array using the Fisher-Yates algorithm, from https://stackoverflow.com/a/2450976.
const shuffle = (array: string[]) => {
  let currentIndex = array.length;

  // While there remain elements to shuffle...
  while (currentIndex !== 0) {
    // Pick a remaining element.
    const randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex--;

    // Swap it with the current element.
    [array[currentIndex], array[randomIndex]] = [
      array[randomIndex],
      array[currentIndex],
    ];
  }
};

export const wordsInQuote = () => {
  const words = [...new Set(QUOTE.split(" ").map(processWord))];
  shuffle(words);
  return words;
};

export const checkAnswerImpl = (guesses: string[]) => {
  const words = QUOTE.split(" ").map(processWord);
  if (
    guesses.slice(guesses.length - words.length).join(" ") === words.join(" ")
  ) {
    return true;
  }

  return false;
};
