// Path building logic - builds continuous beam paths from cell beams

import type { ContinuousBeamPath, Direction, RGBColor } from "./beamTypes";
import { mixColors } from "./beamUtils";
import type { GridPuzzmon } from "./types";

export type PathBuildingContext = {
  gridState: (GridPuzzmon | null)[][];
  gridRows: number;
  gridCols: number;
  cellBeams: Map<string, RGBColor[]>;
  isTargetPosition: (row: number, col: number) => boolean;
};

/**
 * Builds continuous beam paths from cell beams
 * Groups adjacent cells with the same color and direction into continuous paths
 */
export function buildContinuousPaths(
  context: PathBuildingContext,
): ContinuousBeamPath[] {
  const { gridState, gridRows, gridCols, cellBeams, isTargetPosition } =
    context;

  const continuousPaths: ContinuousBeamPath[] = [];
  const processed = new Set<string>();

  for (const [cellKey, colors] of cellBeams.entries()) {
    const parts = cellKey.split("-");
    const row = Number(parts[0]);
    const col = Number(parts[1]);
    const direction = parts[2] as Direction;

    // Skip if already processed as part of a continuous path
    if (processed.has(cellKey)) continue;

    // Mix all colors for this cell/direction
    const mixedColor = mixColors(colors);

    // Find the start and end of this continuous path
    let startRow = row;
    let startCol = col;
    let endRow = row;
    let endCol = col;

    // Trace backward to find start
    let currentRow = row;
    let currentCol = col;
    while (true) {
      let prevRow = currentRow;
      let prevCol = currentCol;

      switch (direction) {
        case "down":
          prevRow -= 1;
          break;
        case "up":
          prevRow += 1;
          break;
        case "right":
          prevCol -= 1;
          break;
        case "left":
          prevCol += 1;
          break;
      }

      if (
        prevRow >= 0 &&
        prevRow < gridRows &&
        prevCol >= 0 &&
        prevCol < gridCols
      ) {
        // Skip if this cell has a puzzmon or target
        if (
          gridState[prevRow]?.[prevCol] !== null ||
          isTargetPosition(prevRow, prevCol)
        ) {
          break;
        }
        const prevKey = `${prevRow}-${prevCol}-${direction}`;
        const prevColors = cellBeams.get(prevKey);
        if (prevColors && prevColors.length > 0) {
          const prevMixedColor = mixColors(prevColors);
          // Check if colors match (within tolerance)
          const colorMatch =
            Math.abs(prevMixedColor.r - mixedColor.r) < 0.01 &&
            Math.abs(prevMixedColor.g - mixedColor.g) < 0.01 &&
            Math.abs(prevMixedColor.b - mixedColor.b) < 0.01;

          if (colorMatch) {
            startRow = prevRow;
            startCol = prevCol;
            currentRow = prevRow;
            currentCol = prevCol;
            processed.add(prevKey);
            continue;
          }
        }
      }
      break;
    }

    // Trace forward to find end
    currentRow = row;
    currentCol = col;
    while (true) {
      let nextRow = currentRow;
      let nextCol = currentCol;

      switch (direction) {
        case "down":
          nextRow += 1;
          break;
        case "up":
          nextRow -= 1;
          break;
        case "right":
          nextCol += 1;
          break;
        case "left":
          nextCol -= 1;
          break;
      }

      if (
        nextRow >= 0 &&
        nextRow < gridRows &&
        nextCol >= 0 &&
        nextCol < gridCols
      ) {
        // Skip if this cell has a puzzmon or target
        if (
          gridState[nextRow]?.[nextCol] !== null ||
          isTargetPosition(nextRow, nextCol)
        ) {
          break;
        }
        const nextKey = `${nextRow}-${nextCol}-${direction}`;
        const nextColors = cellBeams.get(nextKey);
        if (nextColors && nextColors.length > 0) {
          const nextMixedColor = mixColors(nextColors);
          // Check if colors match (within tolerance)
          const colorMatch =
            Math.abs(nextMixedColor.r - mixedColor.r) < 0.01 &&
            Math.abs(nextMixedColor.g - mixedColor.g) < 0.01 &&
            Math.abs(nextMixedColor.b - mixedColor.b) < 0.01;

          if (colorMatch) {
            endRow = nextRow;
            endCol = nextCol;
            currentRow = nextRow;
            currentCol = nextCol;
            processed.add(nextKey);
            continue;
          }
        }
      }
      break;
    }

    // Create continuous path
    continuousPaths.push({
      startRow,
      startCol,
      endRow,
      endCol,
      direction,
      color: mixedColor,
    });
    processed.add(cellKey);
  }

  return continuousPaths;
}
