import { ConditionalTooltip } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { Check } from "lucide-react";
import React from "react";
import { ALL_TOYS, MAX_TOYS, TOY_IMAGES } from "../constants";
import type { PlacedItem } from "../types";

type ToyInventoryProps = {
  placedItems: PlacedItem[];
  onToyClick: (toy: string) => void;
};

export function ToyInventory({ placedItems, onToyClick }: ToyInventoryProps) {
  const isToyPlaced = (toy: string) => {
    return placedItems.some((item) => item.toy === toy);
  };

  return (
    <div className="flex-shrink-0 h-full max-w-[20%]">
      <div className="bg-gray-100 border-2 border-gray-400 rounded-lg px-2 pt-2 pb-1 lg:py-4 lg:pb-1 flex flex-col h-full">
        <div
          className={cn(
            "text-sm lg:text-base font-semibold text-gray-900 mb-2 text-center",
            placedItems.length >= MAX_TOYS && "text-gray-700",
          )}
        >
          {placedItems.length}/{MAX_TOYS} placed
        </div>
        <div className="grid grid-cols-2 gap-2 overflow-y-auto p-2 flex-1 min-h-0">
          {ALL_TOYS.map((toy) => {
            const isPlaced = isToyPlaced(toy);
            const isDisabled = !isPlaced && placedItems.length >= MAX_TOYS;
            return (
              <ConditionalTooltip
                key={toy}
                tooltip={
                  isDisabled ? "You can only place up to four toys." : undefined
                }
                className="z-[400] max-w-40 text-center"
                disableHoverableContent={true}
              >
                <button
                  type="button"
                  onClick={() => {
                    onToyClick(toy);
                  }}
                  disabled={isDisabled}
                  className={cn(
                    "relative border-2 rounded-lg transition-all flex-shrink-0 w-full aspect-square",
                    isPlaced
                      ? "border-green-500 bg-green-100 hover:scale-105"
                      : isDisabled
                        ? "border-gray-300 bg-gray-200 opacity-50 cursor-not-allowed"
                        : "border-gray-300 bg-white hover:border-gray-400 hover:scale-105",
                  )}
                  aria-label={`${toy} (${isPlaced ? "placed" : isDisabled ? "disabled" : "not placed"})`}
                >
                  <img
                    src={TOY_IMAGES[toy]}
                    alt={toy}
                    className="w-full h-full object-contain p-1"
                  />
                  {isPlaced && (
                    <div className="absolute top-0 right-0 bg-green-500 text-white rounded-full w-5 h-5 flex items-center justify-center text-xs font-bold">
                      <Check size={14} strokeWidth={2.5} />
                    </div>
                  )}
                </button>
              </ConditionalTooltip>
            );
          })}
        </div>
      </div>
    </div>
  );
}
