import { cn } from "@hunt/styled-ui";

type PuzzmonToggleProps = {
  isEnabled: boolean;
  onToggle?: () => void;
  className?: string;
};

const PuzzmonToggle = ({
  isEnabled,
  onToggle,
  className,
}: PuzzmonToggleProps) => {
  return (
    <div>
      <div
        id="puzzmon-toggle"
        className={cn(
          "flex items-center gap-2 mb-2 text-monarch-light cursor-pointer",
          className,
        )}
        onClick={onToggle}
        role="switch"
        tabIndex={0}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            onToggle?.();
          }
        }}
        aria-checked={isEnabled}
      >
        <div className="flex items-center gap-1">
          <div
            className={cn(
              "w-[54px] h-[28px] rounded-full flex items-center p-1 cursor-pointer transition-colors",
              isEnabled
                ? "bg-monarch-light shadow-[inset_0_4px_4px_rgba(0,0,0,0.35)]"
                : "bg-[#23273F] shadow-[inset_0_4px_4px_rgba(0,0,0,0.55)]",
            )}
          >
            <div
              className={cn(
                "w-[22px] h-[22px] rounded-full transition-all duration-200 ease-in-out",
                isEnabled
                  ? "translate-x-[24px] bg-monarch-dark"
                  : "translate-x-0 bg-[#B6D0F3]",
              )}
            />
          </div>
        </div>
        <label htmlFor="puzzmon-toggle">
          Toggle to {isEnabled ? "hide" : "spoil"} unbefriended Puzzmon
        </label>
      </div>
    </div>
  );
};

export default PuzzmonToggle;
