export const KITTY_CITY_TASK_DATA_KEY = "kitty_city_photo_album";

export type PlacedItem = {
  toy: string;
};

export type Photo = {
  catName: string;
  photoSrc: string;
};

// Photo with derived catDigit (used internally, not stored)
export type PhotoWithDigit = Photo & {
  catDigit: number;
};

export type StorageData = {
  placedItems: PlacedItem[];
  photos: Photo[];
  hasSubmitted: boolean;
};
