import { cn } from "@hunt/styled-ui";
import React from "react";
import { colorNameToRgb, isLightColor, rgbToCss } from "./beamUtils";
import type { LightState } from "./useLightSources";

function getLightRgb(light: LightState): string {
  if (light === null) {
    return "off";
  }
  if (light === "white") {
    return "RGB";
  }
  return light.charAt(0).toUpperCase();
}

type LightSourceButtonsProps = {
  topLight: LightState;
  leftLight: LightState;
  rightLight: LightState;
  bottomLight: LightState;
  onToggleTop: () => void;
  onToggleLeft: () => void;
  onToggleRight: () => void;
  onToggleBottom: () => void;
};

export const LightSourceButtons: React.FC<LightSourceButtonsProps> = ({
  topLight,
  leftLight,
  rightLight,
  bottomLight,
  onToggleTop,
  onToggleLeft,
  onToggleRight,
  onToggleBottom,
}) => {
  return (
    <>
      {/* Top button */}
      <button
        onClick={onToggleTop}
        className={cn(
          "absolute -top-1 left-1/2 -translate-x-1/2 -translate-y-full w-12 p-2 rounded-full font-bold text-sm border-2 select-none",
          topLight === null
            ? "bg-black border-white text-white"
            : isLightColor(colorNameToRgb(topLight))
              ? "border-black text-black"
              : "border-white text-white",
        )}
        style={
          topLight !== null
            ? {
                backgroundColor: rgbToCss(colorNameToRgb(topLight), 0.8),
              }
            : {}
        }
      >
        {getLightRgb(topLight)}
      </button>

      {/* Left button */}
      <button
        onClick={onToggleLeft}
        className={cn(
          "absolute -left-1 top-1/2 -translate-x-full -translate-y-1/2 w-12 p-2 rounded-full font-bold text-sm border-2 select-none",
          leftLight === null
            ? "border-white text-white"
            : isLightColor(colorNameToRgb(leftLight))
              ? "border-black text-black"
              : "border-white text-white",
        )}
        style={{
          backgroundColor: leftLight
            ? rgbToCss(colorNameToRgb(leftLight), 0.8)
            : "black",
        }}
      >
        {getLightRgb(leftLight)}
      </button>

      {/* Right button */}
      <button
        onClick={onToggleRight}
        className={cn(
          "absolute -right-1 top-1/2 translate-x-full -translate-y-1/2 w-12 p-2 rounded-full font-bold text-sm border-2 select-none",
          rightLight === null
            ? "border-white text-white"
            : isLightColor(colorNameToRgb(rightLight))
              ? "border-black text-black"
              : "border-white text-white",
        )}
        style={{
          backgroundColor: rightLight
            ? rgbToCss(colorNameToRgb(rightLight), 0.8)
            : "black",
        }}
      >
        {getLightRgb(rightLight)}
      </button>

      {/* Bottom button */}
      <button
        onClick={onToggleBottom}
        className={cn(
          "absolute -bottom-1 left-1/2 -translate-x-1/2 translate-y-full w-12 p-2 rounded-full font-bold text-sm border-2 select-none",
          bottomLight === null
            ? "bg-black border-white text-white"
            : isLightColor(colorNameToRgb(bottomLight))
              ? "border-black text-black"
              : "border-white text-white",
        )}
        style={
          bottomLight !== null
            ? {
                backgroundColor: rgbToCss(colorNameToRgb(bottomLight), 0.8),
              }
            : {}
        }
      >
        {getLightRgb(bottomLight)}
      </button>
    </>
  );
};
