import { newClient } from "@hunt/public-client";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import apiUrl from "../../../../utils/apiUrl";
import { IS_STATIC_SITE } from "../../../../utils/staticSite";
import { markTaskSolved } from "../../../puzzleSolveLocalState";
import { type RGBColor } from "./beamTypes";
import { mixColors, rgbToHex } from "./beamUtils";
import { SANDBOX_LEVEL } from "./constants";
import type { LightState } from "./useLightSources";

type UsePrismaticSubmissionParams = {
  hasTeamSubmitted: boolean;
  currentLevel: number;
  targetPositions: {
    row: number;
    col: number;
    requiredColor?:
      | "red"
      | "green"
      | "blue"
      | "yellow"
      | "magenta"
      | "cyan"
      | "lightred"
      | "lightgreen"
      | "lightblue"
      | "white";
  }[];
  targetLitStates: Map<
    string,
    { isLit: boolean; actualColor: RGBColor | null }
  >;
  targetBeams: Map<string, RGBColor[]>;
  stillLights: { row: number; col: number; color: RGBColor }[];
  taskSlug: string | undefined;
};

// Shared storage structure
type PrismaticPathsStorage = {
  submitted?: boolean; // Track if task has been submitted
  levelMappings: Record<number, Record<string, string>>; // hex colors
  lightSources?: {
    topLight: LightState;
    leftLight: LightState;
    rightLight: LightState;
    bottomLight: LightState;
  };
};

// Helper function to convert Map to JSON-serializable format
function mapToObject(
  map: Map<number, Map<string, string>>,
): Record<number, Record<string, string>> {
  const obj: Record<number, Record<string, string>> = {};
  for (const [level, mapping] of map.entries()) {
    const levelData: Record<string, string> = {};
    for (const [position, color] of mapping.entries()) {
      levelData[position] = color;
    }
    obj[level] = levelData;
  }
  return obj;
}

// Helper function to convert object back to Map
function objectToMap(
  obj: Record<number, Record<string, string>>,
): Map<number, Map<string, string>> {
  const map = new Map<number, Map<string, string>>();
  for (const [levelStr, levelData] of Object.entries(obj)) {
    const level = Number(levelStr);
    const mapping = new Map<string, string>();
    for (const [position, color] of Object.entries(levelData)) {
      mapping.set(position, color);
    }
    map.set(level, mapping);
  }
  return map;
}

export function usePrismaticSubmission({
  hasTeamSubmitted,
  currentLevel,
  targetPositions,
  targetLitStates,
  targetBeams,
  stillLights,
  taskSlug,
}: UsePrismaticSubmissionParams) {
  const storageKey = `prismatic_paths_${taskSlug ?? "default"}`;

  // Load from localStorage on mount
  const [storage, setStorage] = useState<PrismaticPathsStorage>(() => {
    if (typeof window === "undefined") {
      return { levelMappings: {} };
    }
    try {
      const stored = localStorage.getItem(storageKey);
      if (stored) {
        const parsed = JSON.parse(stored) as PrismaticPathsStorage;
        return parsed;
      }
    } catch (error) {
      console.error("Failed to load from localStorage:", error);
    }
    return { levelMappings: {} };
  });

  // Convert storage.levelMappings to Map for easier use
  const levelMappings = useMemo(() => {
    return objectToMap(storage.levelMappings);
  }, [storage.levelMappings]);

  const setLevelMappings = useCallback(
    (
      updater: (
        prev: Map<number, Map<string, string>>,
      ) => Map<number, Map<string, string>>,
    ) => {
      setStorage((prev) => {
        const currentMap = objectToMap(prev.levelMappings);
        const newMap = updater(currentMap);
        return {
          ...prev,
          levelMappings: mapToObject(newMap),
        };
      });
    },
    [],
  );

  const [showWinAnimation, setShowWinAnimation] = useState(false);
  const [showLevelWinAnimation, setShowLevelWinAnimation] = useState(false);
  const [submissionError, setSubmissionError] = useState<string | undefined>();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const hasAutoSubmittedRef = useRef(false);

  // Save levelMappings to localStorage whenever it changes
  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      // Load existing storage to preserve lightSources and submitted flag
      const existing = localStorage.getItem(storageKey);
      let existingLightSources: PrismaticPathsStorage["lightSources"];
      let existingSubmitted: PrismaticPathsStorage["submitted"];
      if (existing) {
        try {
          const parsed = JSON.parse(existing) as PrismaticPathsStorage;
          existingLightSources = parsed.lightSources;
          existingSubmitted = parsed.submitted;
        } catch {
          // Ignore parse errors
        }
      }
      const toSave: PrismaticPathsStorage = {
        levelMappings: storage.levelMappings,
        lightSources: existingLightSources,
        submitted: existingSubmitted,
      };
      localStorage.setItem(storageKey, JSON.stringify(toSave));
    } catch (error) {
      console.error("Failed to save to localStorage:", error);
    }
  }, [storage.levelMappings, storageKey]);

  // Check if all targets in current level are correctly lit
  const allTargetsLit = useMemo(() => {
    if (targetPositions.length === 0) return false;
    if (currentLevel === SANDBOX_LEVEL) return false; // Sandbox level doesn't count

    return targetPositions.every((targetPos) => {
      const targetKey = `${targetPos.row}-${targetPos.col}`;
      const litState = targetLitStates.get(targetKey);
      return litState?.isLit === true;
    });
  }, [targetPositions, targetLitStates, currentLevel]);

  // Remove level from mappings if it's no longer solved
  useEffect(() => {
    if (currentLevel === SANDBOX_LEVEL) return; // Skip sandbox level
    if (allTargetsLit) return; // Only remove if not solved
    if (!levelMappings.has(currentLevel)) return; // Only remove if it was previously solved

    // Level was previously solved but is no longer solved - remove it
    setLevelMappings((prev) => {
      const newMap = new Map(prev);
      newMap.delete(currentLevel);
      return newMap;
    });
  }, [allTargetsLit, currentLevel, levelMappings, setLevelMappings]);

  // When all targets are lit, store the mapping for this level
  useEffect(() => {
    if (!allTargetsLit || currentLevel === SANDBOX_LEVEL) return; // Skip sandbox level

    // Check if we already have a mapping for this level
    if (levelMappings.has(currentLevel)) return;

    // Trigger level win animation
    setShowLevelWinAnimation(true);

    // Create mapping of target positions to colors (hex strings)
    const mapping = new Map<string, string>();
    for (const targetPos of targetPositions) {
      const targetKey = `${targetPos.row}-${targetPos.col}`;
      const litState = targetLitStates.get(targetKey);
      if (litState?.isLit) {
        // Get the actual color hitting the target
        const colorsHittingTarget = targetBeams.get(targetKey) || [];
        const stillLightMap = new Map<string, RGBColor>();
        for (const stillLight of stillLights) {
          const key = `${stillLight.row}-${stillLight.col}`;
          stillLightMap.set(key, stillLight.color);
        }
        const stillLightColor = stillLightMap.get(targetKey);

        // Mix all colors together
        const allColors: RGBColor[] = [...colorsHittingTarget];
        if (stillLightColor) {
          allColors.push(stillLightColor);
        }

        if (allColors.length > 0) {
          const mixedColor = mixColors(allColors);
          const hexColor = rgbToHex(mixedColor);
          mapping.set(targetKey, hexColor);
        }
      }
    }

    // Store the mapping for this level
    if (mapping.size > 0) {
      setLevelMappings((prev) => {
        const newMap = new Map(prev);
        newMap.set(currentLevel, mapping);
        return newMap;
      });
    }
  }, [
    allTargetsLit,
    currentLevel,
    targetPositions,
    targetLitStates,
    targetBeams,
    stillLights,
    levelMappings,
    setLevelMappings,
  ]);

  const isSubmittingRef = useRef(false);

  const saveSubmittedFlag = useCallback(() => {
    // Save submitted flag to localStorage, preserving all existing data
    if (typeof window !== "undefined") {
      try {
        const existing = localStorage.getItem(storageKey);
        const existingData: PrismaticPathsStorage = existing
          ? (JSON.parse(existing) as PrismaticPathsStorage)
          : { levelMappings: {} };
        existingData.submitted = true;
        // Preserve levelMappings and lightSources
        if (!existingData.levelMappings) {
          existingData.levelMappings = storage.levelMappings;
        }
        if (!existingData.lightSources && storage.lightSources) {
          existingData.lightSources = storage.lightSources;
        }
        localStorage.setItem(storageKey, JSON.stringify(existingData));
      } catch (error) {
        console.error("Failed to save submitted flag:", error);
      }
    }
  }, [storage.levelMappings, storage.lightSources, storageKey]);

  const submitTask = useCallback(
    async (levelMappings: Map<number, Map<string, string>>) => {
      // If already submitted, just show the win animation without hitting the server
      if (hasTeamSubmitted) {
        setShowWinAnimation(true);
        setSubmissionError(undefined);
        saveSubmittedFlag();
        return;
      }

      if (IS_STATIC_SITE) {
        const slug = taskSlug ?? "monarch_the_brights_task";
        markTaskSolved(slug);
        setShowWinAnimation(true);
        setSubmissionError(undefined);
        saveSubmittedFlag();
        return;
      }

      // Prevent multiple simultaneous submissions
      if (isSubmittingRef.current) {
        return;
      }

      // Check if all 3 levels are complete
      const levelsComplete = [2, 3, 4].every((level) =>
        levelMappings.has(level),
      );

      if (!levelsComplete) {
        return;
      }

      isSubmittingRef.current = true;
      setIsSubmitting(true);
      setSubmissionError("Submitting...");

      try {
        const apiClient = newClient(apiUrl(), undefined);
        const response = await apiClient.submitGuess({
          body: { guess: "" },
          params: { slug: taskSlug ?? "monarch_the_brights_task" },
        });

        if (response.status === 200) {
          const solved = response.body.guesses.some(
            (guess) => guess.status === "correct",
          );
          if (solved) {
            setShowWinAnimation(true);
            setSubmissionError(undefined);
            saveSubmittedFlag();
          } else {
            setSubmissionError(
              "An unexpected error occurred submitting the task. Please try again later.",
            );
          }
        } else {
          setSubmissionError(
            "An unexpected error occurred submitting the task. Please try again later.",
          );
        }
      } catch (error: unknown) {
        console.error("Failed to submit task:", error);
        setSubmissionError(
          "An unexpected error occurred submitting the task. Please try again later.",
        );
      } finally {
        isSubmittingRef.current = false;
        setIsSubmitting(false);
      }
    },
    [hasTeamSubmitted, saveSubmittedFlag, taskSlug],
  );

  // Auto-submit when all 3 levels are complete (only once)
  useEffect(() => {
    if (isSubmitting || hasAutoSubmittedRef.current) return;

    try {
      if (typeof window !== "undefined" && "localStorage" in window) {
        const stored = localStorage.getItem(storageKey);
        if (stored) {
          const parsed = JSON.parse(stored) as PrismaticPathsStorage;
          if (parsed.submitted) {
            return;
          }
        }
      }
    } catch {
      // Ignore storage/parsing errors and proceed with auto-submit logic
    }
    const levelsComplete = [2, 3, 4].every((level) => levelMappings.has(level));

    if (levelsComplete) {
      hasAutoSubmittedRef.current = true;
      void submitTask(levelMappings);
    }
  }, [levelMappings, hasTeamSubmitted, isSubmitting, submitTask, storageKey]);

  return {
    showWinAnimation,
    setShowWinAnimation,
    showLevelWinAnimation,
    setShowLevelWinAnimation,
    submissionError,
    levelMappings,
  };
}
