import { CAT_POSITIONS, TOY_TO_DIGIT, TOY_POSITIONS } from "./constants";

// Get digit from toy name
export const getDigitFromToy = (toy: string): number | null => {
  return TOY_TO_DIGIT[toy] ?? null;
};

// Check if digit appears in time string (HH:MM format)
export const digitInTime = (digit: number, timeString: string): boolean => {
  return timeString.includes(digit.toString());
};

// Format time as HH:MM
export const formatTime = (date: Date): string => {
  const hours = date.getHours().toString().padStart(2, "0");
  const minutes = date.getMinutes().toString().padStart(2, "0");
  return `${hours}:${minutes}`;
};

// Get the position for a specific toy
export const getPositionForToy = (
  toy: string,
): { x: number; y: number; width: number } | null => {
  return TOY_POSITIONS[toy] ?? null;
};

// Get the position for a cat (by cat index)
export const getPositionForCat = (
  catIndex: number,
): { x: number; y: number; width: number } | null => {
  return CAT_POSITIONS[catIndex] ?? null;
};
