import { cn } from "@hunt/styled-ui";
import { useEffect, useState } from "react";

// Constants
const TYPING_SPEED = 50; // milliseconds per character

type TypewriterDialogProps = {
  text: string;
  className?: string;
  showEffect?: boolean;
};

export default function TypewriterDialog({
  text,
  className,
  showEffect = true,
}: TypewriterDialogProps) {
  const [displayedText, setDisplayedText] = useState("");

  useEffect(() => {
    if (!showEffect) {
      setDisplayedText(text);
      return;
    }

    // Reset when text changes
    setDisplayedText("");

    let currentIndex = 0;

    const typeText = () => {
      if (currentIndex < text.length) {
        setDisplayedText(text.slice(0, currentIndex + 1));
        currentIndex++;
      } else {
        clearInterval(interval);
      }
    };

    const interval = setInterval(typeText, TYPING_SPEED);

    return () => {
      clearInterval(interval);
    };
  }, [showEffect, text]);

  return (
    // Actual dialog with fixed width
    <div
      className={cn(
        "text-lg bg-white rounded-full text-black px-6 py-2 border-2 border-black",
        className,
      )}
    >
      <div className="relative">
        <span className="absolute top-0 left-0">{displayedText}</span>
        <span className="invisible">{text}</span>
      </div>
    </div>
  );
}
