import {
  type PuzzmonPreferences,
  type CriterionWithScore,
  type TileSection,
  type Tile,
} from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import { GridTab } from "./GridTab";
import { PreferencesTab } from "./PreferencesTab";
import { ScoringTab } from "./ScoringTab";

type TaskFolderTabsProps = {
  activeTab: "loading" | "grid" | "preferences" | "scoring";
  gridState: (Tile | null)[][];
  tiles: TileSection[];
  scoringCriteria: CriterionWithScore[];
  preferences: PuzzmonPreferences[];
  score: number;
  goal: number;
  handleTilePlace: (
    tile: Tile & { fromGrid?: boolean; gridRow?: number; gridCol?: number },
    row: number,
    col: number,
  ) => void;
  handleTileRemove: (row: number, col: number) => void;
  handleReset: () => void;
};

function TaskFolderTabs({
  activeTab,
  gridState,
  tiles,
  score,
  goal,
  scoringCriteria,
  preferences,
  handleTilePlace,
  handleTileRemove,
  handleReset,
}: TaskFolderTabsProps) {
  const renderContent = () => {
    switch (activeTab) {
      case "grid":
        return (
          <GridTab
            gridState={gridState}
            tiles={tiles}
            preferencesData={preferences}
            score={score}
            goal={goal}
            handleTilePlace={handleTilePlace}
            handleTileRemove={handleTileRemove}
            handleReset={handleReset}
          />
        );
      case "preferences":
        return (
          <PreferencesTab score={score} goal={goal} preferences={preferences} />
        );
      case "scoring":
        return (
          <ScoringTab score={score} goal={goal} criteria={scoringCriteria} />
        );
      default:
        return null;
    }
  };

  return (
    <div
      className={cn(
        "h-full rounded-2xl border-[#FFE100] border-2 -mt-0.5",
        "bg-[#D5B893]",
      )}
    >
      {renderContent()}
    </div>
  );
}

export default TaskFolderTabs;
