import { useDraggable } from "@dnd-kit/core";
import { type Tile } from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import React from "react";

export const TILE_STYLE = "w-20 h-20";

type DraggableTileProps = {
  tile: Tile;
};

const DraggableTile: React.FC<DraggableTileProps> = ({ tile }) => {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: `tile-list-${tile.id}`,
    data: tile,
  });

  return (
    <div
      ref={setNodeRef}
      {...attributes}
      {...listeners}
      className={cn(TILE_STYLE, "cursor-grab")}
      style={isDragging ? { transform: "none" } : undefined}
    >
      <img
        src={tile.image}
        alt={tile.name}
        className="w-full h-full object-contain"
      />
    </div>
  );
};

type TileSectionProps = {
  title: string;
  tiles: Tile[];
};

const TileSection: React.FC<TileSectionProps> = ({ title, tiles }) => {
  return (
    <div>
      <h4 className="text-md font-semibold text-secondary mb-1">{title}</h4>
      <div className="flex flex-wrap gap-2 select-none">
        {tiles.map((tile) => (
          <DraggableTile key={tile.id} tile={tile} />
        ))}
      </div>
    </div>
  );
};

type TileListProps = {
  sections: { title: string; tiles: Tile[] }[];
};

export const TileList: React.FC<TileListProps> = ({ sections }) => {
  return (
    <div className="h-full w-full overflow-y-auto flex flex-col gap-4 pr-3">
      {sections.map((section) => (
        <TileSection
          key={section.title}
          title={section.title}
          tiles={section.tiles}
        />
      ))}
    </div>
  );
};
