  targetImage?: string;
  targetImageSolved?: string;
  targetLitStates?: Map<
    string,
    { isLit: boolean; actualColor: RGBColor | null }
  >; // Map of "row-col" to lit state and actual color
  lightSources?: LightSource[]; // Light sources for the grid
  isSandbox?: boolean; // Whether this is the sandbox level
