// Component to render glowy border around puzzmon
const PuzzmonBorder: React.FC<{
  beamInfo: PuzzmonBeamInfo;
}> = ({ beamInfo }) => {
  // Get incoming colors for borders (beams coming INTO the puzzmon)
  // When a beam with direction "down" enters a cell, it hits the TOP
  // When a beam with direction "up" enters a cell, it hits the BOTTOM
  // When a beam with direction "right" enters a cell, it hits the LEFT
  // When a beam with direction "left" enters a cell, it hits the RIGHT
  const topIncoming = beamInfo.incoming.get("down") || [];
  const topIncomingColor =
    topIncoming.length > 0 ? mixColors(topIncoming) : null;

  const bottomIncoming = beamInfo.incoming.get("up") || [];
  const bottomIncomingColor =
    bottomIncoming.length > 0 ? mixColors(bottomIncoming) : null;

  const leftIncoming = beamInfo.incoming.get("right") || [];
  const leftIncomingColor =
    leftIncoming.length > 0 ? mixColors(leftIncoming) : null;

  const rightIncoming = beamInfo.incoming.get("left") || [];
  const rightIncomingColor =
    rightIncoming.length > 0 ? mixColors(rightIncoming) : null;

  // Get outgoing colors for indicators (beams going OUT from the puzzmon)
  const topOutgoing = beamInfo.outgoing.get("up") || [];
  const topOutgoingColor =
    topOutgoing.length > 0 ? mixColors(topOutgoing) : null;

  const bottomOutgoing = beamInfo.outgoing.get("down") || [];
  const bottomOutgoingColor =
    bottomOutgoing.length > 0 ? mixColors(bottomOutgoing) : null;

  const leftOutgoing = beamInfo.outgoing.get("left") || [];
  const leftOutgoingColor =
    leftOutgoing.length > 0 ? mixColors(leftOutgoing) : null;

  const rightOutgoing = beamInfo.outgoing.get("right") || [];
  const rightOutgoingColor =
    rightOutgoing.length > 0 ? mixColors(rightOutgoing) : null;

  const borderWidth = 5;
  const indicatorSize = 5; // Size of beam indicator triangles

  // Helper to create arrow indicator pointing inward (for incoming beams)
  const createIncomingIndicator = (
    direction: "top" | "bottom" | "left" | "right",
    color: RGBColor,
  ) => {
    const arrowColor = rgbToCss(color, 1);
    let arrowStyle: React.CSSProperties = {};
    let position: React.CSSProperties = {};

    switch (direction) {
      case "top":
        // Arrow pointing down (incoming from top)
        arrowStyle = {
          borderTop: `${indicatorSize}px solid ${arrowColor}`,
          borderLeft: `${indicatorSize}px solid transparent`,
          borderRight: `${indicatorSize}px solid transparent`,
        };
        position = {
          top: `${borderWidth + 2}px`,
          left: "50%",
          transform: "translateX(-50%)",
        };
        break;
      case "bottom":
        // Arrow pointing up (incoming from bottom)
        arrowStyle = {
          borderBottom: `${indicatorSize}px solid ${arrowColor}`,
          borderLeft: `${indicatorSize}px solid transparent`,
          borderRight: `${indicatorSize}px solid transparent`,
        };
        position = {
          bottom: `${borderWidth + 2}px`,
          left: "50%",
          transform: "translateX(-50%)",
        };
        break;
      case "left":
        // Arrow pointing right (incoming from left)
        arrowStyle = {
          borderLeft: `${indicatorSize}px solid ${arrowColor}`,
          borderTop: `${indicatorSize}px solid transparent`,
          borderBottom: `${indicatorSize}px solid transparent`,
        };
        position = {
          left: `${borderWidth + 2}px`,
          top: "50%",
          transform: "translateY(-50%)",
        };
        break;
      case "right":
        // Arrow pointing left (incoming from right)
        arrowStyle = {
          borderRight: `${indicatorSize}px solid ${arrowColor}`,
          borderTop: `${indicatorSize}px solid transparent`,
          borderBottom: `${indicatorSize}px solid transparent`,
        };
        position = {
          right: `${borderWidth + 2}px`,
          top: "50%",
          transform: "translateY(-50%)",
        };
        break;
    }

    return (
      <div
        className="absolute"
        style={{
          ...position,
          width: 0,
          height: 0,
          ...arrowStyle,
          zIndex: 7,
        }}
      />
    );
  };

  // Helper to create arrow indicator pointing outward (for outgoing beams)
  const createOutgoingIndicator = (
    direction: "top" | "bottom" | "left" | "right",
    color: RGBColor,
  ) => {
    const arrowColor = rgbToCss(color, 1);
    let arrowStyle: React.CSSProperties = {};
    let position: React.CSSProperties = {};

    switch (direction) {
      case "top":
        // Arrow pointing up (outgoing)
        arrowStyle = {
          borderBottom: `${indicatorSize}px solid ${arrowColor}`,
          borderLeft: `${indicatorSize}px solid transparent`,
          borderRight: `${indicatorSize}px solid transparent`,
        };
        position = {
          top: `${borderWidth + 2}px`,
          left: "50%",
          transform: "translateX(-50%)",
        };
        break;
      case "bottom":
        // Arrow pointing down (outgoing)
        arrowStyle = {
          borderTop: `${indicatorSize}px solid ${arrowColor}`,
          borderLeft: `${indicatorSize}px solid transparent`,
          borderRight: `${indicatorSize}px solid transparent`,
        };
        position = {
          bottom: `${borderWidth + 2}px`,
          left: "50%",
          transform: "translateX(-50%)",
        };
        break;
      case "left":
        // Arrow pointing left (outgoing)
        arrowStyle = {
          borderRight: `${indicatorSize}px solid ${arrowColor}`,
          borderTop: `${indicatorSize}px solid transparent`,
          borderBottom: `${indicatorSize}px solid transparent`,
        };
        position = {
          left: `${borderWidth + 2}px`,
          top: "50%",
          transform: "translateY(-50%)",
        };
        break;
      case "right":
        // Arrow pointing right (outgoing)
        arrowStyle = {
          borderLeft: `${indicatorSize}px solid ${arrowColor}`,
          borderTop: `${indicatorSize}px solid transparent`,
          borderBottom: `${indicatorSize}px solid transparent`,
        };
        position = {
          right: `${borderWidth + 2}px`,
          top: "50%",
          transform: "translateY(-50%)",
        };
        break;
    }

    return (
      <div
        className="absolute"
        style={{
          ...position,
          width: 0,
          height: 0,
          ...arrowStyle,
          zIndex: 7,
        }}
      />
    );
  };

  return (
    <div className="absolute inset-0 pointer-events-none" style={{ zIndex: 6 }}>
      {/* Top border - shows incoming beam from top */}
      {topIncomingColor && (
        <div
          className="absolute top-0 left-0 right-0"
          style={{
            height: `${borderWidth}px`,
            background: rgbToCss(topIncomingColor, 0.8),
          }}
        />
      )}
      {/* Top border - shows outgoing beam going up */}
      {topOutgoingColor && (
        <div
          className="absolute top-0 left-0 right-0"
          style={{
            height: `${borderWidth}px`,
            background: rgbToCss(topOutgoingColor, 0.8),
          }}
        />
      )}
      {/* Top incoming indicator - triangle pointing inward */}
      {topIncomingColor && createIncomingIndicator("top", topIncomingColor)}
      {/* Top outgoing indicator - triangle pointing outward */}
      {topOutgoingColor && createOutgoingIndicator("top", topOutgoingColor)}

      {/* Bottom border - shows incoming beam from bottom */}
      {bottomIncomingColor && (
        <div
          className="absolute bottom-0 left-0 right-0"
          style={{
            height: `${borderWidth}px`,
            background: rgbToCss(bottomIncomingColor, 0.8),
          }}
        />
      )}
      {/* Bottom border - shows outgoing beam going down */}
      {bottomOutgoingColor && (
        <div
          className="absolute bottom-0 left-0 right-0"
          style={{
            height: `${borderWidth}px`,
            background: rgbToCss(bottomOutgoingColor, 0.8),
          }}
        />
      )}
      {/* Bottom incoming indicator - triangle pointing inward */}
      {bottomIncomingColor &&
        createIncomingIndicator("bottom", bottomIncomingColor)}
      {/* Bottom outgoing indicator - triangle pointing outward */}
      {bottomOutgoingColor &&
        createOutgoingIndicator("bottom", bottomOutgoingColor)}

      {/* Left border - shows incoming beam from left */}
      {leftIncomingColor && (
        <div
          className="absolute top-0 bottom-0 left-0"
          style={{
            width: `${borderWidth}px`,
            background: rgbToCss(leftIncomingColor, 0.8),
          }}
        />
      )}
      {/* Left border - shows outgoing beam going left */}
      {leftOutgoingColor && (
        <div
          className="absolute top-0 bottom-0 left-0"
          style={{
            width: `${borderWidth}px`,
            background: rgbToCss(leftOutgoingColor, 0.8),
          }}
        />
      )}
      {/* Left incoming indicator - triangle pointing inward */}
      {leftIncomingColor && createIncomingIndicator("left", leftIncomingColor)}
      {/* Left outgoing indicator - triangle pointing outward */}
      {leftOutgoingColor && createOutgoingIndicator("left", leftOutgoingColor)}

      {/* Right border - shows incoming beam from right */}
      {rightIncomingColor && (
        <div
          className="absolute top-0 bottom-0 right-0"
          style={{
            width: `${borderWidth}px`,
            background: rgbToCss(rightIncomingColor, 0.8),
          }}
        />
      )}
      {/* Right border - shows outgoing beam going right */}
      {rightOutgoingColor && (
        <div
          className="absolute top-0 bottom-0 right-0"
          style={{
            width: `${borderWidth}px`,
            background: rgbToCss(rightOutgoingColor, 0.8),
          }}
        />
      )}
      {/* Right incoming indicator - triangle pointing inward */}
      {rightIncomingColor &&
        createIncomingIndicator("right", rightIncomingColor)}
      {/* Right outgoing indicator - triangle pointing outward */}
      {rightOutgoingColor &&
        createOutgoingIndicator("right", rightOutgoingColor)}
    </div>
  );
};

// ============================================================================
// Target Indicator Component
// ============================================================================

/**
 * Converts a color name to RGB combination text for tooltips
 */
function getRgbCombinationText(
  color:
    | "red"
    | "green"
    | "blue"
    | "yellow"
    | "magenta"
    | "cyan"
    | "lightred"
    | "lightgreen"
    | "lightblue"
    | "white",
): string {
  switch (color) {
    case "red":
      return "R";
    case "green":
      return "G";
    case "blue":
      return "B";
    case "yellow":
      return "RG";
    case "magenta":
      return "RB";
    case "cyan":
      return "GB";
    case "lightred":
      return "RRGB";
    case "lightgreen":
      return "RGGB";
    case "lightblue":
      return "RGBB";
    case "white":
      return "RGB";
    default:
      return "";
  }
}

const TargetIndicator: React.FC<{
  requiredColor: ColorName;
  isLit: boolean;
  actualColor?: RGBColor | null; // Actual color received (if doesn't match required)
}> = ({ requiredColor, isLit, actualColor }) => {
  const colorRgb = colorNameToRgb(requiredColor);
  const borderColor = rgbToCss(colorRgb, 0.8);
  const rgbText = getRgbCombinationText(requiredColor);

  return (
    <ConditionalTooltip
      tooltip={
        <div className="text-center">
          Needs: {rgbText}
          <br />
          Received: {actualColor ? rgbToComponents(actualColor) : "N/A"}
        </div>
      }
      className="z-[101] bg-white text-black"
      disableHoverableContent={true}
    >
      <div
        className="absolute inset-0 pointer-events-auto"
        style={{ zIndex: 9 }}
      >
        {/* Colored square border showing required color */}
        <div
          className="absolute inset-0"
          style={{
            border: `3px solid ${borderColor}`,
            boxShadow: `inset 0 0 6px ${rgbToCss(colorRgb, 0.3)}`,
            backgroundColor: isLit
              ? rgbToCss(colorRgb, 0.6)
              : rgbToCss(colorRgb, 0.25),
          }}
        />
        {/* Indicator badge showing actual mixed color with checkmark (correct) or X (incorrect) */}
        {actualColor && (
          <div
            className="absolute top-0 right-0 rounded-full flex items-center justify-center"
            style={{
              width: "28%",
              height: "28%",
              minWidth: "20px",
              minHeight: "20px",
              backgroundColor: rgbToCss(actualColor, 1),
              border: `2px solid ${rgbToCss(actualColor, 1)}`,
              transform: "translate(20%, -20%)",
            }}
          >
            {isLit ? (
              <Check
                size={16}
                className={
                  isLightColor(actualColor) ? "text-black" : "text-white"
                }
                strokeWidth={3}
              />
            ) : (
              <X
                size={16}
                className={
                  isLightColor(actualColor) ? "text-black" : "text-white"
                }
                strokeWidth={3}
              />
            )}
          </div>
        )}
      </div>
    </ConditionalTooltip>
  );
};

// ============================================================================
// Grid Components
