const GridPuzzmonTile: React.FC<{
  puzzmon: GridPuzzmon;
  row: number;
  col: number;
  onRemove: (row: number, col: number) => void;
  beamInfo?: PuzzmonBeamInfo;
}> = ({ puzzmon, row, col, onRemove: _onRemove, beamInfo }) => {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: `grid-puzzmon-${row}-${col}`,
    data: {
      ...puzzmon,
      fromGrid: true,
      gridRow: row,
      gridCol: col,
    },
  });

  return (
    <div
      ref={setNodeRef}
      className="relative w-full h-full flex items-center justify-center"
      style={{ padding: "15%" }} // Add padding to make puzzmon smaller
    >
      {beamInfo && <PuzzmonBorder beamInfo={beamInfo} />}
      <img
        {...attributes}
        {...listeners}
        className={cn(
          "w-full h-full object-contain cursor-grab relative select-none",
          isDragging && "opacity-40",
        )}
        style={isDragging ? { zIndex: 7, transform: "none" } : { zIndex: 7 }}
        alt={puzzmon.name}
        src={puzzmon.image}
      />
    </div>
  );
};

const GridCell: React.FC<GridCellProps> = ({
  row,
  col,
  puzzmon,
  onDrop: _onDrop,
  onRemove,
  draggedPuzzmon,
  isTarget,
  targetImage,
  targetImageSolved,
  isTargetLit,
  requiredColor,
  actualColor,
  beamInfo,
}) => {
  // Prevent dropping on Target positions
  const canDrop = !isTarget;

  const { setNodeRef, isOver } = useDroppable({
    id: `grid-cell-${row}-${col}`,
    data: {
      row,
      col,
      type: "grid-cell",
    },
    disabled: !canDrop,
  });

  const showPreview = isOver && draggedPuzzmon && !puzzmon && canDrop;
  const isSameCell =
    draggedPuzzmon?.fromGrid &&
    draggedPuzzmon.gridRow === row &&
    draggedPuzzmon.gridCol === col;

  return (
    <div
      ref={setNodeRef}
      className={cn(
        "relative aspect-square flex items-center justify-center bg-transparent",
        isOver && !isSameCell && "ring-2 ring-blue-400 ring-inset",
      )}
    >
      {/* Target display */}
      {isTarget && targetImage && (
        <>
          {requiredColor && (
            <TargetIndicator
              requiredColor={requiredColor}
              isLit={isTargetLit ?? false}
              actualColor={actualColor}
            />
          )}
          <div
            className="absolute inset-0 flex items-center justify-center pointer-events-none"
            style={{ zIndex: 10, padding: "15%" }}
          >
            <img
              src={isTargetLit ? targetImageSolved : targetImage}
              alt="Target Puzzmon"
              className="w-full h-full object-contain select-none"
            />
          </div>
        </>
      )}

      {puzzmon && (
        <GridPuzzmonTile
          puzzmon={puzzmon}
          row={row}
          col={col}
          onRemove={onRemove}
          beamInfo={beamInfo}
        />
      )}
      {showPreview && draggedPuzzmon && (
        <div
          className="absolute inset-0 flex items-center justify-center"
          style={{ padding: "15%" }}
        >
          <img
            className="w-full h-full object-contain opacity-50"
            alt={draggedPuzzmon.name}
            src={draggedPuzzmon.image}
          />
        </div>
      )}
    </div>
  );
};

// Component to render still light as a glowy circle
const StillLightCircle: React.FC<{
  stillLight: StillLight;
  gridRows: number;
  gridCols: number;
}> = ({ stillLight, gridRows, gridCols }) => {
  const cellWidthPercent = (100 / gridCols) * 0.6;
  const cellHeightPercent = (100 / gridRows) * 0.6;

  const cssColor = rgbToCss(stillLight.color, 0.8);
  const glowColor1 = rgbToCss(stillLight.color, 0.5);
  const glowColor2 = rgbToCss(stillLight.color, 0.3);
  const glowColor3 = rgbToCss(stillLight.color, 0.2);

  const style: React.CSSProperties = {
    position: "absolute",
    pointerEvents: "none",
    left: `calc(${stillLight.col} * (100% / ${gridCols}) + (100% / ${gridCols} / 2) - ${cellWidthPercent}% / 2)`,
    top: `calc(${stillLight.row} * (100% / ${gridRows}) + (100% / ${gridRows} / 2) - ${cellHeightPercent}% / 2)`,
    width: `${cellWidthPercent}%`,
    height: `${cellHeightPercent}%`,
    borderRadius: "50%",
    backgroundColor: cssColor,
    boxShadow: `
      0 0 8px ${glowColor1},
      0 0 16px ${glowColor2},
      0 0 24px ${glowColor2},
      0 0 32px ${glowColor3},
      inset 0 0 8px ${glowColor1}
    `,
    mixBlendMode: "screen",
    zIndex: 4,
    // Create uneven border effect using multiple box-shadows
    border: `2px solid ${cssColor}`,
  };

  return <div style={style} />;
};

// Component to render a continuous light beam path
const LightBeamPath: React.FC<{
  path: ContinuousBeamPath;
  gridRows: number;
  gridCols: number;
}> = ({ path, gridRows, gridCols }) => {
  const cellWidthPercent = 100 / gridCols;
  const cellHeightPercent = 100 / gridRows;
  const beamWidthPercent = cellWidthPercent / 3; // 1/3 of cell width
  const beamHeightPercent = cellHeightPercent / 3; // 1/3 of cell height

  // Glowy and semi-transparent
  const cssColor = rgbToCss(path.color, 0.7);
  const glowColor1 = rgbToCss(path.color, 0.4);
  const glowColor2 = rgbToCss(path.color, 0.3);
  const glowColor3 = rgbToCss(path.color, 0.2);

  const style: React.CSSProperties = {
    position: "absolute",
    pointerEvents: "none",
    backgroundColor: cssColor,
    // Multiple layers of glow for more intense effect
    boxShadow: `
      0 0 4px ${glowColor1},
      0 0 8px ${glowColor2},
      0 0 16px ${glowColor2},
      0 0 24px ${glowColor3}
    `,
    // Use screen blend mode for additive-like color mixing at intersections
    mixBlendMode: "screen",
    zIndex: 5,
  };

  // Calculate start and end positions based on direction
  // Paths span exactly from start cell to end cell (inclusive)
  switch (path.direction) {
    case "down":
      // Vertical beam from startRow to endRow
      style.left = `calc(${path.startCol} * (100% / ${gridCols}) + (100% / ${gridCols} / 2) - (100% / ${gridCols} / 3 / 2))`;
      style.top = `${path.startRow * cellHeightPercent}%`;
      style.width = `${beamWidthPercent}%`;
      // Height spans from start to end cell (inclusive), plus one cell height
      style.height = `${(path.endRow - path.startRow + 1) * cellHeightPercent}%`;
      break;
    case "up":
      // Vertical beam from endRow to startRow (reversed)
      style.left = `calc(${path.startCol} * (100% / ${gridCols}) + (100% / ${gridCols} / 2) - (100% / ${gridCols} / 3 / 2))`;
      style.top = `${path.endRow * cellHeightPercent}%`;
      style.width = `${beamWidthPercent}%`;
      style.height = `${(path.startRow - path.endRow + 1) * cellHeightPercent}%`;
      break;
    case "right":
      // Horizontal beam from startCol to endCol
      style.left = `${path.startCol * cellWidthPercent}%`;
      style.top = `calc(${path.startRow} * (100% / ${gridRows}) + (100% / ${gridRows} / 2) - (100% / ${gridRows} / 3 / 2))`;
      style.width = `${(path.endCol - path.startCol + 1) * cellWidthPercent}%`;
      style.height = `${beamHeightPercent}%`;
      break;
    case "left":
      // Horizontal beam from endCol to startCol (reversed)
      style.left = `${path.endCol * cellWidthPercent}%`;
      style.top = `calc(${path.startRow} * (100% / ${gridRows}) + (100% / ${gridRows} / 2) - (100% / ${gridRows} / 3 / 2))`;
      style.width = `${(path.startCol - path.endCol + 1) * cellWidthPercent}%`;
      style.height = `${beamHeightPercent}%`;
      break;
  }

  return <div style={style} />;
};

