export const PrismaticGrid: React.FC<PrismaticGridProps> = ({
  onPuzzmonPlace,
  onPuzzmonRemove,
  gridState,
  draggedPuzzmon,
  targetPositions,
  targetImage,
  targetImageSolved,
  targetLitStates,
  lightSources,
  isSandbox = false,
}) => {
  const GRID_ROWS = 5;
  const GRID_COLS = 7;

  // Calculate all light beams
  const {
    paths: lightBeams,
    puzzmonBeams,
    stillLights,
  } = useMemo(() => {
    return calculateLightBeams(
      gridState,
      GRID_ROWS,
      GRID_COLS,
      targetPositions.map((pos) => ({ row: pos.row, col: pos.col })),
      lightSources,
    );
  }, [gridState, targetPositions, lightSources]);

  return (
    <div
      className="max-h-full max-w-full flex grow items-start justify-center relative"
      style={{ aspectRatio: "7/5" }}
    >
      <style>{`
        @keyframes pulse-glow {
          0%, 100% {
            opacity: 1;
            transform: scale(1);
          }
          50% {
            opacity: 0.85;
            transform: scale(1.015);
          }
        }
        @keyframes fade-in {
          from {
            opacity: 0;
            transform: scale(0.8);
          }
          to {
            opacity: 1;
            transform: scale(1);
          }
        }
      `}</style>
      <div
        className="relative max-w-full max-h-full h-full grid grid-cols-7 grid-rows-5 gap-0 bg-black"
        style={{ aspectRatio: "7/5" }}
      >
        {/* Default lightbulb only shown when not in sandbox mode (backward compatibility) */}
        {!isSandbox && (
          <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2">
            <Lightbulb size={32} />
          </div>
        )}

        {/* Render all continuous light beam paths */}
        {lightBeams.map((path, index) => (
          <LightBeamPath
            key={`beam-${path.startRow}-${path.startCol}-${path.endRow}-${path.endCol}-${path.direction}-${index}`}
            path={path}
            gridRows={GRID_ROWS}
            gridCols={GRID_COLS}
          />
        ))}

        {/* Render all still light circles */}
        {stillLights.map((stillLight, index) => (
          <StillLightCircle
            key={`still-light-${stillLight.row}-${stillLight.col}-${index}`}
            stillLight={stillLight}
            gridRows={GRID_ROWS}
            gridCols={GRID_COLS}
          />
        ))}

        {gridState.map((row, rowIndex) =>
          row.map((puzzmon, colIndex) => {
            const targetPos = targetPositions.find(
              (pos) => pos.row === rowIndex && pos.col === colIndex,
            );
            const isTarget = !!targetPos;
            const targetKey = `${rowIndex}-${colIndex}`;
            const targetState = isTarget
              ? targetLitStates?.get(targetKey)
              : undefined;
            const isTargetLit = targetState?.isLit ?? false;
            const actualColor = targetState?.actualColor ?? null;
            const beamInfo = puzzmon ? puzzmonBeams.get(targetKey) : undefined;

            return (
              <GridCell
                key={`${rowIndex}-${colIndex}`}
                row={rowIndex}
                col={colIndex}
                puzzmon={puzzmon}
                onDrop={onPuzzmonPlace}
                onRemove={onPuzzmonRemove}
                draggedPuzzmon={draggedPuzzmon}
                isTarget={isTarget}
                targetImage={targetImage}
                targetImageSolved={targetImageSolved}
                isTargetLit={isTargetLit}
                requiredColor={targetPos?.requiredColor}
                actualColor={actualColor}
                beamInfo={beamInfo}
              />
            );
          }),
        )}
      </div>
    </div>
  );
};
