import {
  DndContext,
  DragOverlay,
  useSensors,
  useSensor,
  PointerSensor,
  pointerWithin,
  type DragStartEvent,
  type DragEndEvent,
} from "@dnd-kit/core";
import { snapCenterToCursor } from "@dnd-kit/modifiers";
import { cn } from "@hunt/styled-ui";
import { Check, RotateCcw } from "lucide-react";
import React, { useState, useCallback, useMemo, useEffect } from "react";
import { createPortal } from "react-dom";
import { BackToArchiveButton } from "../../components/MonarchButton";
import MonarchTaskWrapper from "../MonarchTaskWrapper";
import TaskSolvedMessage from "../TaskSolvedMessage";
import TaskSuccessAnimation from "../TaskSuccessAnimation";
import { type MonarchTaskProps } from "../monarch_tasks_defs";
import LevelWinAnimation from "./LevelWinAnimation";
import { LightSourceButtons } from "./LightSourceButtons";
import { PrismaticGrid } from "./PrismaticGrid";
import { PuzzmonList } from "./PuzzmonList";
import { calculateLightBeams } from "./beamCalculation";
import { type RGBColor } from "./beamTypes";
import { colorNameToRgb, mixColors, type ColorName } from "./beamUtils";
import { PRISMATIC_PATHS_STORAGE_KEY, SANDBOX_LEVEL } from "./constants";
import { getData } from "./data";
import { type GridPuzzmon } from "./types";
import { useGridState } from "./useGridState";
import { useLightSources, type LightState } from "./useLightSources";
import { usePrismaticSubmission } from "./usePrismaticSubmission";

function PrismaticPathsTask({
  returnToArchive,
  puzzmonData: _puzzmonData,
  backgroundImageSrc: _backgroundImageSrc,
  teamState,
  taskSlug,
}: MonarchTaskProps) {
  const [currentLevel, setCurrentLevel] = useState(1);
  const [draggedPuzzmon, setDraggedPuzzmon] = useState<
    | (GridPuzzmon & {
        fromGrid?: boolean;
        gridRow?: number;
        gridCol?: number;
      })
    | null
  >(null);

  const hasTeamSubmitted = !!teamState?.puzzles[taskSlug ?? ""]?.solved;

  // Get initial light sources from storage (before other calculations)
  const initialLightSources = useMemo(() => {
    if (typeof window === "undefined") {
      return {
        topLight: (currentLevel === SANDBOX_LEVEL
          ? "white"
          : null) as LightState,
        leftLight: null as LightState,
        rightLight: null as LightState,
        bottomLight: null as LightState,
      };
    }
    try {
      const stored = localStorage.getItem(PRISMATIC_PATHS_STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored) as unknown;
        if (
          typeof parsed === "object" &&
          parsed !== null &&
          !Array.isArray(parsed) &&
          "lightSources" in parsed
        ) {
          const lightSources = (
            parsed as {
              lightSources?: {
                topLight: LightState;
                leftLight: LightState;
                rightLight: LightState;
                bottomLight: LightState;
              };
            }
          ).lightSources;
          if (lightSources) {
            return lightSources;
          }
        }
      }
    } catch (error) {
      console.error("Failed to load light sources from localStorage:", error);
    }
    return {
      topLight: (currentLevel === SANDBOX_LEVEL ? "white" : null) as LightState,
      leftLight: null as LightState,
      rightLight: null as LightState,
      bottomLight: null as LightState,
    };
  }, [currentLevel]);

  // Light source management - use shared storage
  const {
    topLight,
    leftLight,
    rightLight,
    bottomLight,
    setTopLight,
    setLeftLight,
    setRightLight,
    setBottomLight,
    toggleLight,
    lightSources,
  } = useLightSources(currentLevel, {
    initialLightSources,
    onLightSourcesChange: (newLightSources: {
      topLight: LightState;
      leftLight: LightState;
      rightLight: LightState;
      bottomLight: LightState;
    }) => {
      // Save to localStorage
      if (typeof window !== "undefined") {
        try {
          const stored = localStorage.getItem(PRISMATIC_PATHS_STORAGE_KEY);
          let currentStorage: {
            levelMappings?: Record<number, Record<string, ColorName>>;
            lightSources?: {
              topLight: LightState;
              leftLight: LightState;
              rightLight: LightState;
              bottomLight: LightState;
            };
          };
          if (stored) {
            const parsed = JSON.parse(stored) as unknown;
            if (
              typeof parsed === "object" &&
              parsed !== null &&
              !Array.isArray(parsed)
            ) {
              currentStorage = parsed as {
                levelMappings?: Record<number, Record<string, ColorName>>;
                lightSources?: {
                  topLight: LightState;
                  leftLight: LightState;
                  rightLight: LightState;
                  bottomLight: LightState;
                };
              };
            } else {
              currentStorage = { levelMappings: {} };
            }
          } else {
            currentStorage = { levelMappings: {} };
          }
          currentStorage.lightSources = newLightSources;
          localStorage.setItem(
            PRISMATIC_PATHS_STORAGE_KEY,
            JSON.stringify(currentStorage),
          );
        } catch (error) {
          console.error("Failed to save light sources to localStorage:", error);
        }
      }
    },
  });

  const taskData = getData();
  const { gridState, handlePuzzmonPlace, handlePuzzmonRemove, handleReset } =
    useGridState(currentLevel);

  // Get puzzmon data for current level from server
  const availablePuzzmon = useMemo(() => {
    if (!taskData) return [];

    const levelConfig = taskData.levels.find((c) => c.level === currentLevel);
    if (!levelConfig) return [];

    return levelConfig.availablePuzzmon.map((p) => ({
      ...p,
      row: -1, // Not on grid yet
      col: -1,
    })) as GridPuzzmon[];
  }, [taskData, currentLevel]);

  // Get Target positions for current level from server
  const targetPositions = useMemo(() => {
    if (!taskData) return [];

    const levelData = taskData.targetPositions.find(
      (p) => p.level === currentLevel,
    );
    return levelData?.positions ?? [];
  }, [taskData, currentLevel]);

  // Get Target image data from server
  const targetData = useMemo(() => {
    if (!taskData) {
      return { image: "", imageSolved: "" };
    }
    return taskData.targetImages;
  }, [taskData]);

  // Calculate light beams
  const { targetBeams, stillLights } = useMemo(() => {
    return calculateLightBeams(
      gridState,
      5,
      7,
      targetPositions.map((pos) => ({ row: pos.row, col: pos.col })),
      lightSources,
    );
  }, [gridState, targetPositions, lightSources]);

  // Calculate which Targets are lit (have received correct color light)
  // Map key: "row-col", value: { isLit: boolean, actualColor: RGBColor | null }
  const targetLitStates = useMemo(() => {
    const litStates = new Map<
      string,
      { isLit: boolean; actualColor: RGBColor | null }
    >();

    if (targetPositions.length === 0) {
      return litStates;
    }

    // Create a map of still light at each position
    const stillLightMap = new Map<string, RGBColor>();
    for (const stillLight of stillLights) {
      const key = `${stillLight.row}-${stillLight.col}`;
      stillLightMap.set(key, stillLight.color);
    }

    // Check each Target position
    for (const targetPos of targetPositions) {
      const targetKey = `${targetPos.row}-${targetPos.col}`;
      const requiredColor = targetPos.requiredColor;

      // Get all colors hitting this target (beams + still light)
      const colorsHittingTarget = targetBeams.get(targetKey) || [];
      const stillLightColor = stillLightMap.get(targetKey);

      // Mix all colors together (beams + still light)
      const allColors: RGBColor[] = [...colorsHittingTarget];
      if (stillLightColor) {
        allColors.push(stillLightColor);
      }

      // If no colors, target is not lit
      if (allColors.length === 0) {
        litStates.set(targetKey, { isLit: false, actualColor: null });
        continue;
      }

      // Mix all colors additively
      const mixedColor = mixColors(allColors);

      // Get the required color as RGB
      const requiredColorRgb = colorNameToRgb(requiredColor);

      // Check if mixed color matches required color exactly (within tolerance)
      const colorMatch =
        Math.abs(mixedColor.r - requiredColorRgb.r) < 0.01 &&
        Math.abs(mixedColor.g - requiredColorRgb.g) < 0.01 &&
        Math.abs(mixedColor.b - requiredColorRgb.b) < 0.01;

      litStates.set(targetKey, {
        isLit: colorMatch,
        actualColor: mixedColor,
      });
    }

    return litStates;
  }, [targetBeams, stillLights, targetPositions]);

  // Use submission hook
  const {
    showWinAnimation,
    setShowWinAnimation,
    showLevelWinAnimation,
    setShowLevelWinAnimation,
    submissionError,
    levelMappings,
  } = usePrismaticSubmission({
    hasTeamSubmitted,
    currentLevel,
    targetPositions,
    targetLitStates,
    targetBeams,
    stillLights,
    taskSlug,
  });

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
  );

  const handleDragStart = useCallback((event: DragStartEvent) => {
    const { active } = event;
    const data = active.data.current as GridPuzzmon & {
      fromGrid?: boolean;
      gridRow?: number;
      gridCol?: number;
    };
    if (data) {
      setDraggedPuzzmon(data);
    }
  }, []);

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const { over, active } = event;
      const dropTargetData = over?.data.current as {
        row: number;
        col: number;
        type: string;
      };
      const activePuzzmonData = active?.data.current as GridPuzzmon & {
        fromGrid?: boolean;
        gridRow?: number;
        gridCol?: number;
      };

      if (dropTargetData && activePuzzmonData) {
        if (dropTargetData.type === "grid-cell") {
          // Prevent dropping on Target positions
          const isTargetPosition = targetPositions.some(
            (pos) =>
              pos.row === dropTargetData.row && pos.col === dropTargetData.col,
          );
          if (isTargetPosition) {
            setDraggedPuzzmon(null);
            return;
          }

          // If dragging from grid to same cell, do nothing
          if (
            activePuzzmonData.fromGrid &&
            activePuzzmonData.gridRow === dropTargetData.row &&
            activePuzzmonData.gridCol === dropTargetData.col
          ) {
            setDraggedPuzzmon(null);
            return;
          }
          handlePuzzmonPlace(
            activePuzzmonData,
            dropTargetData.row,
            dropTargetData.col,
          );
        }
      } else {
        // If not dropped on a valid drop target and dragged from grid, remove it
        if (
          activePuzzmonData?.fromGrid &&
          activePuzzmonData.gridRow !== undefined &&
          activePuzzmonData.gridCol !== undefined
        ) {
          handlePuzzmonRemove(
            activePuzzmonData.gridRow,
            activePuzzmonData.gridCol,
          );
        }
      }

      setDraggedPuzzmon(null);
    },
    [handlePuzzmonPlace, handlePuzzmonRemove, targetPositions],
  );

  // Wrapper for reset that also resets light sources on sandbox level
  const handleResetWithLightSources = useCallback(() => {
    handleReset();
    if (currentLevel === SANDBOX_LEVEL) {
      // Reset light sources to defaults - onLightSourcesChange will handle localStorage
      setTopLight(null);
      setLeftLight(null);
      setRightLight(null);
      setBottomLight(null);
    }
  }, [
    handleReset,
    currentLevel,
    setTopLight,
    setLeftLight,
    setRightLight,
    setBottomLight,
  ]);

  const isSandbox = currentLevel === SANDBOX_LEVEL;

  // Auto-hide level win animation after it completes (1.5 seconds)
  useEffect(() => {
    if (showLevelWinAnimation) {
      const timeout = setTimeout(() => {
        setShowLevelWinAnimation(false);
      }, 1500);
      return () => {
        clearTimeout(timeout);
      };
    }
  }, [showLevelWinAnimation, setShowLevelWinAnimation]);

  return (
    <MonarchTaskWrapper returnToArchive={returnToArchive}>
      <DndContext
        sensors={sensors}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
        collisionDetection={pointerWithin}
      >
        <div className="relative w-full h-full flex flex-col">
          <BackToArchiveButton
            onClick={returnToArchive}
            className="absolute top-4 left-6 z-50"
          />

          {/* Solved message */}
          <TaskSolvedMessage
            teamState={teamState}
            taskSlug={taskSlug}
            className="mx-auto mb-4"
          />

          {/* Main content area */}
          {taskData && (
            <div
              className={cn(
                "flex-1 min-h-0 flex justify-between gap-6 px-6 pt-10 pb-4",
                isSandbox && "pb-14 gap-16",
                !hasTeamSubmitted && "mt-[74px]",
              )}
            >
              {/* Left section - Level selector and Puzzmon list */}
              {/* Level selector */}
              <div className="flex flex-col gap-2">
                {taskData.levels.map((config) => {
                  const isLevelSandbox = config.level === SANDBOX_LEVEL;
                  const isLevelComplete =
                    !isLevelSandbox && levelMappings.has(config.level);
                  const showCheckmark = !isLevelSandbox;
                  return (
                    <div key={config.level} className="flex items-center gap-2">
                      <button
                        onClick={() => {
                          setCurrentLevel(config.level);
                        }}
                        className={cn(
                          "px-2 lg:px-4 py-1 lg:py-2 w-32 rounded-full font-bold text-sm lg:text-lg transition-all text-black select-none whitespace-nowrap",
                          currentLevel === config.level
                            ? "bg-accent shadow-lg scale-105"
                            : "bg-white hover:bg-gray-300",
                          isLevelSandbox &&
                            "bg-black text-white border-2 border-white hover:bg-neutral-800 focus-visible:bg-neutral-800",
                        )}
                      >
                        {isLevelSandbox
                          ? "Sandbox"
                          : `Level ${config.level - 1}`}
                      </button>
                      {showCheckmark && (
                        <Check
                          size={24}
                          className={cn(
                            "transition-all",
                            isLevelComplete
                              ? "text-green-600 opacity-100"
                              : "opacity-0",
                          )}
                          strokeWidth={3}
                        />
                      )}
                      {!showCheckmark && <div className="w-6" />}
                    </div>
                  );
                })}
                <p className="text-sm lg:text-base italic text-center max-w-40 mt-1 lg:mt-2">
                  {isSandbox
                    ? "Tip: Toggle the light source buttons and drag Puzzmon onto the grid to see how they interact!"
                    : "Tip: Hover Wattissimo and the Puzzmon in the sidebar to get some pointers!"}
                </p>
              </div>

              {/* Middle section - Grid with light source buttons */}
              <div className="min-h-0 flex grow items-center justify-center min-w-0 relative">
                {/* Light source buttons positioned around the grid - only show in sandbox level */}
                {currentLevel === SANDBOX_LEVEL && (
                  <LightSourceButtons
                    topLight={topLight}
                    leftLight={leftLight}
                    rightLight={rightLight}
                    bottomLight={bottomLight}
                    onToggleTop={() => {
                      toggleLight(topLight, setTopLight);
                    }}
                    onToggleLeft={() => {
                      toggleLight(leftLight, setLeftLight);
                    }}
                    onToggleRight={() => {
                      toggleLight(rightLight, setRightLight);
                    }}
                    onToggleBottom={() => {
                      toggleLight(bottomLight, setBottomLight);
                    }}
                  />
                )}

                <PrismaticGrid
                  onPuzzmonPlace={handlePuzzmonPlace}
                  onPuzzmonRemove={handlePuzzmonRemove}
                  gridState={gridState}
                  draggedPuzzmon={draggedPuzzmon}
                  targetPositions={targetPositions}
                  targetImage={targetData.image}
                  targetImageSolved={targetData.imageSolved}
                  targetLitStates={targetLitStates}
                  lightSources={lightSources}
                  isSandbox={isSandbox}
                />

                {/* Level win animation - centered on grid */}
                {showLevelWinAnimation && <LevelWinAnimation />}
              </div>

              <div className="flex flex-col items-center gap-4">
                {/* Reset button */}
                <button
                  onClick={handleResetWithLightSources}
                  className="w-fit flex items-center gap-2 text-white border-2 border-white font-bold rounded-full pl-3 pr-4 py-1 mr-6 bg-black hover:bg-neutral-800 focus-visible:bg-neutral-800 active:bg-neutral-700 select-none"
                >
                  <RotateCcw height={16} width={16} strokeWidth={3} />
                  Reset
                </button>
                {/* Puzzmon list */}
                <PuzzmonList puzzmon={availablePuzzmon} />
              </div>
            </div>
          )}

          {submissionError && (
            <div className="p-4 flex justify-center">
              <p className="text-red-500">{submissionError}</p>
            </div>
          )}

          {/* Win animation */}
          {showWinAnimation && (
            <TaskSuccessAnimation
              onComplete={() => {
                setShowWinAnimation(false);
              }}
            />
          )}
        </div>

        {createPortal(
          <DragOverlay dropAnimation={null} modifiers={[snapCenterToCursor]}>
            {draggedPuzzmon && (
              <div className="w-16 h-16 lg:w-24 lg:h-24 cursor-grabbing">
                <img
                  src={draggedPuzzmon.image}
                  alt={draggedPuzzmon.name}
                  className="w-full h-full object-contain"
                />
              </div>
            )}
          </DragOverlay>,
          document.body,
        )}
      </DndContext>
    </MonarchTaskWrapper>
  );
}

export default PrismaticPathsTask;
