// Beam path calculation logic - main orchestrator

import { processBeam, type BeamProcessingContext } from "./beamPropagation";
import type {
  ContinuousBeamPath,
  Direction,
  LightBeam,
  LightSource,
  PuzzmonBeamInfo,
  RGBColor,
  StillLight,
} from "./beamTypes";
import { mixColors } from "./beamUtils";
import { buildContinuousPaths, type PathBuildingContext } from "./pathBuilding";
import { applyPuzzmonTransformation } from "./puzzmonTransforms";
import {
  processStillLightConsumption,
  createShouldSkipStillLightCheck,
  type StillLightProcessingContext,
} from "./stillLightProcessing";
import type { GridPuzzmon } from "./types";

/**
 * Recursively removes all connected beams in a given direction
 * Used for post-processing to remove paths from blocked puzzmon
 */
function removeConnectedBeamsPostProcess(
  row: number,
  col: number,
  direction: Direction,
  cellBeams: Map<string, RGBColor[]>,
  gridState: (GridPuzzmon | null)[][],
  gridRows: number,
  gridCols: number,
  isTargetPosition: (row: number, col: number) => boolean,
  visited: Set<string>,
): void {
  // Check bounds
  if (row < 0 || row >= gridRows || col < 0 || col >= gridCols) {
    return;
  }

  const cellKey = `${row}-${col}-${direction}`;

  // Avoid infinite loops
  if (visited.has(cellKey)) {
    return;
  }
  visited.add(cellKey);

  // Check if there's a beam here
  if (!cellBeams.has(cellKey)) {
    return;
  }

  // Check if we hit a puzzmon or target - stop here
  const hasPuzzmon = gridState[row]?.[col] !== null;
  const isTarget = isTargetPosition(row, col);
  if (hasPuzzmon || isTarget) {
    // Remove this beam but don't continue
    cellBeams.delete(cellKey);
    return;
  }

  // Remove this beam
  cellBeams.delete(cellKey);

  // Continue in the same direction to the next cell
  let nextRow = row;
  let nextCol = col;

  switch (direction) {
    case "down":
      nextRow += 1;
      break;
    case "up":
      nextRow -= 1;
      break;
    case "right":
      nextCol += 1;
      break;
    case "left":
      nextCol -= 1;
      break;
  }

  // Recursively remove beams in the next cell
  removeConnectedBeamsPostProcess(
    nextRow,
    nextCol,
    direction,
    cellBeams,
    gridState,
    gridRows,
    gridCols,
    isTargetPosition,
    visited,
  );
}

// Calculate continuous light beam paths through the grid
// Returns both paths and beam info for puzzmon cells
export function calculateLightBeams(
  gridState: (GridPuzzmon | null)[][],
  gridRows: number,
  gridCols: number,
  targetPositions?: { row: number; col: number }[],
  lightSources?: LightSource[],
): {
  paths: ContinuousBeamPath[];
  puzzmonBeams: Map<string, PuzzmonBeamInfo>; // "row-col" -> beam info
  targetBeams: Map<string, RGBColor[]>; // "row-col" -> colors hitting target
  stillLights: StillLight[]; // All still light cells
} {
  // Map to track all beams at each cell, grouped by direction
  // Key: "row-col-direction", Value: array of colors at that position/direction
  const cellBeams = new Map<string, RGBColor[]>();
  // Track beams at puzzmon cells for border rendering
  const puzzmonBeams = new Map<string, PuzzmonBeamInfo>();
  // Track beams hitting target positions
  const targetBeams = new Map<string, RGBColor[]>();
  // Track still light at each cell (key: "row-col", value: mixed color)
  const stillLightMap = new Map<string, RGBColor[]>();
  // Track which puzzmon have already activated from still light in this calculation cycle
  // (for puzzmon that disperse still light - they should only disperse if they have exactly one source)
  const stillLightDispersersActivated = new Set<string>();

  // Helper to check if a position is a target
  const isTargetPosition = (row: number, col: number): boolean => {
    return (
      targetPositions?.some((pos) => pos.row === row && pos.col === col) ??
      false
    );
  };

  // Default light source if none provided (for backward compatibility)
  const defaultLightSources: LightSource[] = lightSources ?? [
    {
      row: 0,
      col: 3,
      direction: "down",
      color: { r: 1, g: 1, b: 1 }, // White light
    },
  ];

  const queue: LightBeam[] = [];

  // Process all light sources
  for (const lightSource of defaultLightSources) {
    const {
      row: START_ROW,
      col: START_COL,
      direction: START_DIRECTION,
      color: START_COLOR,
    } = lightSource;

    // Check if there's a puzzmon at the starting position
    // If so, treat it as receiving light from the specified direction
    const startPuzzmon = gridState[START_ROW]?.[START_COL];
    if (startPuzzmon) {
      const puzzmonKey = `${START_ROW}-${START_COL}`;
      if (!puzzmonBeams.has(puzzmonKey)) {
        puzzmonBeams.set(puzzmonKey, {
          incoming: new Map(),
          outgoing: new Map(),
        });
      }
      const info = puzzmonBeams.get(puzzmonKey);
      if (info) {
        // Light is coming from the specified direction
        if (!info.incoming.has(START_DIRECTION)) {
          info.incoming.set(START_DIRECTION, []);
        }
        const incomingColors = info.incoming.get(START_DIRECTION);
        if (incomingColors) {
          incomingColors.push(START_COLOR);
        }

        // Apply puzzmon transformation
        const transformResult = applyPuzzmonTransformation(
          startPuzzmon,
          START_DIRECTION,
          START_COLOR,
          info,
        );

        // Queue the transformed beams
        for (const transformedBeam of transformResult.beams) {
          transformedBeam.row = START_ROW;
          transformedBeam.col = START_COL;
          queue.push(transformedBeam);
        }

        // Process still light positions from transform
        if (transformResult.stillLightPositions) {
          for (const pos of transformResult.stillLightPositions) {
            const targetRow = START_ROW + pos.rowOffset;
            const targetCol = START_COL + pos.colOffset;

            // Check bounds
            if (
              targetRow >= 0 &&
              targetRow < gridRows &&
              targetCol >= 0 &&
              targetCol < gridCols
            ) {
              // Allow still light on cells that can accept still light
              // Still light can be placed on empty cells, targets, or puzzmon that can consume still light
              const puzzmonAtTarget = gridState[targetRow]?.[targetCol];
              const isTarget = isTargetPosition(targetRow, targetCol);

              // Check if the puzzmon at target can consume still light by checking its transform
              let canTargetConsumeStillLight = false;
              if (puzzmonAtTarget) {
                // Mistermoon (order 9), Incandabra (order 5), and Lanternbot (order 4) can consume still light
                // even though their transforms don't return beams or still light positions
                // Their still light consumption is handled in processStillLightConsumption
                if (
                  puzzmonAtTarget.order === 9 ||
                  puzzmonAtTarget.order === 5 ||
                  puzzmonAtTarget.order === 4
                ) {
                  canTargetConsumeStillLight = true;
                } else {
                  const targetKey = `${targetRow}-${targetCol}`;
                  const targetBeamInfo = puzzmonBeams.get(targetKey) || {
                    incoming: new Map(),
                    outgoing: new Map(),
                  };
                  const targetStillLightColor = pos.color ?? START_COLOR;
                  const targetTransformResult = applyPuzzmonTransformation(
                    puzzmonAtTarget,
                    "down", // Dummy direction
                    targetStillLightColor,
                    targetBeamInfo,
                  );
                  // If it returns still light positions or beams, it can consume still light
                  canTargetConsumeStillLight =
                    targetTransformResult.stillLightPositions !== undefined ||
                    targetTransformResult.beams.length > 0;
                }
              }

              const canPlaceStillLight =
                isTarget || !puzzmonAtTarget || canTargetConsumeStillLight;

              if (canPlaceStillLight) {
                const stillLightKey = `${targetRow}-${targetCol}`;
                if (!stillLightMap.has(stillLightKey)) {
                  stillLightMap.set(stillLightKey, []);
                }
                const stillLightColors = stillLightMap.get(stillLightKey);
                if (stillLightColors) {
                  // Use the color specified in the position, or fall back to START_COLOR
                  const stillLightColor = pos.color ?? START_COLOR;
                  stillLightColors.push(stillLightColor);
                }
              }
            }
          }
        }
      }
    } else {
      // No puzzmon at start - add the initial beam in the specified direction
      const startBeam: LightBeam = {
        row: START_ROW,
        col: START_COL,
        direction: START_DIRECTION,
        color: START_COLOR,
      };
      queue.push(startBeam);
    }
  }
  // Create processing context for beam propagation
  const beamProcessingContext: BeamProcessingContext = {
    gridState,
    gridRows,
    gridCols,
    cellBeams,
    puzzmonBeams,
    targetBeams,
    stillLightMap,
    isTargetPosition,
  };

  const visited = new Set<string>(); // Track visited states to avoid infinite loops
  const maxIterations = 100; // Safety limit
  let iterations = 0;

  while (queue.length > 0 && iterations < maxIterations) {
    iterations++;
    const beam = queue.shift();
    if (!beam) break;

    const nextBeams = processBeam(
      beam,
      {
        visitedSet: visited,
        processStillLight: true,
      },
      beamProcessingContext,
    );
    queue.push(...nextBeams);
  }

  // Path building context (will be used after still light processing)
  const pathBuildingContext: PathBuildingContext = {
    gridState,
    gridRows,
    gridCols,
    cellBeams,
    isTargetPosition,
  };

  // Process still light consumption by puzzmon that can consume still light
  // These puzzmon can consume still light if they don't have incoming beams
  // Process recursively until no new still light is generated (to handle cascading still light dispersers)
  let stillLightIterations = 0;
  const maxStillLightIterations = 100; // Safety limit for still light propagation

  const stillLightProcessingContext: StillLightProcessingContext = {
    gridState,
    gridRows,
    gridCols,
    puzzmonBeams,
    stillLightMap,
    stillLightDispersersActivated,
    isTargetPosition,
  };

  while (stillLightIterations < maxStillLightIterations) {
    stillLightIterations++;

    // Process still light consumption/dispersal
    const { newBeams, newStillLightGenerated } = processStillLightConsumption(
      stillLightProcessingContext,
    );
    queue.push(...newBeams);

    // Track still light map state before processing beams
    // This allows us to detect if still light was created during beam processing
    const stillLightKeysBeforeBeams = new Set(stillLightMap.keys());
    const stillLightMapStateBeforeBeams = new Map<string, number>();
    for (const [key, colors] of stillLightMap.entries()) {
      stillLightMapStateBeforeBeams.set(key, colors.length);
    }

    // Process beams generated from still light consumption in this iteration
    // This allows still light created by these beams to be consumed in the next iteration
    const beamProcessedInIteration = new Set<string>();
    const shouldSkipStillLightCheck = createShouldSkipStillLightCheck(
      stillLightMap,
      stillLightDispersersActivated,
    );

    while (queue.length > 0 && iterations < maxIterations) {
      iterations++;
      const beam = queue.shift();
      if (!beam) break;

      const nextBeams = processBeam(
        beam,
        {
          visitedSet: beamProcessedInIteration,
          processStillLight: true,
          checkSkipStillLightBeforeTracking: true,
          shouldSkipStillLightCheck,
        },
        beamProcessingContext,
      );

      queue.push(...nextBeams);
    }

    // Check if still light was created during beam processing
    // (new keys added or existing keys have more colors)
    let stillLightCreatedDuringBeams = false;
    for (const [key, colors] of stillLightMap.entries()) {
      const beforeLength = stillLightMapStateBeforeBeams.get(key) || 0;
      if (!stillLightKeysBeforeBeams.has(key) || colors.length > beforeLength) {
        stillLightCreatedDuringBeams = true;
        break;
      }
    }

    // If no new still light was generated in still light processing AND no still light was created during beam processing, we're done
    if (!newStillLightGenerated && !stillLightCreatedDuringBeams) {
      break;
    }
  }

  // Process any remaining beams that weren't processed in the still light consumption loop
  // (but don't generate still light from these to avoid infinite loops)
  const stillLightProcessed = new Set<string>();
  while (queue.length > 0 && iterations < maxIterations) {
    iterations++;
    const beam = queue.shift();
    if (!beam) break;

    const nextBeams = processBeam(
      beam,
      {
        visitedSet: stillLightProcessed,
        processStillLight: false, // Don't process still light in this loop
      },
      beamProcessingContext,
    );
    queue.push(...nextBeams);
  }

  // Post-process: Remove paths and still light from puzzmon that have multiple inputs and should be blocked
  // This fixes the root cause by removing paths and still light after all beams have been processed
  for (const [puzzmonKey, beamInfo] of puzzmonBeams.entries()) {
    const [rowStr, colStr] = puzzmonKey.split("-");
    const row = Number(rowStr);
    const col = Number(colStr);

    if (row < 0 || row >= gridRows || col < 0 || col >= gridCols) continue;

    const puzzmon = gridState[row]?.[col];
    if (!puzzmon) continue;

    // Check if this puzzmon should block outputs when multiple inputs are present
    const incomingDirections = Array.from(beamInfo.incoming.keys());
    const hasMultipleInputs = incomingDirections.length > 1;
    const shouldBlockMultipleInputs = hasMultipleInputs && puzzmon.order !== 2;

    if (shouldBlockMultipleInputs) {
      // Remove all cellBeams in all 4 directions from adjacent cells
      const directionsToClean: Direction[] = ["up", "down", "left", "right"];
      const visitedForCleanup = new Set<string>();

      for (const outputDirection of directionsToClean) {
        // Calculate adjacent cell position
        let currentRow = row;
        let currentCol = col;
        switch (outputDirection) {
          case "up":
            currentRow -= 1;
            break;
          case "down":
            currentRow += 1;
            break;
          case "left":
            currentCol -= 1;
            break;
          case "right":
            currentCol += 1;
            break;
        }

        // Recursively remove all connected beams in this direction
        if (
          currentRow >= 0 &&
          currentRow < gridRows &&
          currentCol >= 0 &&
          currentCol < gridCols
        ) {
          removeConnectedBeamsPostProcess(
            currentRow,
            currentCol,
            outputDirection,
            cellBeams,
            gridState,
            gridRows,
            gridCols,
            isTargetPosition,
            visitedForCleanup,
          );
        }
      }

      // Remove still light created by Glimmerpom (order 6) or Prismoidia (order 7)
      if (puzzmon.order === 6 || puzzmon.order === 7) {
        // For Glimmerpom: still light is placed 2 units away in 8 directions
        if (puzzmon.order === 6) {
          const glimmerpomStillLightPositions = [
            { rowOffset: 0, colOffset: 2 },
            { rowOffset: 1, colOffset: 1 },
            { rowOffset: 2, colOffset: 0 },
            { rowOffset: 1, colOffset: -1 },
            { rowOffset: 0, colOffset: -2 },
            { rowOffset: -1, colOffset: -1 },
            { rowOffset: -2, colOffset: 0 },
            { rowOffset: -1, colOffset: 1 },
          ];

          for (const pos of glimmerpomStillLightPositions) {
            const targetRow = row + pos.rowOffset;
            const targetCol = col + pos.colOffset;
            if (
              targetRow >= 0 &&
              targetRow < gridRows &&
              targetCol >= 0 &&
              targetCol < gridCols
            ) {
              const stillLightKey = `${targetRow}-${targetCol}`;
              stillLightMap.delete(stillLightKey);
            }
          }
        }

        // For Prismoidia: still light is placed in a specific pattern relative to incoming direction
        // We need to check all possible patterns since we don't know which direction the beam came from
        if (puzzmon.order === 7) {
          // Prismoidia places still light in 6 positions relative to the incoming direction
          // Base pattern (beam from top/down): (1,1), (0,1), (-1,1), (1,-1), (0,-1), (-1,-1)
          // We'll check all rotations of this pattern
          const basePositions = [
            { rowOffset: 1, colOffset: 1 },
            { rowOffset: 0, colOffset: 1 },
            { rowOffset: -1, colOffset: 1 },
            { rowOffset: 1, colOffset: -1 },
            { rowOffset: 0, colOffset: -1 },
            { rowOffset: -1, colOffset: -1 },
          ];

          // Check all 4 rotations (for each possible incoming direction)
          const allRotations = [
            basePositions, // down (default)
            basePositions.map((p) => ({
              rowOffset: -p.colOffset,
              colOffset: p.rowOffset,
            })), // right (90° counter-clockwise)
            basePositions.map((p) => ({
              rowOffset: -p.rowOffset,
              colOffset: -p.colOffset,
            })), // up (180°)
            basePositions.map((p) => ({
              rowOffset: p.colOffset,
              colOffset: -p.rowOffset,
            })), // left (90° clockwise)
          ];

          for (const rotation of allRotations) {
            for (const pos of rotation) {
              const targetRow = row + pos.rowOffset;
              const targetCol = col + pos.colOffset;
              if (
                targetRow >= 0 &&
                targetRow < gridRows &&
                targetCol >= 0 &&
                targetCol < gridCols
              ) {
                const stillLightKey = `${targetRow}-${targetCol}`;
                stillLightMap.delete(stillLightKey);
              }
            }
          }
        }
      }
    }
  }

  // Rebuild continuous paths to include beams from still light consumption
  const allContinuousPaths = buildContinuousPaths(pathBuildingContext);

  // Build still lights array and update puzzmon beam info
  const stillLights: StillLight[] = [];
  for (const [key, colors] of stillLightMap.entries()) {
    // Skip if no colors (shouldn't happen, but safety check)
    if (!colors?.length) {
      continue;
    }
    const [rowStr, colStr] = key.split("-");
    const row = Number(rowStr);
    const col = Number(colStr);
    const mixedColor = mixColors(colors);
    stillLights.push({ row, col, color: mixedColor });

    // Also update puzzmon beam info if there's a puzzmon at this cell
    const puzzmonKey = `${row}-${col}`;
    if (puzzmonBeams.has(puzzmonKey)) {
      const beamInfo = puzzmonBeams.get(puzzmonKey);
      if (beamInfo) {
        beamInfo.stillLight = mixedColor;
      }
    }
  }

  return {
    paths: allContinuousPaths,
    puzzmonBeams,
    targetBeams,
    stillLights,
  };
}
