import React from "react";
import { TOY_IMAGES } from "../constants";

type PlacedToyProps = {
  toy: string;
  position: { x: number; y: number; width: number };
};

export function PlacedToy({ toy, position }: PlacedToyProps) {
  return (
    <div
      className="absolute z-10"
      style={{
        left: `${position.x * 100}%`,
        top: `${position.y * 100}%`,
        width: `${position.width * 100}%`,
      }}
    >
      <img
        src={TOY_IMAGES[toy]}
        alt={toy}
        className="w-full h-auto object-contain"
      />
    </div>
  );
}
