import { cn } from "@hunt/styled-ui";
import React from "react";
import { BackToArchiveButton } from "../components/MonarchButton";

type MonarchTaskWrapperProps = {
  children: React.ReactNode;
  returnToArchive?: () => void;
  warningClassName?: string;
  taskClassName?: string;
};

export default function MonarchTaskWrapper({
  children,
  returnToArchive,
  warningClassName,
  taskClassName,
}: MonarchTaskWrapperProps) {
  return (
    <>
      {/* Show message on small screens */}
      <div
        className={cn(
          "md:hidden relative flex items-center justify-center h-full w-full p-8",
          warningClassName,
        )}
      >
        {returnToArchive && (
          <BackToArchiveButton
            onClick={returnToArchive}
            className="absolute top-4 left-6 z-50"
          />
        )}
        <div className="text-center max-w-md">
          <p className="text-lg font-semibold text-accent mb-2">
            This task is not supported on this screen size
          </p>
          <p className="text-sm text-white">
            Please use a device with a wider screen or resize your browser
            window to access this task.
          </p>
        </div>
      </div>

      {/* Show task content on wider screens */}
      <div className={cn("hidden md:block w-full h-full", taskClassName)}>
        {children}
      </div>
    </>
  );
}
