// Still light processing logic - handles still light consumption and dispersal

import type {
  Direction,
  LightBeam,
  PuzzmonBeamInfo,
  RGBColor,
} from "./beamTypes";
import { mixColors } from "./beamUtils";
import { applyPuzzmonTransformation } from "./puzzmonTransforms";
import type { GridPuzzmon } from "./types";

export type StillLightProcessingContext = {
  gridState: (GridPuzzmon | null)[][];
  gridRows: number;
  gridCols: number;
  puzzmonBeams: Map<string, PuzzmonBeamInfo>;
  stillLightMap: Map<string, RGBColor[]>;
  stillLightDispersersActivated: Set<string>;
  isTargetPosition: (row: number, col: number) => boolean;
};

/**
 * Processes still light consumption by puzzmon that can consume still light
 * Returns new beams generated from still light consumption and whether new still light was generated
 */
export function processStillLightConsumption(
  context: StillLightProcessingContext,
): { newBeams: LightBeam[]; newStillLightGenerated: boolean } {
  const {
    gridState,
    gridRows,
    gridCols,
    puzzmonBeams,
    stillLightMap,
    stillLightDispersersActivated,
    isTargetPosition,
  } = context;

  let newStillLightGenerated = false;
  const stillLightActivated = new Set<string>(); // Track which puzzmon have already activated from still light in this iteration
  const newBeams: LightBeam[] = [];

  // First pass: Process still light dispersers (glimmerpom, etc.)
  // This ensures that still light generated by dispersers is available for consumers in the same iteration
  for (let row = 0; row < gridRows; row++) {
    for (let col = 0; col < gridCols; col++) {
      const puzzmon = gridState[row]?.[col];
      if (!puzzmon) continue;

      const puzzmonKey = `${row}-${col}`;
      // Initialize beamInfo if it doesn't exist
      if (!puzzmonBeams.has(puzzmonKey)) {
        puzzmonBeams.set(puzzmonKey, {
          incoming: new Map(),
          outgoing: new Map(),
        });
      }
      const beamInfo = puzzmonBeams.get(puzzmonKey);
      if (!beamInfo) continue;

      // Check if there's still light at this cell
      const stillLightKey = `${row}-${col}`;
      const stillLightColors = stillLightMap.get(stillLightKey);

      // Only process still light dispersers in the first pass
      if (stillLightColors && stillLightColors.length > 0) {
        // Check if this puzzmon has incoming beams - if so, skip still light dispersal
        if (beamInfo.incoming.size > 0) {
          continue;
        }

        const stillLightColor = mixColors(stillLightColors);
        const activationKey = puzzmonKey;

        // Skip if this puzzmon has already been activated in this iteration
        if (stillLightActivated.has(activationKey)) {
          continue;
        }

        // Check if this puzzmon can disperse still light by checking its transform
        const dummyTransformResult = applyPuzzmonTransformation(
          puzzmon,
          "down", // Dummy direction - transform should return all positions regardless
          stillLightColor,
          beamInfo,
        );

        if (dummyTransformResult.stillLightPositions && puzzmon.order !== 7) {
          // This puzzmon can disperse still light
          stillLightActivated.add(activationKey);
          // Track that this puzzmon has activated from still light
          stillLightDispersersActivated.add(puzzmonKey);
          // Consume the still light by removing it (since it's been used)
          stillLightMap.delete(stillLightKey);

          // Use the still light positions from the transform result
          const allStillLightPositions =
            dummyTransformResult.stillLightPositions;

          for (const pos of allStillLightPositions) {
            const targetRow = row + pos.rowOffset;
            const targetCol = col + pos.colOffset;

            // Check bounds
            if (
              targetRow >= 0 &&
              targetRow < gridRows &&
              targetCol >= 0 &&
              targetCol < gridCols
            ) {
              // Check if the target cell can accept still light
              const puzzmonAtTarget = gridState[targetRow]?.[targetCol];
              const isTarget = isTargetPosition(targetRow, targetCol);

              // Check if the puzzmon at target can consume still light by checking its transform
              // Mistermoon (order 9), Incandabra (order 5), and Lanternbot (order 4) can consume still light
              // even though their transforms don't return stillLightPositions
              let canTargetConsumeStillLight = false;
              if (puzzmonAtTarget) {
                // Check if it's a known still light consumer
                if (
                  puzzmonAtTarget.order === 4 ||
                  puzzmonAtTarget.order === 5 ||
                  puzzmonAtTarget.order === 9
                ) {
                  canTargetConsumeStillLight = true;
                } else {
                  // For other puzzmon, check if their transform returns still light positions or beams
                  const targetKey = `${targetRow}-${targetCol}`;
                  const targetBeamInfo = puzzmonBeams.get(targetKey) || {
                    incoming: new Map(),
                    outgoing: new Map(),
                  };
                  const targetTransformResult = applyPuzzmonTransformation(
                    puzzmonAtTarget,
                    "down", // Dummy direction
                    stillLightColor,
                    targetBeamInfo,
                  );
                  // If it returns still light positions or beams, it can consume still light
                  canTargetConsumeStillLight =
                    targetTransformResult.stillLightPositions !== undefined ||
                    targetTransformResult.beams.length > 0;
                }
              }

              const canPlaceStillLight =
                isTarget || !puzzmonAtTarget || canTargetConsumeStillLight;

              if (canPlaceStillLight) {
                const targetStillLightKey = `${targetRow}-${targetCol}`;

                // Check if still light already exists at this position
                const existingStillLightColors =
                  stillLightMap.get(targetStillLightKey);
                const existingMixedColor =
                  existingStillLightColors &&
                  existingStillLightColors.length > 0
                    ? mixColors(existingStillLightColors)
                    : null;

                // If still light already exists with the same color, skip adding it (to avoid duplicate circles)
                if (existingMixedColor) {
                  const colorMatch =
                    Math.abs(existingMixedColor.r - stillLightColor.r) < 0.01 &&
                    Math.abs(existingMixedColor.g - stillLightColor.g) < 0.01 &&
                    Math.abs(existingMixedColor.b - stillLightColor.b) < 0.01;
                  if (colorMatch) {
                    continue; // Skip - still light with same color already exists here
                  }
                }

                // Ensure the map entry exists before adding
                if (!stillLightMap.has(targetStillLightKey)) {
                  stillLightMap.set(targetStillLightKey, []);
                }

                const targetStillLightColors =
                  stillLightMap.get(targetStillLightKey);
                if (targetStillLightColors) {
                  targetStillLightColors.push(stillLightColor);

                  // Check if this is actually new still light (different color or didn't exist before)
                  const newMixedColor = mixColors(targetStillLightColors);
                  const isNewStillLight =
                    !existingMixedColor ||
                    Math.abs(existingMixedColor.r - newMixedColor.r) > 0.01 ||
                    Math.abs(existingMixedColor.g - newMixedColor.g) > 0.01 ||
                    Math.abs(existingMixedColor.b - newMixedColor.b) > 0.01;

                  if (isNewStillLight) {
                    // Mark that we generated new still light
                    newStillLightGenerated = true;
                  }
                }
              }
            }
          }
        }
      }
    }
  }

  // Second pass: Process still light consumers (Incandabra, Lanternbot, Mistermoon)
  // This happens after dispersers so that newly generated still light is available
  for (let row = 0; row < gridRows; row++) {
    for (let col = 0; col < gridCols; col++) {
      const puzzmon = gridState[row]?.[col];
      if (!puzzmon) continue;

      const puzzmonKey = `${row}-${col}`;
      // Initialize beamInfo if it doesn't exist
      if (!puzzmonBeams.has(puzzmonKey)) {
        puzzmonBeams.set(puzzmonKey, {
          incoming: new Map(),
          outgoing: new Map(),
        });
      }
      const beamInfo = puzzmonBeams.get(puzzmonKey);
      if (!beamInfo) continue;

      // Check if there's still light at this cell
      const stillLightKey = `${row}-${col}`;
      const stillLightColors = stillLightMap.get(stillLightKey);

      // For puzzmon that can consume still light (Incandabra, Lanternbot, Mistermoon):
      // They only consume still light if they don't have incoming beams
      // EXCEPT for Mistermoon - it only works with still light, so it should process still light
      // even if it has incoming beams tracked (those beams are blocked and don't interact with it)
      if (stillLightColors && stillLightColors.length > 0) {
        // Check if this puzzmon has incoming beams - if so, skip still light consumption
        // But Mistermoon (order 9) is an exception - it processes still light regardless
        if (beamInfo.incoming.size > 0) {
          // For Incandabra/Lanternbot, skip if they have incoming beams
          // Mistermoon is handled separately below and processes still light regardless
          if (puzzmon.order === 4 || puzzmon.order === 5) {
            continue;
          }
          // Mistermoon (order 9) will be processed below even if it has incoming beams
        }
        if (
          (puzzmon.order === 4 || puzzmon.order === 5) &&
          beamInfo.outgoing.size > 0
        ) {
          continue;
        }
        const stillLightColor = mixColors(stillLightColors);
        // Track activation by puzzmon only (not by color) so each puzzmon activates once per iteration
        // but different puzzmon can cascade across iterations
        const activationKey = puzzmonKey;

        // Skip if this puzzmon has already been activated in this iteration
        if (stillLightActivated.has(activationKey)) {
          continue;
        }

        // Incandabra (TYPE_5): Takes still light and casts blue component to the north
        if (puzzmon.order === 5) {
          const blueComponent = { r: 0, g: 0, b: stillLightColor.b };
          if (stillLightColor.b > 0.1) {
            stillLightActivated.add(activationKey);
            // Consume the still light by removing it (since it's been used)
            stillLightMap.delete(stillLightKey);

            const northBeam: LightBeam = {
              row,
              col,
              direction: "up",
              color: blueComponent,
            };
            newBeams.push(northBeam);

            // Track outgoing beam
            if (!beamInfo.outgoing.has("up")) {
              beamInfo.outgoing.set("up", []);
            }
            const outgoingColors = beamInfo.outgoing.get("up");
            if (outgoingColors) {
              outgoingColors.push(blueComponent);
            }
          }
        }

        // Lanternbot (TYPE_4): Takes still light and casts red component to the east
        if (puzzmon.order === 4) {
          const redComponent = { r: stillLightColor.r, g: 0, b: 0 };
          if (stillLightColor.r > 0.1) {
            stillLightActivated.add(activationKey);
            // Consume the still light by removing it (since it's been used)
            stillLightMap.delete(stillLightKey);

            const eastBeam: LightBeam = {
              row,
              col,
              direction: "right",
              color: redComponent,
            };
            newBeams.push(eastBeam);

            // Track outgoing beam
            if (!beamInfo.outgoing.has("right")) {
              beamInfo.outgoing.set("right", []);
            }
            const outgoingColors = beamInfo.outgoing.get("right");
            if (outgoingColors) {
              outgoingColors.push(redComponent);
            }
          }
        }

        // Mistermoon (TYPE_9): Takes still light and shoots beams in directions with empty spaces
        // Shoots beams in all directions that have an empty cell next to mistermoon
        // Does NOT shoot if there is another puzzmon next to mistermoon in that direction
        // Mistermoon ONLY works with still light, not with incoming beams
        // If mistermoon has incoming beams tracked (from beams that hit it), those beams are blocked
        // and don't interact with mistermoon, so we should still process still light
        if (puzzmon.order === 9) {
          // CRITICAL: Re-check still light right before processing mistermoon
          // Still light might have been deleted during beam propagation before this function was called
          const currentStillLightColors = stillLightMap.get(stillLightKey);
          if (
            !currentStillLightColors ||
            currentStillLightColors.length === 0
          ) {
            // Still light was already consumed/deleted, skip processing
            continue;
          }

          // Mistermoon only works with still light, not with incoming beams
          // Even if it has incoming beams tracked (beams that hit it are blocked),
          // it should still process still light since beams don't interact with mistermoon
          // So we don't check for incoming beams - mistermoon always processes still light if present

          stillLightActivated.add(activationKey);
          // Consume the still light by removing it (since it's been used)
          // Use the current still light colors we just checked, not the ones from earlier
          const currentStillLightColor = mixColors(currentStillLightColors);
          stillLightMap.delete(stillLightKey);

          // Check all 4 directions (up, down, left, right)
          const directions: {
            direction: Direction;
            rowOffset: number;
            colOffset: number;
          }[] = [
            { direction: "up", rowOffset: -1, colOffset: 0 },
            { direction: "down", rowOffset: 1, colOffset: 0 },
            { direction: "left", rowOffset: 0, colOffset: -1 },
            { direction: "right", rowOffset: 0, colOffset: 1 },
          ];

          // Create beams for all directions with empty cells (no puzzmon)
          for (const { direction, rowOffset, colOffset } of directions) {
            const targetRow = row + rowOffset;
            const targetCol = col + colOffset;

            // Check bounds - only shoot if the target cell is within the grid
            if (
              targetRow >= 0 &&
              targetRow < gridRows &&
              targetCol >= 0 &&
              targetCol < gridCols
            ) {
              // Check if there's a puzzmon at the target cell
              const puzzmonAtTarget = gridState[targetRow]?.[targetCol];

              // Only shoot beam if the cell is empty (null = no puzzmon)
              // Do NOT shoot if there's another puzzmon next to mistermoon
              if (puzzmonAtTarget === null) {
                // Create beam in this direction with the still light color
                // Use currentStillLightColor which was captured right before deletion
                const beam: LightBeam = {
                  row,
                  col,
                  direction,
                  color: currentStillLightColor,
                };
                newBeams.push(beam);

                // Track outgoing beam
                if (!beamInfo.outgoing.has(direction)) {
                  beamInfo.outgoing.set(direction, []);
                }
                const outgoingColors = beamInfo.outgoing.get(direction);
                if (outgoingColors) {
                  outgoingColors.push(currentStillLightColor);
                }
              }
            }
          }
          // Continue to next puzzmon after processing mistermoon
          continue;
        }
      }
    }
  }

  return { newBeams, newStillLightGenerated };
}

/**
 * Creates a helper function to check if we should skip still light processing for a puzzmon
 * Used in the beam processing loop to determine if still light should be created
 */
export function createShouldSkipStillLightCheck(
  stillLightMap: Map<string, RGBColor[]>,
  stillLightDispersersActivated: Set<string>,
): (
  puzzmon: GridPuzzmon,
  puzzmonKey: string,
  info: PuzzmonBeamInfo | undefined,
) => boolean {
  return (puzzmon, puzzmonKey, info) => {
    if (!info) return false;
    // Check if this puzzmon can disperse still light by checking its transform
    const dummyBeamInfo: PuzzmonBeamInfo = {
      incoming: new Map<Direction, RGBColor[]>(),
      outgoing: new Map<Direction, RGBColor[]>(),
    };
    const dummyTransformResult = applyPuzzmonTransformation(
      puzzmon,
      "down", // Dummy direction
      { r: 1, g: 1, b: 1 }, // Dummy color
      dummyBeamInfo,
    );

    if (dummyTransformResult.stillLightPositions) {
      // This puzzmon can disperse still light
      const stillLightAtPuzzmon = stillLightMap.get(puzzmonKey);
      const hasStillLightSource =
        stillLightAtPuzzmon && stillLightAtPuzzmon.length > 0;
      const hasActivatedFromStillLight =
        stillLightDispersersActivated.has(puzzmonKey);

      // For puzzmon that disperse still light (order 6), always allow processing
      if (puzzmon.order === 6) {
        return false;
      } else if (hasStillLightSource || hasActivatedFromStillLight) {
        return true;
      }
    }
    return false;
  };
}
