const getPuzzmonData = (puzzmonSlug: string) => {
  const data = MONSTER_DATA["Royal Groves"][puzzmonSlug];
  return {
    id: puzzmonSlug,
    name: data.name,
    imageSrc: data.imageSrc,
  };
};

// Get Royal Groves Puzzmon from existing data
export const getRoyalGrovesPuzzmon = (): Tile[] => {
  const royalGrovesData = MONSTER_DATA["Royal Groves"];
  return Object.entries(royalGrovesData).map(([key, puzzmon]) => ({
    id: key,
    name: puzzmon.name,
    image: puzzmon.imageSrc,
    type: "puzzmon",
  }));
};

