import { cn } from "@hunt/styled-ui";
import { BackToArchiveButton } from "../../components/MonarchButton";
import MonarchTaskWrapper from "../MonarchTaskWrapper";
import TaskSolvedMessage from "../TaskSolvedMessage";
import TaskSuccessAnimation from "../TaskSuccessAnimation";
import { type MonarchTaskProps } from "../monarch_tasks_defs";
import { EndGameModal } from "./EndGameModal";
import SnakeSegment from "./SnakeSegment";
import Background from "./assets/background.png";
import Bomb from "./assets/bomb.png";
import Boulder from "./assets/boulder.png";
import CheckeredFlag from "./assets/checkered_flag.png";
import Explosion from "./assets/explosion.png";
import GemBlue from "./assets/gem_blue.png";
import GemGreen from "./assets/gem_green.png";
import GemGrey from "./assets/gem_grey.png";
import GemLightBlue from "./assets/gem_light_blue.png";
import GemOrange from "./assets/gem_orange.png";
import GemRed from "./assets/gem_red.png";
import GoldenApple from "./assets/golden_apple.png";
import { GameState, type Position } from "./types";
import useSnake, {
  DeathReason,
  END_LOCATION,
  type SnakePower,
  type Bomb as BombType,
  type Gem as GemType,
  type Portal as PortalType,
  type SnakeType,
} from "./useSnake";

const GRID_ROWS = 8;
const GRID_COLS = 12;

const GEMS: Record<SnakeType, string> = {
  blue: GemBlue,
  green: GemGreen,
  grey: GemGrey,
  light_blue: GemLightBlue,
  orange: GemOrange,
  dark_orange: GemRed,
  brown: "",
};

const SNAKE_COLORS: Record<
  SnakeType,
  { body: string; head: string; line?: string }
> = {
  blue: { body: "bg-[#2d45e0]", head: "bg-[#5871ff]", line: "bg-[#fd8c00]" },
  brown: { body: "bg-[#432500]", head: "bg-[#432500]" },
  green: { body: "bg-[#009934]", head: "bg-[#00e300]", line: "bg-white" },
  grey: { body: "bg-[#7e8080]", head: "bg-[#888f8f]", line: "bg-white" },
  light_blue: {
    body: "bg-[#6f9ccb]",
    head: "bg-[#8ebae1]",
    line: "bg-[#5f4131]",
  },
  orange: {
    body: "bg-[#ff9635]",
    head: "bg-[#ffc733]",
    line: "bg-[#97db62]",
  },
  dark_orange: { body: "bg-[#f27600]", head: "bg-[#ff9100]" },
};

const POWER_DESCRIPTIONS: Record<string, string> = {
  use_portals: "Uses portals",
  move_rocks: "Pushes boulders",
  eat_bombs: "Eats bombs in addition to apples",
  pass_through_walls: "Moves through walls, boulders, and apples",
  pass_through_itself: "Can intersect itself",
  ice_movement: "Slides in a straight line until it hits an obstacle",
  only_one_apple: "Eats at most 1 apple",
};

const DEATH_MESSAGES: Record<DeathReason, string> = {
  [DeathReason.HIT_WALL]: "You hit a wall!",
  [DeathReason.BOMB_EXPLODED]: "A bomb exploded!",
  [DeathReason.HIT_BOULDER]: "You hit a boulder!",
  [DeathReason.HIT_SELF]: "You hit yourself!",
  [DeathReason.TOO_MANY_APPLES]: "You ate too many apples!",
};

function getZ(powers: SnakePower[], index: number, offset: boolean) {
  if (index === 0) {
    if (powers.includes("pass_through_walls")) {
      return offset ? "z-[55]" : "z-50";
    }

    return offset ? "z-[25]" : "z-20";
  }

  if (powers.includes("pass_through_walls")) {
    return offset ? "z-[45]" : "z-40";
  }

  return offset ? "z-[15]" : "z-10";
}

function SerpentineHillsTask({
  returnToArchive,
  puzzmonData,
  teamState,
  taskSlug,
}: MonarchTaskProps) {
  const {
    gameState,
    startGame,
    snake,
    walls,
    apples,
    collectedApples,
    boulders,
    bombs,
    gems,
    collectedGems,
    snakeType,
    explosionPosition,
    portals,
    showWinAnimation,
    hideWinAnimation,
    submissionError,
    direction,
    powers,
    deathReason,
    showExplosionDelay,
  } = useSnake(puzzmonData ?? [], teamState, taskSlug);

  const snakeIndices = (row: number, col: number): number[] => {
    return snake
      .map<[{ position: Position; visible: boolean }, number]>((segment, i) => [
        segment,
        i,
      ])
      .filter(
        ([segment, _i]) =>
          segment.position.x === col &&
          segment.position.y === row &&
          segment.visible,
      )
      .map(([_segment, i]) => i);
  };

  const isApple = (row: number, col: number): boolean => {
    return apples.some(
      (apple, index) =>
        apple.x === col && apple.y === row && !collectedApples.has(index),
    );
  };

  const isBoulder = (row: number, col: number): boolean => {
    return boulders.some((boulder) => boulder.x === col && boulder.y === row);
  };

  const getBomb = (row: number, col: number): BombType | null => {
    return (
      bombs.find(
        (bomb) => bomb.position.x === col && bomb.position.y === row,
      ) || null
    );
  };

  const getGem = (row: number, col: number): GemType | null => {
    return (
      gems.find(
        (gem, index) =>
          gem.position.x === col &&
          gem.position.y === row &&
          !collectedGems.has(index),
      ) || null
    );
  };

  const getPortal = (row: number, col: number): PortalType | null => {
    return (
      portals.find(
        (portal) => portal.position.x === col && portal.position.y === row,
      ) || null
    );
  };

  const hasWallBelow = (row: number, col: number): boolean => {
    return walls.some(
      (wall) =>
        wall.direction === "horizontal" &&
        wall.from.y === row &&
        wall.from.x <= col &&
        wall.to.x >= col,
    );
  };

  const hasWallToRight = (row: number, col: number): boolean => {
    return walls.some(
      (wall) =>
        wall.direction === "vertical" &&
        wall.from.x === col &&
        wall.from.y <= row &&
        wall.to.y >= row,
    );
  };

  const renderGrid = () => {
    const cells = [];

    for (let row = -1; row < GRID_ROWS + 1; row++) {
      for (let col = -1; col < GRID_COLS + 1; col++) {
        const segmentIndices = snakeIndices(row, col);
        const hasApple = isApple(row, col);
        const hasBoulder = isBoulder(row, col);
        const bomb = getBomb(row, col);
        const gem = getGem(row, col);
        const portal = getPortal(row, col);
        const wallBelow = hasWallBelow(row, col);
        const wallRight = hasWallToRight(row, col);

        cells.push(
          <div key={`${row}-${col}`} className={cn("relative")}>
            {wallBelow && (
              <div className="absolute z-30 -bottom-1 h-2 w-full bg-black" />
            )}
            {wallRight && (
              <div className="absolute z-30 -right-1 w-2 h-full bg-black" />
            )}
            {segmentIndices.map((index) => (
              <SnakeSegment
                key={index}
                movementDirection={direction ?? "RIGHT"}
                previous={
                  index - 1 >= 0 ? snake[index - 1].position : undefined
                }
                current={snake[index].position}
                next={
                  index + 1 < snake.length
                    ? snake[index + 1].position
                    : undefined
                }
                lineClassName={
                  SNAKE_COLORS[snakeType].line
                    ? cn(
                        SNAKE_COLORS[snakeType].line,
                        getZ(powers, index, true),
                      )
                    : undefined
                }
                className={cn(
                  index === 0
                    ? SNAKE_COLORS[snakeType].head
                    : SNAKE_COLORS[snakeType].body,
                  getZ(powers, index, false),
                )}
              />
            ))}
            {hasApple && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none select-none">
                <img
                  src={GoldenApple}
                  alt="Apple"
                  className="w-4/5 h-4/5 transform-gpu drop-shadow-[0_2px_4px_rgba(0,0,0,0.75)]"
                  style={{
                    imageRendering: "pixelated",
                  }}
                />
              </div>
            )}
            {hasBoulder && (
              <div className="absolute inset-0 flex items-center justify-center z-30 pointer-events-none select-none">
                <img
                  src={Boulder}
                  alt="Boulder"
                  className="w-4/5 h-4/5 transform-gpu drop-shadow-[0_4px_6px_rgba(0,0,0,0.75)]"
                  style={{
                    imageRendering: "pixelated",
                  }}
                />
              </div>
            )}
            {bomb && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none select-none">
                <img
                  src={Bomb}
                  alt="Bomb"
                  className="w-full h-full transform-gpu drop-shadow-[0_2px_4px_rgba(0,0,0,0.75)]"
                  style={{
                    imageRendering: "pixelated",
                  }}
                />
                <div className="absolute top-0 right-0 -mt-1 -mr-1 bg-red-600 text-white text-sm font-bold rounded-full w-6 h-6 flex items-center justify-center">
                  {bomb.value}
                </div>
              </div>
            )}
            {gem && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none select-none">
                <img
                  src={GEMS[gem.snakeType]}
                  alt={`${gem.snakeType} gem`}
                  className="w-4/5 h-4/5 transform-gpu drop-shadow-[0_2px_4px_rgba(0,0,0,0.75)]"
                  style={{
                    imageRendering: "pixelated",
                  }}
                />
              </div>
            )}
            {portal && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none select-none">
                <img
                  src={portal.imageSrc}
                  alt="portal"
                  className="w-4/5 h-4/5"
                  style={{
                    imageRendering: "pixelated",
                  }}
                />
              </div>
            )}
            {END_LOCATION.x === col && END_LOCATION.y === row && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none select-none">
                <img
                  src={CheckeredFlag}
                  alt="end square"
                  className="w-4/5 h-4/5"
                  style={{
                    imageRendering: "pixelated",
                  }}
                />
              </div>
            )}
            {row === explosionPosition?.y &&
              col === explosionPosition.x &&
              (gameState === GameState.GAME_OVER || showExplosionDelay) && (
                <div className="absolute z-50 w-[300%] h-[300%] top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none select-none">
                  <img
                    src={Explosion}
                    alt="Explosion"
                    className="w-full h-full object-cover"
                    style={{
                      imageRendering: "pixelated",
                    }}
                  />
                </div>
              )}
          </div>,
        );
      }
    }
    return cells;
  };

  return (
    <MonarchTaskWrapper
      returnToArchive={returnToArchive}
      taskClassName="md:hidden lg:flex"
      warningClassName="md:flex lg:hidden"
    >
      <div className="relative w-full h-full flex flex-col justify-end items-center">
        <BackToArchiveButton
          onClick={returnToArchive}
          className="absolute top-4 left-6 z-50"
        />

        <div className="flex flex-col items-center gap-2 lg:gap-4 mt-auto w-full h-full">
          {taskSlug && teamState?.puzzles[taskSlug]?.solved ? (
            <TaskSolvedMessage teamState={teamState} taskSlug={taskSlug} />
          ) : (
            <div className="h-[42px] w-full" />
          )}

          <div className="flex gap-2 grow mb-4 min-h-0 w-full max-w-7xl">
            <div className="grow min-h-0 flex items-center justify-center">
              <div className="relative">
                <img
                  src={Background}
                  alt=""
                  className="max-h-full max-w-full block h-auto w-auto pointer-events-none select-none"
                />
                {gameState === GameState.START_SCREEN && (
                  <div className="absolute inset-0 flex items-center justify-center z-[60]">
                    <div className="flex flex-col items-center gap-4 bg-black bg-opacity-75 p-8 rounded-lg">
                      <p className="text-white text-center text-lg xl:text-2xl">
                        The Serpentine Hills Puzzmon are hungry!
                        <br />
                      </p>
                      <p className="text-sm xl:text-lg text-center">
                        Use arrow keys to move.
                        <br />
                        Eat gems to get special powers.
                      </p>
                      <button
                        onClick={startGame}
                        className="px-6 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-lg font-bold"
                      >
                        Start Game
                      </button>
                    </div>
                  </div>
                )}
                {gameState === GameState.WON &&
                  !submissionError &&
                  !showWinAnimation && (
                    <EndGameModal
                      title="Congratulations!"
                      subtitle="The Serpentine Hills Puzzmon are happy and full of apples."
                      startGame={startGame}
                      win
                    />
                  )}
                {gameState === GameState.WON && submissionError && (
                  <EndGameModal
                    title="Error"
                    subtitle={submissionError}
                    startGame={startGame}
                  />
                )}
                {gameState === GameState.GAME_OVER && (
                  <EndGameModal
                    title="Game Over!"
                    subtitle={
                      deathReason !== undefined
                        ? DEATH_MESSAGES[deathReason]
                        : "You died"
                    }
                    startGame={startGame}
                  />
                )}
                {gameState !== GameState.START_SCREEN && (
                  <div className="absolute grid top-0 left-0 w-full h-full grid-cols-[repeat(14,_minmax(0,_1fr))] grid-rows-10">
                    {renderGrid()}
                  </div>
                )}
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2">
                  {showWinAnimation && (
                    <TaskSuccessAnimation onComplete={hideWinAnimation} />
                  )}
                </div>
              </div>
            </div>

            {/* Snake Reference Cards Column */}
            <div className="w-72 flex flex-col gap-1 xl:gap-2 p-2 xl:p-4 xl:mt-2 rounded-lg overflow-y-auto shrink-0 bg-black/25">
              {puzzmonData
                ?.sort((a, b) => a.name.localeCompare(b.name))
                .map((monster) => {
                  const snakeData = monster.serpentineHillsMonarchTask;
                  if (!snakeData) return null;

                  const powers = snakeData.specialPowers;
                  const powerDescription =
                    powers.length > 0
                      ? powers
                          .map((power) => POWER_DESCRIPTIONS[power])
                          .join(", ")
                      : "Basic snake with no special abilities";

                  return (
                    <div key={monster.name} className="flex gap-3 my-0.5">
                      {/* Snake Color Square */}
                      <img
                        src={monster.imageSrc}
                        alt={monster.name}
                        className="h-12 transform-gpu drop-shadow-[0_2px_4px_rgba(0,0,0,0.75)] pointer-events-none select-none"
                      />

                      {/* Snake Info */}
                      <div className="flex-1 min-w-0">
                        <div className="font-semibold text-sm xl:text-base">
                          {monster.name}
                        </div>
                        <div className="text-sm xl:text-base italic mt-1">
                          {powerDescription}
                        </div>
                      </div>
                    </div>
                  );
                })}
            </div>
          </div>
        </div>
      </div>
    </MonarchTaskWrapper>
  );
}

export default SerpentineHillsTask;
