import { cn } from "@hunt/styled-ui";
import { useEffect, useRef } from "react";
import {
  SMALL_TALK_DELTA,
  SMALL_TALK_DELTA_INTERVAL,
  TARGET_ZONE_START,
  TARGET_ZONE_END,
} from "./constants";

type SmallTalkMeterProps = {
  value: number; // 0-100
  onChange: (fn: (prev: number) => number) => void;
  className?: string;
};

// Update more frequently for smoother animation (every ~16ms for 60fps)
const ANIMATION_INTERVAL = 16; // ms
const ANIMATION_STEPS = Math.ceil(
  SMALL_TALK_DELTA_INTERVAL / ANIMATION_INTERVAL,
);
const ANIMATION_DELTA = SMALL_TALK_DELTA / ANIMATION_STEPS;

export default function SmallTalkMeter({
  value,
  onChange,
  className,
}: SmallTalkMeterProps) {
  const decreaseIntervalRef = useRef<NodeJS.Timeout>();
  const increaseIntervalRef = useRef<NodeJS.Timeout>();
  const animationIntervalRef = useRef<NodeJS.Timeout>();
  const isSpacebarHeldRef = useRef<boolean>(false);
  const decreaseStepsRemainingRef = useRef<number>(0);
  const increaseStepsRemainingRef = useRef<number>(0);

  // Smooth animation loop - updates every ~16ms for 60fps smoothness
  useEffect(() => {
    animationIntervalRef.current = setInterval(() => {
      if (decreaseStepsRemainingRef.current > 0 && !isSpacebarHeldRef.current) {
        onChange((prev) => Math.max(0, prev - ANIMATION_DELTA));
        decreaseStepsRemainingRef.current--;
      }
      if (increaseStepsRemainingRef.current > 0 && isSpacebarHeldRef.current) {
        onChange((prev) => Math.min(100, prev + ANIMATION_DELTA));
        increaseStepsRemainingRef.current--;
      }
    }, ANIMATION_INTERVAL);

    return () => {
      if (animationIntervalRef.current)
        clearInterval(animationIntervalRef.current);
    };
  }, [onChange]);

  // Control decrease rate - spread change over multiple steps
  useEffect(() => {
    decreaseIntervalRef.current = setInterval(() => {
      if (!isSpacebarHeldRef.current) {
        decreaseStepsRemainingRef.current = ANIMATION_STEPS;
      }
    }, SMALL_TALK_DELTA_INTERVAL);

    return () => {
      if (decreaseIntervalRef.current)
        clearInterval(decreaseIntervalRef.current);
    };
  }, []);

  // Handle spacebar press and hold
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.code === "Space") {
        event.preventDefault();
        event.stopPropagation();

        if (!isSpacebarHeldRef.current) {
          isSpacebarHeldRef.current = true;
          increaseStepsRemainingRef.current = ANIMATION_STEPS;

          // Immediate increase on press
          onChange((prev) => Math.min(100, prev + ANIMATION_DELTA));
          increaseStepsRemainingRef.current--;

          // Control increase rate - spread change over multiple steps
          increaseIntervalRef.current = setInterval(() => {
            if (isSpacebarHeldRef.current) {
              increaseStepsRemainingRef.current = ANIMATION_STEPS;
            }
          }, SMALL_TALK_DELTA_INTERVAL);
        }
      }
    };

    const handleKeyUp = (event: KeyboardEvent) => {
      if (event.code === "Space") {
        event.preventDefault();
        event.stopPropagation();

        if (isSpacebarHeldRef.current) {
          isSpacebarHeldRef.current = false;
          increaseStepsRemainingRef.current = 0;

          if (increaseIntervalRef.current) {
            clearInterval(increaseIntervalRef.current);
            increaseIntervalRef.current = undefined;
          }
        }
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
      window.removeEventListener("keyup", handleKeyUp);
      if (increaseIntervalRef.current) {
        clearInterval(increaseIntervalRef.current);
      }
    };
  }, [onChange]);

  const targetZoneStart = TARGET_ZONE_START;
  const targetZoneEnd = TARGET_ZONE_END;
  const isInTargetZone = value >= targetZoneStart && value <= targetZoneEnd + 2;

  return (
    <div className={cn("relative", className)}>
      {/* Main content wrapper */}
      <div className="w-64 flex flex-col gap-2">
        {/* Label */}
        <div className="text-white text-lg font-bold">Small Talk</div>

        {/* Meter container */}
        <div className="relative w-full h-8 bg-gray-800 border-2 border-black rounded-md overflow-hidden">
          {/* Target zone background */}
          <div
            className="absolute h-full bg-green-500 opacity-30"
            style={{
              left: `${targetZoneStart}%`,
              width: `${targetZoneEnd - targetZoneStart}%`,
            }}
          />

          {/* Current value bar */}
          <div
            className={cn(
              "h-full transition-[width] duration-[100ms] ease-linear will-change-[width]",
              isInTargetZone
                ? "bg-green-400"
                : value > targetZoneEnd
                  ? "bg-red-400"
                  : "bg-yellow-400",
            )}
            style={{ width: `${value}%` }}
          />

          {/* Target zone markers */}
          <div
            className="absolute top-0 w-0.5 h-full bg-green-300"
            style={{ left: `${targetZoneStart}%` }}
          />
          <div
            className="absolute top-0 w-0.5 h-full bg-green-300"
            style={{ left: `${targetZoneEnd}%` }}
          />
        </div>

        {/* Instructions */}
        <div className="text-white text-xs text-center">
          Press SPACE to chat
        </div>
      </div>
    </div>
  );
}
