import {
  ALL_ZONES,
  MONSTER_ZONES,
  zoneToSlug,
  type MonsterDetails,
} from "@hunt/hunt-data/monarch";
import { type TeamHuntState } from "@hunt/public-client";
import { cn } from "@hunt/styled-ui";
import { ArrowRight, FlaskConical, FunnelX, HelpCircle } from "lucide-react";
import React, { useCallback } from "react";
import FilterByZone from "../../components/FilterByZone";
import { MonarchSearchField } from "../../components/MonarchSearchField";
import { slugify } from "../../lib/slug";
import { updateQueryParam } from "../../lib/url";
import { MONARCH_QUERY_KEYS } from "../../useMonarchQueryParams";
import { ZONE_TO_TASK } from "./MonarchContent";
import MonarchSection from "./MonarchSection";
import PuzzmonToggle from "./PuzzmonToggle";

const getNumTotalPuzzmon = (
  zoneDetails: Record<string, { count: number; taskPrompt?: string }>,
  selectedZone: string,
  searchTerm: string,
  numMonstersBefriended: number,
) => {
  if (searchTerm) {
    // If there is a search term, then we do not want to show any undiscovered puzzmon because they should not match any search terms.
    // Thus, we return the number of monsters befriended, which is already filtered by the search term.
    return numMonstersBefriended;
  }

  if (selectedZone !== ALL_ZONES) {
    // If a zone is selected, then we return the number of puzzmon in that zone.
    return zoneDetails[selectedZone].count;
  }

  // Otherwise, we sum up all of the zone counts to get the total number of puzzmon.
  return Object.values(zoneDetails).reduce((sum, { count }) => sum + count, 0);
};

const PuzzmonBefriendedCount = ({
  numBefriended,
  numTotal,
  hasSearch,
  withBreakpoint,
}: {
  numBefriended: number;
  numTotal: number;
  hasSearch?: boolean;
  withBreakpoint?: boolean;
}) => {
  return (
    <i className="text-monarch-light text-base">
      {hasSearch ? (
        <span className="max-sm:hidden">{numBefriended} matching Puzzmon</span>
      ) : (
        <>
          <b>
            {numBefriended}/{numTotal}
          </b>{" "}
          <span className={cn(withBreakpoint && "max-sm:hidden")}>
            Puzzmon befriended
          </span>
        </>
      )}
    </i>
  );
};

type AllPuzzmonPageProps = {
  numMonstersBefriended: number;
  searchTerm: string;
  handleSearchInput: (newSearchTerm: string) => void;
  monstersByZone: Record<string, MonsterDetails[]>;
  setSelectedMonsterName: React.Dispatch<
    React.SetStateAction<string | undefined>
  >;
  selectedZone: string;
  setSelectedZone: (zone: string) => void;
  zoneDetails: Record<string, { count: number; taskPrompt?: string }>;
  activeZones: string[];
  setZoneTaskSelected: (zone: string) => void;
  teamState?: TeamHuntState;
  isDarkMode: boolean;
  setHelpPageOpen: (isOpen: boolean) => void;
  showAllPuzzmon: boolean;
  setShowAllPuzzmon: React.Dispatch<React.SetStateAction<boolean>>;
};

function AllPuzzmonPage({
  numMonstersBefriended,
  searchTerm,
  handleSearchInput,
  monstersByZone,
  setSelectedMonsterName,
  selectedZone,
  setSelectedZone,
  zoneDetails,
  activeZones,
  setZoneTaskSelected,
  teamState,
  isDarkMode,
  setHelpPageOpen,
  showAllPuzzmon,
  setShowAllPuzzmon,
}: AllPuzzmonPageProps) {
  const updateSelectedMonster = useCallback(
    (monsterName: string) => {
      setSelectedMonsterName(monsterName);
      updateQueryParam(MONARCH_QUERY_KEYS.PUZZMON_SLUG, slugify(monsterName));
    },
    [setSelectedMonsterName],
  );
  const updateSelectedZoneTask = useCallback(
    (zoneName: string) => {
      const slug = slugify(zoneName);
      setZoneTaskSelected(slug);
      updateQueryParam(MONARCH_QUERY_KEYS.TASK, slug);
    },
    [setZoneTaskSelected],
  );

  const isCapstoneSolved = useCallback(
    (zone: string) => {
      if (!teamState) return false;
      return Object.values(teamState.puzzles).find(
        (puzzle) => puzzle.round === zoneToSlug(zone) && puzzle.is_meta,
      )?.solved;
    },
    [teamState],
  );

  const numTotalPuzzmon = getNumTotalPuzzmon(
    zoneDetails,
    selectedZone,
    searchTerm,
    numMonstersBefriended,
  );
  return (
    <div className="monarch-screen-scroll px-8 py-4 md:px-11 md:py-6 overflow-hidden overflow-y-scroll">
      {/* Header and filters. */}
      <div className="w-[800px] mx-auto mb-2">
        <div className="flex gap-4 items-start">
          <div className="flex flex-col">
            <h1 className="p-0 font-title text-6xl max-monarch-medium:text-5xl text-white transform-gpu drop-shadow-[0_0_8px_rgba(255,255,255,0.33)]">
              MonArch
            </h1>
            <p
              role="doc-subtitle"
              className="italic text-monarch-accent text-2xl max-monarch-medium:text-xl -mt-2 mb-2"
            >
              Your Monster Archive
            </p>
          </div>
          <button
            aria-label="Help"
            onClick={() => {
              updateQueryParam(MONARCH_QUERY_KEYS.PAGE, "help");
              setHelpPageOpen(true);
            }}
            className="mt-4 text-monarch-light hover:text-monarch-accent transition-colors"
          >
            <HelpCircle className="w-14 h-14 max-monarch-medium:w-12 max-monarch-medium:h-12" />
          </button>
        </div>
        {(showAllPuzzmon || numMonstersBefriended < numTotalPuzzmon) && (
          <PuzzmonToggle
            isEnabled={showAllPuzzmon}
            onToggle={() => {
              setShowAllPuzzmon((prev) => !prev);
            }}
          />
        )}
        <div className="flex items-center gap-2 text-black flex-wrap">
          <div className="max-sm:w-full">
            <MonarchSearchField
              value={searchTerm}
              onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
                handleSearchInput(event.target.value);
              }}
              onClear={() => {
                handleSearchInput("");
              }}
              placeholder="Search..."
            />
          </div>
          <div className="flex items-center gap-1 max-sm:w-full">
            <FilterByZone
              selectedItem={selectedZone}
              onValueChange={setSelectedZone}
              menuOptions={activeZones}
            />
            {selectedZone !== ALL_ZONES && (
              <button
                aria-label="Clear filter"
                onClick={() => {
                  setSelectedZone(ALL_ZONES);
                }}
                className="mr-1"
              >
                <FunnelX
                  width={22}
                  height={22}
                  className="text-monarch-light"
                />
              </button>
            )}
          </div>
          <div className="max-monarch-medium:w-full">
            <PuzzmonBefriendedCount
              numBefriended={numMonstersBefriended}
              numTotal={numTotalPuzzmon}
              hasSearch={!!searchTerm}
            />
          </div>
        </div>
      </div>
      {numTotalPuzzmon === 0 && (
        <div className="text-monarch-light text-lg">
          No matching Puzzmon found.
        </div>
      )}
      <div className="flex flex-col gap-4 pb-12">
        {Object.entries(monstersByZone)
          .filter(([groupTitle, groupEntries]) => {
            // Only show Keepers zone if it has at least one keeper
            if (
              groupTitle === (MONSTER_ZONES.KEEPERS as string) ||
              groupTitle === (MONSTER_ZONES.THE_GLITCH as string)
            ) {
              return groupEntries.length > 0;
            }
            return true;
          })
          .map(([groupTitle, groupEntries]) => {
            return (
              <div key={groupTitle}>
                <div className="flex items-center justify-between pb-1 gap-4 my-1">
                  <h3 className="p-0 m-0 text-xl flex justify-start items-center text-monarch-accent font-title transform-gpu drop-shadow-[0_2px_1px_rgba(0,0,0,0.25)]">
                    {groupTitle.toUpperCase()}
                  </h3>
                  <div className="grow flex justify-start">
                    <PuzzmonBefriendedCount
                      numBefriended={groupEntries.length}
                      numTotal={zoneDetails[groupTitle].count}
                      hasSearch={!!searchTerm}
                      withBreakpoint
                    />
                  </div>
                  <div
                    className={cn(
                      "max-md:grow flex justify-end",
                      (!isCapstoneSolved(groupTitle) ||
                        !(slugify(groupTitle) in ZONE_TO_TASK)) &&
                        "invisible",
                    )}
                  >
                    <button
                      className={`flex items-center gap-1 bg-monarch-accent-green text-sm italic text-monarch-dark
                        rounded-full px-4 py-px ml-1 shadow-[inset_0_0_10px_#01640F,0_0_6px_var(--secondary-blue)]
                        hover:brightness-110 hover:shadow-[inset_0_0_10px_#01640F,0_0_6px_var(--monarch-accent-green)]
                        focus-visible:brightness-110 focus-visible:outline-monarch-accent px-2 gap-0.5`}
                      onClick={(): void => {
                        updateSelectedZoneTask(groupTitle);
                      }}
                    >
                      <FlaskConical className="h-4 w-4" />
                      <span className="max-md:hidden">
                        {zoneDetails[groupTitle].taskPrompt ??
                          "Interact with Puzzmon"}
                      </span>
                      <ArrowRight className="h-5 w-5" />
                    </button>
                  </div>
                </div>
                <MonarchSection
                  monsterDataList={groupEntries}
                  updateSelectedMonster={updateSelectedMonster}
                  totalCount={zoneDetails[groupTitle].count}
                  hideUndiscoveredPuzzmon={!!searchTerm}
                  isDarkMode={isDarkMode}
                  zone={groupTitle}
                />
              </div>
            );
          })}
      </div>
    </div>
  );
}

export default AllPuzzmonPage;
