import React from "react";

/**
 * Parses a description string and converts HTML-like tags to React elements.
 * Supports <strike>...</strike> for strikethrough and <i>...</i> for italics.
 * Tags are not nested - each tag is processed independently.
 */
export const parseDescription = (text: string | undefined): React.ReactNode => {
  if (!text) return text;

  const parts: React.ReactNode[] = [];
  let currentIndex = 0;

  // Regex to match opening/closing tags (non-greedy to match the first closing tag)
  const tagRegex = /<(strike|i)>(.*?)<\/\1>/g;
  let match;

  while ((match = tagRegex.exec(text)) !== null) {
    // Add text before the tag
    if (match.index > currentIndex) {
      const beforeText = text.slice(currentIndex, match.index);
      if (beforeText) {
        parts.push(beforeText);
      }
    }

    // Process the tag content (no nesting, so use directly)
    const tagType = match[1];
    const tagContent = match[2];

    // Apply the appropriate formatting
    if (tagType === "strike") {
      parts.push(
        React.createElement(
          "span",
          {
            key: `strike-${match.index}`,
            className: "line-through",
          },
          tagContent,
        ),
      );
    } else if (tagType === "i") {
      parts.push(
        React.createElement(
          "span",
          {
            key: `italic-${match.index}`,
            className: "italic",
          },
          tagContent,
        ),
      );
    }

    currentIndex = match.index + match[0].length;
  }

  // Add any remaining text after the last tag
  if (currentIndex < text.length) {
    const remainingText = text.slice(currentIndex);
    if (remainingText) {
      parts.push(remainingText);
    }
  }

  // If no tags were found, return the original text
  if (parts.length === 0) {
    return text;
  }

  return parts.length === 1
    ? parts[0]
    : React.createElement(React.Fragment, {}, ...parts);
};
