type RatingState = Record<string, number>;

// Mapping from full category names to abbreviations
const CATEGORY_ABBREVIATIONS: Record<string, string> = {
  Strength: "STR",
  Dexterity: "DEX",
  Constitution: "CON",
  Intelligence: "INT",
  Wisdom: "WIS",
  Charisma: "CHA",
};

// Radar chart component
function RadarChart({
  categories,
  ratings,
  size,
}: {
  categories: string[];
  ratings: RatingState;
  size: number;
}) {
  const padding = 20; // Minimal padding for labels to prevent clipping
  const center = size / 2;
  const radius = size * 0.5; // Chart radius - increased to fill more space
  const numPoints = categories.length;
  const angleStep = (2 * Math.PI) / numPoints;

  // Calculate points for the polygon based on ratings
  const getPoint = (index: number, value: number) => {
    const angle = index * angleStep - Math.PI / 2; // Start from top
    const distance = (radius * value) / 5; // Scale 1-5 to 0-radius
    const x = center + distance * Math.cos(angle);
    const y = center + distance * Math.sin(angle);
    return { x, y };
  };

  // Create grid lines (circles for each rating level) - softer, more organic
  const gridLines = [1, 2, 3, 4, 5].map((level) => {
    const r = (radius * level) / 5;
    const opacity = 0.3 + (level / 5) * 0.2; // Gradually increase opacity for better contrast
    return (
      <circle
        key={level}
        cx={center}
        cy={center}
        r={r}
        fill="none"
        stroke="#b45309" // Darker amber for better contrast
        strokeWidth={level === 5 ? "2" : "1.5"}
        strokeOpacity={opacity}
      />
    );
  });

  // Create axis lines - softer, more feather-like
  const axisLines = categories.map((_, index) => {
    const angle = index * angleStep - Math.PI / 2;
    const x = center + radius * Math.cos(angle);
    const y = center + radius * Math.sin(angle);
    return (
      <line
        key={index}
        x1={center}
        y1={center}
        x2={x}
        y2={y}
        stroke="#b45309" // Darker amber for better contrast
        strokeWidth="1.5"
        strokeOpacity="0.35"
      />
    );
  });

  // Create data polygon
  const points = categories
    .map((category, index) => {
      const value = ratings[category] ?? 0;
      const point = getPoint(index, value);
      return `${point.x},${point.y}`;
    })
    .join(" ");

  // Create labels
  const labels = categories.map((category, index) => {
    const angle = index * angleStep - Math.PI / 2;
    const labelRadius = radius + 20; // Position labels further from the chart
    const x = center + labelRadius * Math.cos(angle);
    const y = center + labelRadius * Math.sin(angle);
    const abbreviation = CATEGORY_ABBREVIATIONS[category] || category;
    return (
      <text
        key={category}
        x={x}
        y={y}
        textAnchor="middle"
        dominantBaseline="middle"
        className="fill-black"
        style={{ fontSize: "14px", fontWeight: "500" }}
      >
        {abbreviation}
      </text>
    );
  });

  return (
    <div className="w-48 h-48 flex items-center justify-center overflow-visible">
      <svg
        width={size}
        height={size}
        viewBox={`-${padding} -${padding} ${size + padding * 2} ${size + padding * 2}`}
        style={{ overflow: "visible" }}
        preserveAspectRatio="xMidYMid meet"
      >
        {/* Grid circles */}
        {gridLines}
        {/* Axis lines */}
        {axisLines}
        {/* Gradient definition for bird-themed colors */}
        <defs>
          <linearGradient id="birdGradient" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="#f59e0b" stopOpacity="0.5" />
            <stop offset="100%" stopColor="#d97706" stopOpacity="0.4" />
          </linearGradient>
          <linearGradient id="birdStroke" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#b45309" />
            <stop offset="100%" stopColor="#92400e" />
          </linearGradient>
        </defs>
        {/* Data polygon with bird-themed styling */}
        {points && (
          <>
            <polygon
              points={points}
              fill="url(#birdGradient)"
              stroke="url(#birdStroke)"
              strokeWidth="3"
              strokeLinejoin="round"
              className="transform-gpu drop-shadow-[0_2px_4px_rgba(180,83,9,0.4)]"
            />
          </>
        )}
        {/* Labels */}
        {labels}
      </svg>
    </div>
  );
}

export default RadarChart;
