import {
  DndContext,
  DragOverlay,
  useSensors,
  useSensor,
  PointerSensor,
  pointerWithin,
  type DragStartEvent,
  type DragEndEvent,
} from "@dnd-kit/core";
import { snapCenterToCursor } from "@dnd-kit/modifiers";
import {
  type TileSection,
  type Tile,
  type PuzzmonPreferences,
  useGlobalVolume,
} from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import { RotateCcw } from "lucide-react";
import { useState, useCallback } from "react";
import { createPortal } from "react-dom";
import { GridGameBoard } from "./GridGameBoard";
import { ScoreDisplay } from "./ScoreDisplay";
import { TILE_STYLE, TileList } from "./TileList";
import dropSound from "./assets/drop_sound.mp3";
import resetSound from "./assets/reset_sound.mp3";

type GridTabProps = {
  gridState?: (Tile | null)[][];
  tiles: TileSection[];
  preferencesData: PuzzmonPreferences[];
  score: number;
  goal: number;
  handleTilePlace: (
    tile: Tile & { fromGrid?: boolean; gridRow?: number; gridCol?: number },
    row: number,
    col: number,
  ) => void;
  handleTileRemove: (row: number, col: number) => void;
  handleReset: () => void;
};

export const GridTab = ({
  gridState,
  tiles,
  preferencesData,
  score,
  goal,
  handleTilePlace,
  handleTileRemove,
  handleReset,
}: GridTabProps) => {
  const defaultGrid: (Tile | null)[][] = Array.from({ length: 5 }, () =>
    Array.from({ length: 5 }, () => null),
  );
  const currentGridState = gridState ?? defaultGrid;
  const globalVolume = useGlobalVolume();

  const [draggedTile, setDraggedTile] = useState<
    (Tile & { fromGrid?: boolean; gridRow?: number; gridCol?: number }) | null
  >(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    }),
  );

  const handleDragStart = useCallback((event: DragStartEvent) => {
    const { active } = event;
    const data = active.data.current as Tile & {
      fromGrid?: boolean;
      gridRow?: number;
      gridCol?: number;
    };
    if (data) {
      setDraggedTile(data);
    }
  }, []);

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const { over, active } = event;
      const dropTargetData = over?.data.current as {
        row: number;
        col: number;
        type: string;
      };
      const activeTileData = active?.data.current as Tile & {
        fromGrid?: boolean;
        gridRow?: number;
        gridCol?: number;
      };

      if (dropTargetData && activeTileData) {
        if (dropTargetData.type === "grid-cell") {
          // If dragging from grid to same cell, do nothing
          if (
            activeTileData.fromGrid &&
            activeTileData.gridRow === dropTargetData.row &&
            activeTileData.gridCol === dropTargetData.col
          ) {
            setDraggedTile(null);
            return;
          }
          handleTilePlace(
            activeTileData,
            dropTargetData.row,
            dropTargetData.col,
          );
          try {
            const audio = new Audio(dropSound);
            audio.volume = globalVolume;
            void audio.play();
          } catch {
            // Ignore sound errors.
          }
        }
      } else {
        // If not dropped on a valid drop target and dragged from grid, remove it
        if (
          activeTileData?.fromGrid &&
          activeTileData.gridRow !== undefined &&
          activeTileData.gridCol !== undefined
        ) {
          handleTileRemove(activeTileData.gridRow, activeTileData.gridCol);
        }
      }

      setDraggedTile(null);
    },
    [globalVolume, handleTilePlace, handleTileRemove],
  );

  return (
    <DndContext
      sensors={sensors}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      collisionDetection={pointerWithin}
    >
      <div className="p-6 h-full w-full flex flex-col">
        {/* Score display at the top */}
        {/* Main content area */}
        <div className="flex h-full w-full gap-6 flex-1 min-h-0 relative">
          {/* Left section - Game Board (auto width) */}
          <GridGameBoard
            onTilePlace={handleTilePlace}
            onTileRemove={handleTileRemove}
            gridState={currentGridState}
            draggedTile={draggedTile}
            preferencesData={preferencesData}
          />

          <div className="flex flex-col gap-2 w-full">
            <div className="flex items-center justify-between gap-2">
              <button
                type="button"
                className="flex items-center gap-2 text-monarch-dark border-[3px] border-monarch-dark font-bold rounded-full pl-3 pr-4 py-1 bg-[#D5B893] hover:brightness-75 focus-visible:brightness-75 active:brightness-75 select-none"
                onClick={() => {
                  handleReset();
                  try {
                    const audio = new Audio(resetSound);
                    audio.volume = globalVolume;
                    void audio.play();
                  } catch {
                    // Ignore sound errors.
                  }
                }}
              >
                <RotateCcw height={16} width={16} strokeWidth={3} />
                Reset
              </button>
              <ScoreDisplay score={score} goal={goal} />
            </div>
            {/* Right section - Tile List (fills remaining space) */}
            <div className="flex-1 min-h-0 overflow-hidden">
              <TileList sections={tiles} />
            </div>
          </div>
        </div>
      </div>
      {createPortal(
        <DragOverlay dropAnimation={null} modifiers={[snapCenterToCursor]}>
          {draggedTile && (
            <div className={cn(TILE_STYLE, "cursor-grabbing")}>
              <img
                src={draggedTile.image}
                alt={draggedTile.name}
                className="w-full h-full object-contain"
              />
            </div>
          )}
        </DragOverlay>,
        document.body,
      )}
    </DndContext>
  );
};
