import {
  MONSTER_DATA,
  MONSTER_ZONES,
  type MonsterDetails,
} from "@hunt/hunt-data/monarch";
import { useCallback, useEffect, useMemo, useState } from "react";

const SESSION_STORAGE_KEY = "old_bark_town_puzzle";

export type Square = {
  x: number;
  y: number;
};

enum Direction {
  LEFT,
  RIGHT,
  UP,
  DOWN,
  NONE,
}

export enum PipeType {
  ENDPOINT,
  ENDPOINT_LEFT,
  ENDPOINT_RIGHT,
  ENDPOINT_UP,
  ENDPOINT_DOWN,
  HORIZONTAL,
  VERTICAL,
  NW_CORNER,
  NE_CORNER,
  SW_CORNER,
  SE_CORNER,
}

export type Path = {
  squares: Square[];
};

type FlowNode = {
  type: "puzzmon" | "item";
  id: string;
  puzzmonId: string;
};

export const checkAnswerImpl = (paths: Path[]): boolean => {
  const oldBarkTownMap = MONSTER_DATA[MONSTER_ZONES.OLD_BARK_TOWN];
  const monsterData = Object.values(oldBarkTownMap).filter(
    (
      details,
    ): details is MonsterDetails & {
      fetchableItems: NonNullable<MonsterDetails["fetchableItems"]>;
    } => {
      return Array.isArray(details.fetchableItems);
    },
  );

  const matchedPuzzmon = paths.map((path) => {
    const nodes = path.squares
      .map((square) => findNode(square, monsterData))
      .filter((puzzmon) => puzzmon !== undefined);

    // For a path to be valid, it must have 3 nodes (2 fetchable items and 1 puzzmon),
    // all must be for the same puzzmon, the puzzmon must be the middle node, and the
    // two items on the ends must be different.
    if (
      nodes.length !== 3 ||
      nodes[0].puzzmonId !== nodes[1].puzzmonId ||
      nodes[1].puzzmonId !== nodes[2].puzzmonId ||
      nodes[0].type !== "item" ||
      nodes[1].type !== "puzzmon" ||
      nodes[2].type !== "item" ||
      nodes[0].id === nodes[2].id
    ) {
      return undefined;
    }

    return nodes[0].puzzmonId;
  });

  // If any of the paths are invalid then this is an incorrect solution.
  if (matchedPuzzmon.some((m) => m === undefined)) {
    return false;
  }

  // If we don't have all the puzzmon then this is an incorrect solution.
  if (new Set(matchedPuzzmon).size < monsterData.length) {
    return false;
  }

  // If the solution doesn't cover all the squares in the grid then it's invalid.
  const sum = paths
    .map((path) => path.squares.length)
    .reduce((acc, curr) => curr + acc, 0);
  return sum === 8 * 12;
};

// Map from incoming direction -> outgoing direction -> pipe type.
const PIPE_TYPES: Record<Direction, Record<Direction, PipeType | undefined>> = {
  [Direction.LEFT]: {
    [Direction.LEFT]: PipeType.HORIZONTAL,
    // Direction.RIGHT would mean the path doubles back on itself.
    [Direction.RIGHT]: undefined,
    [Direction.UP]: PipeType.NE_CORNER,
    [Direction.DOWN]: PipeType.SE_CORNER,
    [Direction.NONE]: PipeType.ENDPOINT_RIGHT,
  },
  [Direction.RIGHT]: {
    // Direction.LEFT would mean the path doubles back on itself.
    [Direction.LEFT]: undefined,
    [Direction.RIGHT]: PipeType.HORIZONTAL,
    [Direction.UP]: PipeType.NW_CORNER,
    [Direction.DOWN]: PipeType.SW_CORNER,
    [Direction.NONE]: PipeType.ENDPOINT_LEFT,
  },
  [Direction.UP]: {
    [Direction.LEFT]: PipeType.SW_CORNER,
    [Direction.RIGHT]: PipeType.SE_CORNER,
    [Direction.UP]: PipeType.VERTICAL,
    // Direction.DOWN would mean the path doubles back on itself.
    [Direction.DOWN]: undefined,
    [Direction.NONE]: PipeType.ENDPOINT_DOWN,
  },
  [Direction.DOWN]: {
    [Direction.LEFT]: PipeType.NW_CORNER,
    [Direction.RIGHT]: PipeType.NE_CORNER,
    [Direction.DOWN]: PipeType.VERTICAL,
    // Direction.UP would mean the path doubles back on itself.
    [Direction.UP]: undefined,
    [Direction.NONE]: PipeType.ENDPOINT_UP,
  },
  [Direction.NONE]: {
    [Direction.LEFT]: PipeType.ENDPOINT_LEFT,
    [Direction.RIGHT]: PipeType.ENDPOINT_RIGHT,
    [Direction.DOWN]: PipeType.ENDPOINT_DOWN,
    [Direction.UP]: PipeType.ENDPOINT_UP,
    [Direction.NONE]: PipeType.ENDPOINT,
  },
};

const adjacent = (square1: Square, square2: Square) => {
  return (
    (square1.x === square2.x && Math.abs(square1.y - square2.y) === 1) ||
    (Math.abs(square1.x - square2.x) === 1 && square1.y === square2.y)
  );
};

const findContainingPathIndex = (square: Square, paths: Path[]): number => {
  return paths.findIndex(({ squares }) =>
    squares.some((s) => s.x === square.x && s.y === square.y),
  );
};

const deltaToDirection = (delta: { dx: number; dy: number } | undefined) => {
  if (delta === undefined) {
    return Direction.NONE;
  } else if (delta.dx === 1 && delta.dy === 0) {
    return Direction.DOWN;
  } else if (delta.dx === -1 && delta.dy === 0) {
    return Direction.UP;
  } else if (delta.dx === 0 && delta.dy === 1) {
    return Direction.RIGHT;
  } else if (delta.dx === 0 && delta.dy === -1) {
    return Direction.LEFT;
  } else {
    throw new Error("Bug! in deltaToDirection");
  }
};

const concatPaths = (
  currentPath: Path,
  previousPath: Path,
  previous: Square,
  square: Square,
): Square[] => {
  if (
    equal(square, currentPath.squares[0]) &&
    equal(previous, previousPath.squares[0])
  ) {
    // Extending the beginning of one path onto the beginning of another path.
    return previousPath.squares.reverse().concat(currentPath.squares);
  } else if (
    equal(square, currentPath.squares[0]) &&
    equal(previous, previousPath.squares.at(-1))
  ) {
    // Extending the end of one path onto the beginning of another path.
    return previousPath.squares.concat(currentPath.squares);
  } else if (
    equal(square, currentPath.squares.at(-1)) &&
    equal(previous, previousPath.squares[0])
  ) {
    // Extending the beginning of one path onto the end of another path.
    return currentPath.squares.concat(previousPath.squares);
  } else if (
    equal(square, currentPath.squares.at(-1)) &&
    equal(previous, previousPath.squares.at(-1))
  ) {
    // Extending the end of one path onto the end of another path.
    return previousPath.squares.concat(currentPath.squares.reverse());
  } else {
    throw new Error("Bug! in concatPaths");
  }
};

const equal = (s1: Square | undefined, s2: Square | undefined): boolean => {
  // For the purposes of comparing squares, I think we don't want to consider undefined to be equal to
  // undefined. If this ever happens then it was probably unintended, and we should try to ignore it.
  return s1 !== undefined && s2 !== undefined && s1.x === s2.x && s1.y === s2.y;
};

const findNode = (
  square: Square,
  monsterData: MonsterDetails[],
): FlowNode | undefined => {
  for (const puzzmon of monsterData) {
    if (puzzmon.position?.x === square.x && puzzmon.position?.y === square.y) {
      return {
        type: "puzzmon",
        id: puzzmon.name,
        puzzmonId: puzzmon.name,
      };
    }

    for (const item of puzzmon.fetchableItems ?? []) {
      if (item.position?.x === square.x && item.position?.y === square.y) {
        return {
          type: "item",
          id: item.alt,
          puzzmonId: puzzmon.name,
        };
      }
    }
  }

  return undefined;
};

const useFlowGame = (puzzmonData: MonsterDetails[], onComplete: () => void) => {
  const [dragging, setDragging] = useState(false);
  const [paths, setPaths] = useState<Path[]>([]);
  const [previous, setPrevious] = useState<Square | undefined>();
  const [complete, setComplete] = useState<boolean>(false);

  useEffect(() => {
    const item = window.sessionStorage.getItem(SESSION_STORAGE_KEY);
    if (item !== null) {
      try {
        const parsed: unknown = JSON.parse(item);
        if (
          Array.isArray(parsed) &&
          parsed.every(
            (p) =>
              typeof p === "object" &&
              p !== null &&
              Array.isArray((p as { squares?: unknown }).squares) &&
              (p as { squares: unknown[] }).squares.every(
                (s) =>
                  typeof s === "object" &&
                  s !== null &&
                  typeof (s as { x?: unknown }).x === "number" &&
                  typeof (s as { y?: unknown }).y === "number",
              ),
          )
        ) {
          setPaths(parsed as Path[]);
        }
      } catch {
        // ignore invalid persisted state
      }
    }
  }, []);

  useEffect(() => {
    window.sessionStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(paths));
  }, [paths]);

  const handlePathUpdate = useCallback(
    (square: Square) => {
      if (previous === undefined) {
        throw new Error("Bug! in handlePathUpdate");
      }

      const containingPathIndex = findContainingPathIndex(square, paths);
      const previousContainingPathIndex = findContainingPathIndex(
        previous,
        paths,
      );
      const containingPath = paths[containingPathIndex];
      const previousContainingPath = paths[previousContainingPathIndex];
      if (adjacent(previous, square) && !containingPath) {
        // Previous is in the current path and square is not => extend the current path.
        if (equal(previous, previousContainingPath.squares.at(-1))) {
          // If previous is at the end of the path the append the new square.
          previousContainingPath.squares.push(square);
        } else if (equal(previous, previousContainingPath.squares[0])) {
          // If previous is at the beginning of the path then prepend the new square.
          previousContainingPath.squares = [square].concat(
            previousContainingPath.squares,
          );
        } else {
          return;
        }
        setPaths([...paths]);
        setPrevious(square);
      } else if (
        containingPath &&
        previousContainingPath &&
        containingPath !== previousContainingPath &&
        (equal(square, containingPath.squares.at(-1)) ||
          equal(square, containingPath.squares[0]))
      ) {
        // Linking two paths.
        paths[containingPathIndex].squares = concatPaths(
          containingPath,
          previousContainingPath,
          previous,
          square,
        );
        paths.splice(previousContainingPathIndex, 1);
        setPaths([...paths]);
        setPrevious(undefined);
        setDragging(false);
      } else if (
        containingPath &&
        previousContainingPath === containingPath &&
        containingPath.squares.length > 1 &&
        ((equal(previous, containingPath.squares.at(-1)) &&
          equal(square, containingPath.squares.at(-2))) ||
          (equal(previous, containingPath.squares[0]) &&
            equal(square, containingPath.squares[1])))
      ) {
        // Going back along a path to erase it.
        if (
          equal(previous, containingPath.squares.at(-1)) &&
          equal(square, containingPath.squares.at(-2))
        ) {
          // Erasing from the end of the path.
          containingPath.squares = containingPath.squares.slice(0, -1);
        } else if (
          equal(square, containingPath.squares[1]) &&
          equal(previous, containingPath.squares[0])
        ) {
          // Erasing from the beginning of the path.
          containingPath.squares = containingPath.squares.slice(1);
        } else {
          throw new Error("Bug! in erasing");
        }

        setPrevious(square);
        setPaths([...paths]);
      } else if (containingPath && containingPath === previousContainingPath) {
        const squareIndex = containingPath.squares.findIndex((s) =>
          equal(square, s),
        );
        const previousIndex = containingPath.squares.findIndex((s) =>
          equal(previous, s),
        );
        if (
          previousIndex > 0 &&
          previousIndex < containingPath.squares.length - 1 &&
          Math.abs(squareIndex - previousIndex) === 1
        ) {
          // We want to split the current path.
          paths[previousContainingPathIndex] = {
            squares: containingPath.squares.slice(
              0,
              Math.min(squareIndex, previousIndex) + 1,
            ),
          };
          paths.push({
            squares: containingPath.squares.slice(
              Math.max(squareIndex, previousIndex),
            ),
          });
          setPrevious(square);
          setPaths([...paths]);
        }
      }
    },
    [paths, previous],
  );

  const checkCompletion = useCallback(() => {
    const total = paths.reduce((acc, curr) => acc + curr.squares.length, 0);
    // If the grid isn't full yet then the answer is definitely incorrect and we can exit early to save
    // a request to the backend.
    if (total !== 8 * 12) {
      setComplete(false);
      return;
    }

    setComplete(checkAnswerImpl(paths));
  }, [paths]);

  const onCellEnter = useCallback(
    (square: Square) => {
      if (!dragging) {
        return;
      }
      handlePathUpdate(square);
      checkCompletion();
    },
    [checkCompletion, dragging, handlePathUpdate],
  );

  const onDragStart = useCallback(
    (square: Square) => {
      const pathIndex = findContainingPathIndex(square, paths);

      setPrevious(square);
      setDragging(true);
      if (pathIndex < 0) {
        setPaths(paths.concat([{ squares: [square] }]));
      }

      checkCompletion();
    },
    [paths, checkCompletion],
  );

  const onDragEnd = useCallback(
    (square: Square) => {
      const pathIndex = findContainingPathIndex(square, paths);
      if (pathIndex >= 0 && paths[pathIndex].squares.length === 1) {
        paths.splice(pathIndex, 1);
        setPaths([...paths]);
      }

      setDragging(false);
      setPrevious(undefined);
    },
    [paths],
  );

  const getPipeType = useCallback(
    (square: Square): PipeType | undefined => {
      const path = paths[findContainingPathIndex(square, paths)];
      if (!path) {
        return undefined;
      }

      const index = path.squares.findIndex(
        (s) => square.x === s.x && square.y === s.y,
      );

      const prev = index > 0 ? path.squares[index - 1] : undefined;
      const next =
        index < path.squares.length - 1 ? path.squares[index + 1] : undefined;

      const incomingDelta = prev
        ? {
            dx: square.x - prev.x,
            dy: square.y - prev.y,
          }
        : undefined;
      const outgoingDelta = next
        ? {
            dx: next.x - square.x,
            dy: next.y - square.y,
          }
        : undefined;

      return PIPE_TYPES[deltaToDirection(incomingDelta)][
        deltaToDirection(outgoingDelta)
      ];
    },
    [paths],
  );

  const getNodeColorMask = useCallback(
    (square: Square): string | undefined => {
      const node = findNode(square, puzzmonData);
      if (node === undefined) {
        return undefined;
      }

      const containingPathIndex = findContainingPathIndex(square, paths);
      if (containingPathIndex === -1) {
        return undefined;
      }

      const foundMatching = paths[containingPathIndex].squares.reduce<
        FlowNode[]
      >((acc, curr) => {
        const n = findNode(curr, puzzmonData);
        return n?.puzzmonId === node.puzzmonId ? acc.concat(n) : acc;
      }, []);
      // The path needs to have a node at `square` + two other nodes matching it, and the middle one
      // needs to be the dog.
      if (
        foundMatching.length === 3 &&
        foundMatching[0].type === "item" &&
        foundMatching[1].type === "puzzmon" &&
        foundMatching[2].type === "item"
      ) {
        return "bg-green-400 opacity-50";
      }

      return undefined;
    },
    [puzzmonData, paths],
  );

  const clear = useCallback(() => {
    setPaths([]);
  }, []);

  useEffect(() => {
    if (complete) {
      onComplete();
    }
  }, [complete, onComplete]);

  const result = useMemo(
    () => ({
      onCellEnter,
      onDragStart,
      onDragEnd,
      getPipeType,
      complete,
      getNodeColorMask,
      clear,
    }),
    [
      onCellEnter,
      onDragEnd,
      onDragStart,
      getPipeType,
      complete,
      getNodeColorMask,
      clear,
    ],
  );

  return result;
};

export default useFlowGame;
