import confetti from "canvas-confetti";

const getConfetti = () => {
  const colors = ["#f3e372", "#eb476d", "#3c87d2", "#00d219"];
  void confetti({
    particleCount: 300,
    angle: 60,
    spread: 80,
    origin: { x: -0.2, y: 0.9 },
    startVelocity: 80,
    gravity: 0.25,
    colors: colors,
  });
  void confetti({
    particleCount: 300,
    angle: 120,
    spread: 80,
    origin: { x: 1.2, y: 0.9 },
    startVelocity: 80,
    gravity: 0.25,
    colors: colors,
  });

  // Use setTimeout to ensure canvas is created.
  const timeout = setTimeout(() => {
    const canvases = document.querySelectorAll("canvas");
    canvases.forEach((canvas) => {
      // Check if this is a confetti canvas (typically has specific styling)
      const style = window.getComputedStyle(canvas);
      if (
        style.position === "fixed" &&
        (style.pointerEvents === "none" || style.pointerEvents === "")
      ) {
        canvas.style.zIndex = "9999";
      }
    });
  }, 0);

  return () => {
    clearTimeout(timeout);
  };
};

export default getConfetti;
