import { CopyToClipboard } from "@hunt/copy-to-clipboard";
import { Button } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { ArrowLeft, Check, Copy } from "lucide-react";
import React from "react";

export const MONARCH_BUTTON_STYLING = `
    no-copy
    font-body text-white font-semibold pl-4 pr-5 py-2.5
    max-lg:text-sm max-xl:text-base text-xl
    max-md:pl-2 max-lg:pl-2.5 max-xl:pl-3 max-md:pr-3 max-lg:pr-3.5 max-xl:pr-4 max-md:py-1 max-lg:py-1.5 max-xl:py-2
    bg-[#153A62]/80 max-md:border-2 border-[3px] border-monarch-border dark:border-monarch-dark-border rounded-full
    box-border shadow-[0_0_10px_rgba(0,179,255,0.4)]
    hover:bg-[#153A62]/80 focus-visible:bg-[#153A62]/80
    hover:text-white focus-visible:text-white
    hover:scale-105 focus-visible:scale-105 active:scale-100
    hover:brightness-110 focus-visible:brightness-110 active:brightness-100
    hover:shadow-[0_0_10px_rgba(0,179,255,0.8)] focus-visible:shadow-[0_0_10px_rgba(0,179,255,0.8)] active:shadow-[0_0_10px_rgba(0,179,255,0.4)]
    focus-visible:outline-none
`;

type MonarchButtonProps = {
  children: React.ReactNode;
  onClick: () => void;
};

export function MonarchButton({ children, onClick }: MonarchButtonProps) {
  return (
    <Button className={MONARCH_BUTTON_STYLING} onClick={onClick}>
      {children}
    </Button>
  );
}

type BackToArchiveButtonProps = {
  onClick: () => void;
  className?: string;
};

export function BackToArchiveButton({
  onClick,
  className,
}: BackToArchiveButtonProps) {
  return (
    <div className={cn("flex z-10", className)}>
      <MonarchButton onClick={onClick}>
        <ArrowLeft className="max-lg:w-4 max-xl:w-5 w-6" />
        <div>
          Back<span className="max-md:hidden">{" to archive"}</span>
        </div>
      </MonarchButton>
    </div>
  );
}

type CopyMonarchEntryButtonProps = {
  contentId?: string;
};

export function CopyMonarchEntryButton({
  contentId,
}: CopyMonarchEntryButtonProps) {
  return (
    <CopyToClipboard
      iconClassName={MONARCH_BUTTON_STYLING}
      icon={
        <div className="flex items-center justify-center gap-2 max-lg:w-[109px] max-xl:w-[126px] w-[155px]">
          <Copy className="max-xl:w-5 w-6" />
          Copy all info
        </div>
      }
      iconAfterCopy={
        <div className="flex items-center justify-center gap-2 max-lg:w-[109px] max-xl:w-[126px] w-[155px]">
          <Check className="max-xl:w-5 w-6" />
          Copied!
        </div>
      }
      contentId={contentId}
      variant="custom"
      hideTooltip
    />
  );
}
