import { useState, useCallback, useEffect, useMemo } from "react";

export type GridPuzzmon = {
  id: string;
  name: string;
  image: string;
  slug: string;
  row: number;
  col: number;
  order: number;
  input: string;
  output: string;
  otherText?: string;
};

const STORAGE_KEY_PREFIX = "prismatic_paths_grid_state";

export const useGridState = (level: number) => {
  const getStorageKey = useCallback(
    (lvl: number) => `${STORAGE_KEY_PREFIX}_level_${lvl}`,
    [],
  );

  const loadStateForLevel = useCallback(
    (lvl: number): (GridPuzzmon | null)[][] => {
      if (typeof window === "undefined") {
        return Array.from({ length: 5 }, () =>
          Array.from({ length: 7 }, () => null),
        );
      }
      try {
        const saved = localStorage.getItem(getStorageKey(lvl));
        if (saved) {
          return JSON.parse(saved) as (GridPuzzmon | null)[][];
        }
      } catch (error) {
        console.warn(
          `Failed to load grid state for level ${lvl} from local storage:`,
          error,
        );
      }
      return Array.from({ length: 5 }, () =>
        Array.from({ length: 7 }, () => null),
      );
    },
    [getStorageKey],
  );

  // Track modifications per level using state (triggers re-renders)
  const [modificationsMap, setModificationsMap] = useState<
    Map<number, (GridPuzzmon | null)[][]>
  >(new Map());

  // Derive base grid state synchronously from level using useMemo
  // This ensures gridState updates immediately when level changes
  const baseGridState = useMemo(() => {
    return loadStateForLevel(level);
  }, [level, loadStateForLevel]);

  // Get modifications for current level, or use base state if no modifications
  const gridState = useMemo(() => {
    const modifications = modificationsMap.get(level);
    if (modifications) {
      return modifications;
    }
    return baseGridState;
  }, [level, baseGridState, modificationsMap]);

  const updateGridState = useCallback(
    (updater: (prev: (GridPuzzmon | null)[][]) => (GridPuzzmon | null)[][]) => {
      setModificationsMap((prevMap) => {
        const newMap = new Map(prevMap);
        const currentModifications = newMap.get(level) ?? baseGridState;
        const newState = updater(currentModifications);
        newMap.set(level, newState);
        return newMap;
      });
    },
    [level, baseGridState],
  );

  // Save to local storage whenever grid state changes
  useEffect(() => {
    if (typeof window === "undefined") return;
    try {
      const key = getStorageKey(level);
      localStorage.setItem(key, JSON.stringify(gridState));
    } catch (error) {
      console.warn("Failed to save grid state to local storage:", error);
    }
  }, [gridState, level, getStorageKey]);

  const handlePuzzmonPlace = useCallback(
    (
      puzzmon: GridPuzzmon & {
        fromGrid?: boolean;
        gridRow?: number;
        gridCol?: number;
      },
      row: number,
      col: number,
    ) => {
      updateGridState((prev) => {
        const newGrid = prev.map((r) => [...r]);

        // If puzzmon is coming from grid, clear its old position
        if (
          puzzmon.fromGrid &&
          puzzmon.gridRow !== undefined &&
          puzzmon.gridCol !== undefined
        ) {
          newGrid[puzzmon.gridRow][puzzmon.gridCol] = null;
        }

        // Place puzzmon in new position
        newGrid[row][col] = puzzmon;
        return newGrid;
      });
    },
    [updateGridState],
  );

  const handlePuzzmonRemove = useCallback(
    (row: number, col: number) => {
      updateGridState((prev) => {
        const newGrid = [...prev];
        newGrid[row] = [...newGrid[row]];
        newGrid[row][col] = null;
        return newGrid;
      });
    },
    [updateGridState],
  );

  const handleReset = useCallback(() => {
    const emptyGrid = Array.from({ length: 5 }, () =>
      Array.from({ length: 7 }, () => null),
    );
    setModificationsMap((prevMap) => {
      const newMap = new Map(prevMap);
      newMap.set(level, emptyGrid);
      return newMap;
    });
    if (typeof window !== "undefined") {
      localStorage.removeItem(getStorageKey(level));
    }
  }, [level, getStorageKey]);

  return {
    gridState,
    handlePuzzmonPlace,
    handlePuzzmonRemove,
    handleReset,
  };
};
