type GameOverScreenProps = {
  score: number;
  targetScore: number;
  resetGame: () => void;
  submissionError?: string;
  won?: boolean;
  customMessage?: string;
};

export const GameOverScreen = ({
  score,
  targetScore,
  resetGame,
  submissionError,
  won,
  customMessage,
}: GameOverScreenProps) => {
  const isWon = won ?? score >= targetScore;

  return (
    <div className="text-center bg-white/80 backdrop-blur-sm rounded-lg p-6 shadow-lg">
      <div className="text-2xl font-bold mb-2 text-gray-800">Game Over!</div>
      <div className="text-lg mb-4 text-gray-700">Final Score: {score}</div>
      {isWon && !submissionError ? (
        <div>
          <div className="text-green-600 font-semibold mb-2">
            {customMessage || "Congratulations on completing the task!"}
          </div>
          <button
            onClick={resetGame}
            className="px-6 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-lg font-semibold text-lg shadow-lg"
          >
            Play Again
          </button>
        </div>
      ) : (
        <div>
          <div className="text-red-500 font-semibold mb-2">
            {submissionError ||
              customMessage ||
              `You need ${targetScore} points to complete this round.`}
          </div>
          <button
            onClick={resetGame}
            className="px-6 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-lg font-semibold text-lg shadow-lg"
          >
            Try Again
          </button>
        </div>
      )}
    </div>
  );
};
