import { cn } from "@hunt/styled-ui";
import { X } from "lucide-react";
import React from "react";

const MONARCH_SEARCH_FIELD_STYLING = `
  flex-1 text-white text-base w-80 max-monarch-medium:w-60
  items-center rounded-full px-4 py-1
  bg-monarch-input-bg border-2 border-monarch-input-border
  box-border shadow-[0_0_10px_rgba(0,179,255,0.4)]
  placeholder:text-monarch-input-placeholder placeholder:italic
  focus:outline-none focus-visible:outline-none
  focus-visible:border-monarch-light focus-visible:shadow-[0_0_12px_rgba(0,179,255,0.8)]
`;

type MonarchSearchFieldProps = React.InputHTMLAttributes<HTMLInputElement> & {
  onClear?: () => void;
};

export const MonarchSearchField = React.forwardRef<
  HTMLInputElement,
  MonarchSearchFieldProps
>(({ value, onClear, ...inputProps }, ref) => {
  return (
    <div className="relative">
      <input
        type="search"
        className={cn(
          MONARCH_SEARCH_FIELD_STYLING,
          "[&::-webkit-search-cancel-button]:hidden",
        )}
        {...inputProps}
        value={value}
        ref={ref}
      />
      {!!value && (
        <button
          type="button"
          tabIndex={-1}
          className="absolute right-3 top-1/2 -translate-y-1/2 text-monarch-border dark:text-monarch-dark-border"
          onClick={(e) => {
            const input = e.currentTarget
              .previousElementSibling as HTMLInputElement | null;
            if (input) {
              input.value = "";
              onClear?.();
            }
          }}
          aria-hidden="true"
        >
          <X width={22} height={22} />
        </button>
      )}
    </div>
  );
});
MonarchSearchField.displayName = "MonarchSearchField";
