import { useState, useMemo, useEffect } from "react";
import type { LightSource } from "./beamTypes";
import { colorNameToRgb, type ColorName } from "./beamUtils";
import { SANDBOX_LEVEL } from "./constants";

export type LightState = ColorName | null;

type UseLightSourcesParams = {
  initialLightSources?: {
    topLight: LightState;
    leftLight: LightState;
    rightLight: LightState;
    bottomLight: LightState;
  };
  onLightSourcesChange?: (lightSources: {
    topLight: LightState;
    leftLight: LightState;
    rightLight: LightState;
    bottomLight: LightState;
  }) => void;
};

export const useLightSources = (
  currentLevel: number,
  params?: UseLightSourcesParams,
) => {
  const { initialLightSources, onLightSourcesChange } = params ?? {};

  const initialTopLight =
    initialLightSources?.topLight ??
    (currentLevel === SANDBOX_LEVEL ? "white" : null);
  const initialLeftLight = initialLightSources?.leftLight ?? null;
  const initialRightLight = initialLightSources?.rightLight ?? null;
  const initialBottomLight = initialLightSources?.bottomLight ?? null;

  const [topLight, setTopLight] = useState<LightState>(initialTopLight);
  const [leftLight, setLeftLight] = useState<LightState>(initialLeftLight);
  const [rightLight, setRightLight] = useState<LightState>(initialRightLight);
  const [bottomLight, setBottomLight] =
    useState<LightState>(initialBottomLight);

  // Update state when initialLightSources changes (e.g., from localStorage)
  useEffect(() => {
    if (initialLightSources) {
      setTopLight(initialLightSources.topLight);
      setLeftLight(initialLightSources.leftLight);
      setRightLight(initialLightSources.rightLight);
      setBottomLight(initialLightSources.bottomLight);
    }
  }, [initialLightSources]);

  // Notify parent when light sources change
  useEffect(() => {
    if (onLightSourcesChange) {
      onLightSourcesChange({
        topLight,
        leftLight,
        rightLight,
        bottomLight,
      });
    }
  }, [topLight, leftLight, rightLight, bottomLight, onLightSourcesChange]);

  // Toggle function for light sources
  const toggleLight = (
    current: LightState,
    setter: (value: LightState) => void,
  ) => {
    if (current === null) {
      setter("white");
    } else if (current === "white") {
      setter("red");
    } else if (current === "red") {
      setter("green");
    } else if (current === "green") {
      setter("blue");
    } else if (current === "blue") {
      setter(null); // off
    }
  };

  // Calculate light sources - always include top light, plus optional left/right/bottom (only in sandbox level)
  const lightSources = useMemo(() => {
    const sources: LightSource[] = [];

    // Top light (row 0, col 3, direction down)
    if (currentLevel === SANDBOX_LEVEL) {
      // In sandbox level, use configurable top light
      if (topLight !== null) {
        sources.push({
          row: 0,
          col: 3,
          direction: "down",
          color: colorNameToRgb(topLight),
        });
      }
    } else {
      // In other levels, always use white top light
      sources.push({
        row: 0,
        col: 3,
        direction: "down",
        color: { r: 1, g: 1, b: 1 }, // white
      });
    }

    // Additional lights only in sandbox level (level 4)
    if (currentLevel === SANDBOX_LEVEL) {
      // Left light (col 0, row 2, direction right) - comes from left side
      if (leftLight !== null) {
        sources.push({
          row: 2,
          col: 0,
          direction: "right",
          color: colorNameToRgb(leftLight),
        });
      }

      // Right light (col 6, row 2, direction left) - comes from right side
      if (rightLight !== null) {
        sources.push({
          row: 2,
          col: 6,
          direction: "left",
          color: colorNameToRgb(rightLight),
        });
      }

      // Bottom light (row 4, col 3, direction up) - comes from bottom side
      if (bottomLight !== null) {
        sources.push({
          row: 4,
          col: 3,
          direction: "up",
          color: colorNameToRgb(bottomLight),
        });
      }
    }

    return sources;
  }, [currentLevel, topLight, leftLight, rightLight, bottomLight]);

  return {
    topLight,
    leftLight,
    rightLight,
    bottomLight,
    setTopLight,
    setLeftLight,
    setRightLight,
    setBottomLight,
    toggleLight,
    lightSources,
  };
};
