import { newClient } from "@hunt/public-client";
import {
  type ScoringLevelWithAchieved,
  type CriterionWithScore,
  METRIC_FUNCTIONS,
  countSatisfiedPreferences,
} from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import { useMemo, useState, useCallback, useEffect } from "react";
import apiUrl from "../../../../utils/apiUrl";
import { IS_STATIC_SITE } from "../../../../utils/staticSite";
import { markTaskSolved } from "../../../puzzleSolveLocalState";
import { BackToArchiveButton } from "../../components/MonarchButton";
import MonarchTaskWrapper from "../MonarchTaskWrapper";
import TaskSolvedMessage from "../TaskSolvedMessage";
import TaskSuccessAnimation from "../TaskSuccessAnimation";
import { type MonarchTaskProps } from "../monarch_tasks_defs";
import TaskFolderTabs from "./TaskFolderTabs";
import {
  getRoyalGrovesPuzzmon,
  BIOMES,
  PUZZMON_PREFERENCES,
  SCORING_CRITERIA,
} from "./data";
import { useGridState } from "./useGridState";

const SCORE_GOAL = 20;

const FolderTab = ({
  label,
  isActive,
  onClick,
}: {
  label: string;
  isActive: boolean;
  onClick: () => void;
}) => {
  return (
    <div className="relative">
      <button
        className={cn(
          "relative flex items-center z-10 w-fit h-10 font-title text-[16px] px-4 border-2 rounded-t-2xl cursor-pointer bg-[#D5B893] border-[#FFE100] border-b-[#D5B893] select-none",
          isActive
            ? "text-secondary"
            : "h-[37px] pt-[3px] text-black bg-[#947d60] border-transparent hover:brightness-125 focus-visible:brightness-125",
        )}
        onClick={onClick}
      >
        {label.toUpperCase()}
      </button>
    </div>
  );
};

function RoyalGrovesTask({
  returnToArchive,
  teamState,
  taskSlug,
}: MonarchTaskProps) {
  const [activeTab, setActiveTab] = useState<
    "grid" | "preferences" | "scoring"
  >("grid");

  // Grid state persists across tab switches
  const { gridState, handleTilePlace, handleTileRemove, handleReset } =
    useGridState();

  // Submission state
  const [showWinAnimation, setShowWinAnimation] = useState(false);
  const [solved, setSolved] = useState(false);

  const hasTeamSubmitted = !!teamState?.puzzles[taskSlug ?? ""]?.solved;

  const tabs = [
    { id: "grid" as const, label: "Grid" },
    { id: "scoring" as const, label: "Scoring" },
    { id: "preferences" as const, label: "Preferences" },
  ];

  const { criteriaWithScores, totalScore } = useMemo(() => {
    const preferencesSatisfied = countSatisfiedPreferences(
      gridState,
      PUZZMON_PREFERENCES,
    );

    let totalScore = 0;

    const criteriaWithScores = SCORING_CRITERIA.map<CriterionWithScore>(
      (criterion) => {
        const metric = METRIC_FUNCTIONS[criterion.id](
          gridState,
          preferencesSatisfied,
        );
        let score = 0;

        const result = {
          ...criterion,
          metric,
          levels: criterion.levels.map<ScoringLevelWithAchieved>((level) => {
            const achieved = metric >= level.threshold;
            if (achieved) {
              score = Math.max(score, level.points);
            }
            return {
              ...level,
              achieved,
            };
          }),
        };
        totalScore += score;
        return result;
      },
    );

    return {
      criteriaWithScores,
      totalScore,
    };
  }, [gridState]);

  // Submission callback
  const submitAnswer = useCallback(async () => {
    if (solved || hasTeamSubmitted) return;

    if (IS_STATIC_SITE) {
      const slug = taskSlug ?? "monarch_royal_groves_task";
      markTaskSolved(slug);
      setSolved(true);
      setShowWinAnimation(true);
      return;
    }

    try {
      const apiClient = newClient(apiUrl(), undefined);
      const response = await apiClient.submitGuess({
        body: {
          guess: "",
        },
        params: { slug: "monarch_royal_groves_task" },
      });

      if (response.status === 200) {
        const isSolved = response.body.guesses.some(
          (guess) => guess.status === "correct",
        );
        if (isSolved) {
          setSolved(true);
          setShowWinAnimation(true);
        }
      }
    } catch (error: unknown) {
      console.error("Failed to submit answer:", error);
    }
  }, [solved, hasTeamSubmitted, taskSlug]);

  // Auto-submit when score meets goal
  useEffect(() => {
    if (totalScore >= SCORE_GOAL) {
      void submitAnswer();
    }
  }, [totalScore, submitAnswer]);

  return (
    <MonarchTaskWrapper returnToArchive={returnToArchive}>
      <div className="h-full w-full flex flex-col">
        <BackToArchiveButton
          onClick={returnToArchive}
          className="absolute top-4 left-6 z-50"
        />

        {/* Solved message */}
        <TaskSolvedMessage
          teamState={teamState}
          taskSlug={taskSlug}
          className="mx-auto mb-4"
        />

        {/* Tabs positioned above folder content */}
        <div
          className={cn(
            "flex space-x-2 justify-center translate-y-px",
            !hasTeamSubmitted && "mt-12",
          )}
        >
          {tabs.map((tab) => (
            <FolderTab
              key={tab.id}
              label={tab.label}
              isActive={activeTab === tab.id}
              onClick={() => {
                setActiveTab(tab.id);
              }}
            />
          ))}
        </div>

        {/* Submission status feedback */}
        {showWinAnimation && (
          <TaskSuccessAnimation
            onComplete={() => {
              setShowWinAnimation(false);
            }}
          />
        )}

        {/* Main content area */}
        <div className="px-4 pb-4 flex-1 min-h-0">
          <TaskFolderTabs
            activeTab={activeTab}
            gridState={gridState}
            score={totalScore}
            goal={SCORE_GOAL}
            tiles={[
              {
                title: "Puzzmon",
                tiles: getRoyalGrovesPuzzmon(),
              },
              {
                title: "Landscapes",
                tiles: BIOMES,
              },
            ]}
            scoringCriteria={criteriaWithScores}
            preferences={PUZZMON_PREFERENCES}
            handleTilePlace={handleTilePlace}
            handleTileRemove={handleTileRemove}
            handleReset={handleReset}
          />
        </div>
      </div>
    </MonarchTaskWrapper>
  );
}

export default RoyalGrovesTask;
