import { type Tile } from "@hunt/puzzle-components";
import { useState, useCallback, useEffect } from "react";

const STORAGE_KEY = "royal_groves_grid_state";

export const useGridState = () => {
  // Initialize 5x5 grid with null values, loading from session storage if available
  const [gridState, setGridState] = useState<(Tile | null)[][]>(() => {
    try {
      const saved = sessionStorage.getItem(STORAGE_KEY);
      if (saved) {
        return JSON.parse(saved) as (Tile | null)[][];
      }
    } catch (error) {
      console.warn("Failed to load grid state from session storage:", error);
    }
    return Array.from({ length: 5 }, () =>
      Array.from({ length: 5 }, () => null),
    );
  });

  // Save to session storage whenever grid state changes
  useEffect(() => {
    try {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(gridState));
    } catch (error) {
      console.warn("Failed to save grid state to session storage:", error);
    }
  }, [gridState]);

  const handleTilePlace = useCallback(
    (
      tile: Tile & {
        fromGrid?: boolean;
        gridRow?: number;
        gridCol?: number;
      },
      row: number,
      col: number,
    ) => {
      setGridState((prev) => {
        const newGrid = prev.map((r) => [...r]);

        // If tile is coming from grid, clear its old position
        if (
          tile.fromGrid &&
          tile.gridRow !== undefined &&
          tile.gridCol !== undefined
        ) {
          newGrid[tile.gridRow][tile.gridCol] = null;
        }
        // If tile is coming from tile list, don't remove existing instances - allow duplicates

        // Place tile in new position
        newGrid[row][col] = tile;
        return newGrid;
      });
    },
    [],
  );

  const handleTileRemove = useCallback((row: number, col: number) => {
    setGridState((prev) => {
      const newGrid = [...prev];
      newGrid[row] = [...newGrid[row]];
      newGrid[row][col] = null;
      return newGrid;
    });
  }, []);

  const handleReset = useCallback(() => {
    const emptyGrid = Array.from({ length: 5 }, () =>
      Array.from({ length: 5 }, () => null),
    );
    setGridState(emptyGrid);
    sessionStorage.removeItem(STORAGE_KEY);
  }, []);

  return {
    gridState,
    handleTilePlace,
    handleTileRemove,
    handleReset,
  };
};
