import { newClient } from "@hunt/public-client";
import { cn } from "@hunt/styled-ui";
import { motion } from "motion/react";
import React, { useCallback, useEffect, useRef, useState } from "react";
import apiUrl from "../../../../utils/apiUrl";
import { IS_STATIC_SITE } from "../../../../utils/staticSite";
import { markTaskSolved } from "../../../puzzleSolveLocalState";
import { BackToArchiveButton } from "../../components/MonarchButton";
import { GameOverScreen } from "../GameOverScreen";
import MonarchTaskWrapper from "../MonarchTaskWrapper";
import TaskSolvedMessage from "../TaskSolvedMessage";
import TaskSuccessAnimation from "../TaskSuccessAnimation";
import { type MonarchTaskProps } from "../monarch_tasks_defs";
import { BubbleCoveTaskBackground } from "./BubbleCoveTaskBackground";
import { InterRoundScreen } from "./InterRoundScreen";
import { StartScreen } from "./StartScreen";
import {
  ROUND_1_TARGET_SCORE,
  ROUND_2_TARGET_SCORE,
  STORAGE_KEY,
  WORD_COUNT,
} from "./constants";
import { type GameState } from "./types";
import { useFishManager } from "./useFishManager";
import { useWordManager } from "./useWordManager";
import { stateIsPlaying } from "./utils";

const SUBMISSION_ERROR =
  "An unexpected error occurred submitting the task. Please try again later.";

type StorageData = {
  score: number;
  hasSubmitted: boolean;
};

const getStoredData = (): StorageData => {
  if (typeof window === "undefined") {
    return { score: 0, hasSubmitted: false };
  }
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (!stored) {
      return { score: 0, hasSubmitted: false };
    }
    const parsed = JSON.parse(stored) as StorageData;
    return {
      score: parsed.score ?? 0,
      hasSubmitted: parsed.hasSubmitted ?? false,
    };
  } catch {
    return { score: 0, hasSubmitted: false };
  }
};

function BubbleCoveTask({
  returnToArchive,
  puzzmonData,
  backgroundImageSrc: _backgroundImageSrc,
  teamState,
  taskSlug,
}: MonarchTaskProps) {
  const [gameState, setGameState] = useState<GameState>("start_screen");
  const [score, setScore] = useState(() => getStoredData().score);
  const [currentInput, setCurrentInput] = useState("");
  const [showWinAnimation, setShowWinAnimation] = useState(false);
  const [submissionError, setSubmissionError] = useState<string | undefined>();
  const inputRef = useRef<HTMLInputElement>(null);
  const gameAreaRef = useRef<HTMLDivElement>(null);

  const hasTeamSubmitted = !!teamState?.puzzles[taskSlug ?? ""]?.solved;

  const {
    advanceRound,
    nextWordWrapper,
    reset: resetWords,
    roundNumber,
  } = useWordManager(WORD_COUNT);

  // Use roundNumber from useWordManager (1-indexed: 1 = round 1, 2 = round 2)
  // TypeScript workaround: assert type since we know it's a number from the return type
  const currentRoundNumber = roundNumber as unknown as number;

  const { fish, clearFish, markFishCompleted, roundFinished } = useFishManager({
    gameState,
    puzzmonData,
    getNextWord: nextWordWrapper,
    roundNumber: currentRoundNumber,
  });

  // Handle keyboard input
  const onChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (gameState !== "round_1" && gameState !== "round_2") return;

      setCurrentInput(e.target.value);
      const matchingFish = fish.find(
        (f) =>
          !f.completed &&
          f.answer.toLowerCase() === e.target.value.toLowerCase().trim(),
      );

      if (matchingFish) {
        // Mark fish as completed (but keep it swimming)
        markFishCompleted(matchingFish.id);
        setScore((prev) => prev + 1);
        setCurrentInput("");
      }
    },
    [gameState, fish, markFishCompleted],
  );

  const onKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      setCurrentInput("");
    }
  }, []);

  const startRound = useCallback(() => {
    clearFish();
    setScore(0);
    setCurrentInput("");
    setTimeout(() => {
      inputRef.current?.focus();
    }, 100);
  }, [clearFish]);

  // Start game
  const startGame = useCallback(() => {
    setGameState("round_1");
    startRound();
  }, [startRound]);

  const startRound2 = useCallback(() => {
    setGameState("round_2");
    startRound();
  }, [startRound]);

  const clearRoundState = useCallback(() => {
    clearFish();
    resetWords();
    setCurrentInput("");
  }, [clearFish, resetWords]);

  // Reset game
  const resetGame = useCallback(() => {
    setGameState("start_screen");
    setSubmissionError(undefined);
    clearRoundState();
  }, [clearRoundState]);

  const submitTask = useCallback(async () => {
    // If already submitted, just show the win animation without hitting the server
    if (hasTeamSubmitted) {
      setShowWinAnimation(true);
      setSubmissionError(undefined);
      return;
    }

    if (IS_STATIC_SITE) {
      const slug = taskSlug ?? "monarch_bubble_cove_task";
      markTaskSolved(slug);
      setShowWinAnimation(true);
      setSubmissionError(undefined);
      return;
    }

    setSubmissionError("Submitting...");

    try {
      const apiClient = newClient(apiUrl(), undefined);
      const response = await apiClient.submitGuess({
        body: {
          guess: "",
        },
        params: { slug: taskSlug ?? "monarch_bubble_cove_task" },
      });

      if (response.status === 200) {
        const solved = response.body.guesses.some(
          (guess) => guess.status === "correct",
        );
        if (solved) {
          setShowWinAnimation(true);
          setSubmissionError(undefined);
        } else {
          setSubmissionError(SUBMISSION_ERROR);
        }
      } else {
        setSubmissionError(SUBMISSION_ERROR);
      }
    } catch (error: unknown) {
      console.error("Failed to submit score:", error);
      setSubmissionError(SUBMISSION_ERROR);
    }
  }, [taskSlug, hasTeamSubmitted]);

  useEffect(() => {
    const targetScore = getTargetScore(currentRoundNumber);
    if (gameState === "round_1" && roundFinished) {
      clearRoundState();
      if (score >= targetScore) {
        setGameState("inter_round_screen");
        advanceRound();
      } else {
        setGameState("game_over");
      }
    } else if (gameState === "round_2" && roundFinished) {
      setGameState("game_over");
      clearRoundState();
      if (score >= targetScore) {
        void submitTask();
      }
    }
  }, [
    advanceRound,
    clearRoundState,
    gameState,
    resetGame,
    roundFinished,
    currentRoundNumber,
    score,
    submitTask,
  ]);

  // Handle clicking on game area to focus input
  const handleGameAreaClick = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      // Only focus if game is playing and click wasn't on an interactive element
      if (
        stateIsPlaying(gameState) &&
        !(e.target instanceof HTMLButtonElement) &&
        !(e.target instanceof HTMLInputElement)
      ) {
        inputRef.current?.focus();
      }
    },
    [gameState],
  );

  return (
    <MonarchTaskWrapper returnToArchive={returnToArchive}>
      <div className="relative w-full h-full flex flex-col justify-end items-center overflow-x-auto overflow-y-hidden">
        <BackToArchiveButton
          onClick={returnToArchive}
          className="absolute top-4 left-6 z-50"
        />

        <div className="flex flex-col items-center gap-2 lg:gap-4 mt-auto w-full h-full">
          {/* Solved message */}
          <TaskSolvedMessage teamState={teamState} taskSlug={taskSlug} />

          {/* Game UI */}
          <div
            className={cn(
              "relative mb-4 max-w-full max-h-full min-h-0 aspect-[3/2]",
              !hasTeamSubmitted && "mt-12 md:mt-20",
            )}
          >
            {/* Game area - background image with all overlays */}
            <div
              ref={gameAreaRef}
              className="relative w-full h-full overflow-hidden cursor-text"
              onClick={handleGameAreaClick}
              onKeyDown={undefined}
              role="button"
              tabIndex={stateIsPlaying(gameState) ? 0 : -1}
              aria-label="Click to focus input for typing"
            >
              <BubbleCoveTaskBackground />

              {/* Score and timer overlay - top, positioned on the image */}
              <div className="absolute top-4 left-4 right-4 text-xl flex justify-between items-center z-10 pointer-events-none">
                <div className="font-bold text-white transform-gpu drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">
                  Score: {score}
                </div>
                <div className="text-white transform-gpu drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">
                  Target: {getTargetScore(currentRoundNumber)} points
                </div>
              </div>

              {/* Fish swimming across (with words) */}
              <div className="absolute inset-0 focus-visible:outline-none">
                {fish.map((f) => {
                  return (
                    <motion.div
                      key={f.id}
                      className={cn(
                        "absolute overflow-visible",
                        f.behavior === "arc" && "z-[35]",
                        f.behavior === "pop_out" && "z-[25]",
                      )}
                      style={{
                        left: `${f.x}%`,
                        top: `${f.y}%`,
                        transform: "translate(-50%, -50%)",
                        width: `${f.width}%`,
                      }}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      exit={{ opacity: 0 }}
                    >
                      <div className="flex flex-col items-center gap-2">
                        {/* Puzzmon image */}
                        <img
                          src={f.puzzmon.imageSrc}
                          alt={f.puzzmon.name}
                          className="w-full h-full object-contain select-none"
                          style={{
                            transform:
                              [
                                // For pop_out fish when moving back: flip based on direction
                                // Left side (direction 1): flip when moving back
                                // Right side (direction -1): unflip when moving back
                                f.behavior === "pop_out" && f.isMovingBack
                                  ? (f.direction ?? 1) === 1
                                    ? "scaleX(-1)"
                                    : ""
                                  : (f.direction ?? 1) === -1
                                    ? "scaleX(-1)"
                                    : "",
                                f.rotation ? `rotate(${f.rotation}deg)` : "",
                              ]
                                .filter(Boolean)
                                .join(" ") || "none",
                          }}
                        />
                        {/* Word label */}
                        <div
                          className={cn(
                            "px-3 py-1 rounded-lg text-lg font-bold text-white shadow-lg whitespace-nowrap w-max",
                            f.completed ? "bg-green-500" : "bg-blue-600",
                          )}
                        >
                          {f.text}
                        </div>
                      </div>
                    </motion.div>
                  );
                })}
              </div>

              {/* Input area overlay - bottom */}
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50 pointer-events-auto w-full max-w-2xl px-4">
                {gameState === "start_screen" && (
                  <StartScreen startGame={startGame} />
                )}

                {gameState === "inter_round_screen" && (
                  <InterRoundScreen startGame={startRound2} />
                )}

                {gameState === "game_over" && (
                  <GameOverScreen
                    score={score}
                    targetScore={getTargetScore(currentRoundNumber)}
                    resetGame={resetGame}
                    submissionError={submissionError}
                  />
                )}
              </div>

              <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-10 pointer-events-auto w-full max-w-2xl px-4">
                {stateIsPlaying(gameState) && (
                  <div className="relative w-full">
                    {/* Input positioned where visible text is - allows text selection */}
                    <input
                      ref={inputRef}
                      type="text"
                      value={currentInput}
                      onChange={onChange}
                      onKeyDown={onKeyDown}
                      className="w-full text-center text-3xl font-mono text-white transform-gpu drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] bg-transparent border-none outline-none selection:bg-blue-500 selection:text-white focus-visible:outline-none focus:outline-none"
                      autoComplete="off"
                      autoCorrect="off"
                      autoCapitalize="off"
                      spellCheck="false"
                      style={{
                        textShadow: "0 2px 4px rgba(0,0,0,0.8)",
                        caretColor: "transparent",
                      }}
                    />
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Win animation */}
        {showWinAnimation && (
          <TaskSuccessAnimation
            onComplete={() => {
              setShowWinAnimation(false);
            }}
          />
        )}
      </div>
    </MonarchTaskWrapper>
  );
}

function getTargetScore(roundNumber: number): number {
  if (roundNumber === 1) {
    return ROUND_1_TARGET_SCORE;
  } else if (roundNumber === 2) {
    return ROUND_2_TARGET_SCORE;
  } else {
    throw new Error("invalid round number");
  }
}

export default BubbleCoveTask;
