import { type ParsedQs } from "qs";

export const MONARCH_QUERY_KEYS = {
  IS_OPEN: "showMonarch",
  SEARCH: "search",
  ZONE: "zone",
  PUZZMON_SLUG: "puzzmonSlug",
  PAGE: "page",
  TASK: "task",
};

export type MonarchQueryParams = {
  isOpen: boolean;
  search?: string;
  puzzmonSlug?: string;
  page?: string;
};

type QueryValue = undefined | null | string | ParsedQs | (string | ParsedQs)[];

export function requireString(queryValue: QueryValue) {
  if (!queryValue) {
    return undefined;
  }
  if (typeof queryValue === "string") {
    return queryValue;
  }
  console.error(
    "One of the query params in the URL path is not a valid string.",
  );
  return "";
}

function requireBoolean(queryValue: QueryValue) {
  return requireString(queryValue) === "true";
}

export function getQueryParam(queryParams: ParsedQs | undefined, key: string) {
  if (queryParams === undefined) {
    return new URLSearchParams(window.location.search).get(key);
  }

  return queryParams[key];
}

function useMonarchQueryParams(queryParams: ParsedQs | undefined) {
  const isOpen: boolean | undefined = requireBoolean(
    getQueryParam(queryParams, MONARCH_QUERY_KEYS.IS_OPEN),
  );
  const search: string | undefined = requireString(
    getQueryParam(queryParams, MONARCH_QUERY_KEYS.SEARCH),
  );
  const zone: string | undefined = requireString(
    getQueryParam(queryParams, MONARCH_QUERY_KEYS.ZONE),
  );
  const puzzmonSlug: string | undefined = requireString(
    getQueryParam(queryParams, MONARCH_QUERY_KEYS.PUZZMON_SLUG),
  );
  const page: string | undefined = requireString(
    getQueryParam(queryParams, MONARCH_QUERY_KEYS.PAGE),
  );
  const task: string | undefined = requireString(
    getQueryParam(queryParams, MONARCH_QUERY_KEYS.TASK),
  );

  return {
    isOpen,
    search,
    zone,
    puzzmonSlug,
    page,
    task,
  };
}

export default useMonarchQueryParams;
