import { useDraggable } from "@dnd-kit/core";
import { ConditionalTooltip } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import React from "react";
import { type GridPuzzmon } from "./types";

const TILE_STYLE = "w-16 h-16 lg:w-24 lg:h-24";

type DraggablePuzzmonProps = {
  puzzmon: GridPuzzmon;
};

const DraggablePuzzmon: React.FC<DraggablePuzzmonProps> = ({ puzzmon }) => {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: `puzzmon-list-${puzzmon.id}`,
    data: puzzmon,
  });

  return (
    <ConditionalTooltip
      tooltip={
        <div className="text-center">
          Input: {puzzmon.input}
          <br />
          Output: {puzzmon.output}
          <br />
          {puzzmon.otherText && (
            <span className="text-sm italic">{puzzmon.otherText}</span>
          )}
        </div>
      }
      className="z-[101] bg-white text-black"
      disableHoverableContent={true}
    >
      <div
        ref={setNodeRef}
        {...attributes}
        {...listeners}
        className={cn(
          TILE_STYLE,
          "cursor-grab select-none bg-black border-2 border-white p-2 shadow-sm transition-all",
          isDragging && "opacity-50",
        )}
        style={isDragging ? { transform: "none" } : undefined}
      >
        <img
          src={puzzmon.image}
          alt={puzzmon.name}
          className="w-full h-full object-contain"
        />
      </div>
    </ConditionalTooltip>
  );
};

type PuzzmonListProps = {
  puzzmon: GridPuzzmon[];
};

export const PuzzmonList: React.FC<PuzzmonListProps> = ({ puzzmon }) => {
  return (
    <div className="flex flex-col gap-3 overflow-y-auto pr-6 pb-4">
      {puzzmon.map((p) => (
        <DraggablePuzzmon key={p.id} puzzmon={p} />
      ))}
    </div>
  );
};
