import {
  MONSTER_DATA,
  MONSTER_ZONES,
  type MonarchData,
} from "@hunt/hunt-data/monarch";

/**
 * Returns a copy of monarchData where each zone's solvedPuzzmon list is replaced
 * with all Puzzmon. Once we clientize the frontend, we can remove this function
 * and just call computeMonarchData directly in MonarchContent. Currently if we do that,
 * all of the dontLeakThis-protected data from the main hunt-data package will complain
 * and I don't want to conflict with anyone else by removing them.
 */
export function expandMonarchDataToShowAll(
  monarchData: MonarchData | undefined,
): MonarchData | undefined {
  if (!monarchData) return monarchData;

  const expanded: MonarchData = {} as MonarchData;

  for (const zoneKey in MONSTER_ZONES) {
    const zone = MONSTER_ZONES[zoneKey as keyof typeof MONSTER_ZONES];

    const fullList = Object.values(
      MONSTER_DATA[zone as keyof typeof MONSTER_DATA],
    );

    expanded[zone] = {
      ...monarchData[zone],
      count: fullList.length,
      solvedPuzzmon: fullList,
    };
  }

  return expanded;
}
