import { cn } from "@hunt/styled-ui";
import React from "react";
import undiscoveredPuzzmon from "../../assets/undiscovered_puzzmon.svg";

const MONARCH_CARD_STYLING = `
  relative
  flex
  flex-col
  items-center
  text-center
  py-1
  gap-2
  w-32
  h-[132px]
  max-w-36
  max-h-52
  rounded-tr-[50px]
  rounded-bl-[50px]
  bg-gradient-to-b from-monarch-card-top to-monarch-card-bottom
  transform-gpu drop-shadow-[0_0_6px_#2186F8]
  cursor-pointer
  transition-all
  shadow-md
  focus-visible:outline-none
  select-none
`;

type PuzzmonImageProps = {
  imageSrc: string | undefined;
  top?: string | number;
  left?: string | number;
  width?: string | number;
  height?: string | number;
};

const PuzzmonImage = ({
  name,
  puzzmonImage,
}: {
  name?: string;
  puzzmonImage?: PuzzmonImageProps;
}) => {
  return (
    <>
      {name && puzzmonImage ? (
        <img
          src={puzzmonImage.imageSrc}
          alt={name}
          className="max-w-none transform-gpu drop-shadow-[0_4px_4px_#36316C]"
          style={{
            width: puzzmonImage.width ?? "auto",
            height: puzzmonImage.height ?? 96,
          }}
        />
      ) : (
        <div className="flex items-center justify-center w-full h-full">
          <img
            src={undiscoveredPuzzmon}
            alt="Undiscovered"
            className="w-12 h-12 max-w-12 max-h-12 fill-neutral-900"
          />
        </div>
      )}
    </>
  );
};

const PuzzmonName = ({
  name,
  displayNameSplit,
}: {
  name: string;
  displayNameSplit?: string[];
}) => {
  return (
    <b
      className={`absolute min-h-6 bottom-2 -left-1 bg-monarch-accent rounded-[35px]
        flex items-center justify-center font-body leading-5
        text-monarch-dark text-base px-1.5 w-full break-words`}
    >
      {displayNameSplit
        ? displayNameSplit.map((namePart, i) => {
            return (
              <React.Fragment key={namePart}>
                {i > 0 && <>&shy;</>}
                {namePart}
              </React.Fragment>
            );
          })
        : name}
    </b>
  );
};

type MonarchCardProps = {
  isDiscovered?: boolean;
  name?: string;
  displayNameSplit?: string[];
  isSelected?: boolean;
  updateSelectedMonster?: (newMonsterName: string) => void;
  puzzmonImage?: PuzzmonImageProps;
};

function MonarchCard({
  name,
  displayNameSplit,
  isSelected,
  updateSelectedMonster,
  puzzmonImage,
}: MonarchCardProps) {
  return name && updateSelectedMonster ? (
    <button
      className={cn(
        MONARCH_CARD_STYLING,
        name && "pb-10",
        isSelected && "bg-neutral-400 hover:bg-neutral-400",
        "active:shadow-none active:translate-x-px active:translate-y-px",
        !!name &&
          `hover:scale-105 hover:brightness-105 hover:drop-shadow-[0_0_12px_var(--monarch-accent)]
          focus-visible:scale-105 focus-visible:brightness-105 focus-visible:drop-shadow-[0_0_12px_var(--monarch-accent)]`,
      )}
      onClick={() => {
        updateSelectedMonster(name);
      }}
      aria-label={name}
    >
      <PuzzmonImage name={name} puzzmonImage={puzzmonImage} />
      <PuzzmonName name={name} displayNameSplit={displayNameSplit} />
    </button>
  ) : (
    <div
      className={cn(MONARCH_CARD_STYLING, "disabled cursor-not-allowed")}
      aria-label="Unknown Puzzmon"
    >
      <PuzzmonImage />
    </div>
  );
}

export default MonarchCard;
