import {
  COPY_NO_EXTRA_LINES_CLASS,
  COPY_ONLY_CLASS,
  NO_COPY_CLASS,
} from "@hunt/copy-to-clipboard";
import { MONSTER_ZONES, type MonsterDetails } from "@hunt/hunt-data/monarch";
import {
  GlitchEffect,
  GlitchStyles,
  postprocessMonarchAltText,
  useGlobalVolume,
} from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import {
  CircleArrowRight,
  CircleArrowLeft,
  Volume2,
  Apple,
} from "lucide-react";
import React, { useEffect } from "react";
import puzzmonCard from "../../../assets/puzzmon_card.svg";
import {
  BackToArchiveButton,
  CopyMonarchEntryButton,
} from "../../../components/MonarchButton";
import { slugify } from "../../../lib/slug";
import { deleteQueryParam, updateQueryParam } from "../../../lib/url";
import { MONARCH_QUERY_KEYS } from "../../../useMonarchQueryParams";
import { parseDescription } from "./parse_description";

const ARROW_WRAPPER_CLASSNAME = "h-full flex flex-col justify-center mx-1";
const ARROW_CLASSNAME = `text-monarch-border dark:text-monarch-dark-border transform-gpu drop-shadow-[0_0_2px_rgba(46,167,253,0.66)]
  max-md:w-8 max-lg:w-11 max-xl:w-12 w-[52px] max-md:h-8 max-lg:h-11 max-xl:h-12 h-[52px]
  hover:drop-shadow-[0_0_2px_rgba(46,167,253)] focus-visible:drop-shadow-[0_0_2px_rgba(46,167,253)]
  hover:scale-105 focus-visible:scale-105 hover:brightness-105 focus-visible:brightness-105`;

function PuzzmonNameAndSubtitle({
  name,
  displayNameSplit,
  subtitle,
  pronunciationSrc,
}: {
  name: string;
  displayNameSplit?: string[];
  subtitle?: string;
  pronunciationSrc?: string;
}) {
  const globalVolume = useGlobalVolume();

  return (
    <>
      <div
        className={cn(
          "flex flex-col justify-start items-center mb-2 lg:min-h-[108px] xl:min-h-[124px]",
          NO_COPY_CLASS,
        )}
      >
        <div className="relative sm:max-w-[58%]">
          <h1 className="text-center p-0 font-title max-sm:mt-1 max-md:text-3xl max-lg:text-4xl max-xl:text-5xl text-6xl text-white transform-gpu drop-shadow-[0_0_8px_rgba(255,255,255,0.33)]">
            {displayNameSplit
              ? displayNameSplit.map((namePart, i) => {
                  return (
                    <React.Fragment key={namePart}>
                      {i > 0 && <>&shy;</>}
                      {namePart.toUpperCase()}
                    </React.Fragment>
                  );
                })
              : name.toUpperCase()}
          </h1>
          {pronunciationSrc && (
            <Volume2
              className="absolute left-full translate-x-3 max-sm:translate-x-2 top-1/2 -translate-y-1/2 max-sm:top-2.5 max-sm:translate-y-0 text-monarch-accent cursor-pointer hover:scale-110 w-10 h-10 max-md:w-6 max-md:h-6"
              onClick={() => {
                const audio = new Audio(pronunciationSrc);
                audio.volume = globalVolume;
                void audio.play();
              }}
            />
          )}
        </div>
        {subtitle && (
          <p
            role="doc-subtitle"
            className="italic text-monarch-accent max-lg:text-lg max-xl:text-xl text-2xl max-md:-mt-5 max-lg:-mt-4 max-xl:-mt-3 -mt-2 mb-2"
          >
            {subtitle}
          </p>
        )}
      </div>
      <div className={COPY_ONLY_CLASS}>
        <div className="text-lg font-bold">{name.toUpperCase()}</div>
        {subtitle && <div className="italic">{subtitle}</div>}
      </div>
    </>
  );
}

function PuzzmonImage({
  imageSrc,
  imageSrcDark,
  name,
  altText,
  imageSubtext,
  isGlitched,
  zone,
  isDarkMode,
}: {
  imageSrc?: string;
  imageSrcDark?: string;
  name: string;
  altText: string;
  imageSubtext?: string;
  isGlitched?: boolean;
  zone: MONSTER_ZONES;
  isDarkMode: boolean;
}) {
  const resolvedImage =
    zone === MONSTER_ZONES.THE_BRIGHTS && isDarkMode && imageSrcDark
      ? imageSrcDark
      : imageSrc;
  const finalAltText = postprocessMonarchAltText(altText);

  return (
    <>
      <div className={cn("relative w-full select-none", NO_COPY_CLASS)}>
        {(() => {
          const imageContent = (
            <>
              <a
                href={resolvedImage}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={`Open ${name} in new tab`}
              >
                <img
                  src={puzzmonCard}
                  alt={finalAltText}
                  className="w-full h-full transform-gpu drop-shadow-[0_0_8px_#2186F8]"
                />
              </a>
              {resolvedImage && (
                <img
                  src={resolvedImage}
                  alt=""
                  className="w-full h-full object-contain absolute top-0 left-0 [filter:drop-shadow(4px_4px_4px_#36316C)] pointer-events-none"
                  aria-hidden="true"
                />
              )}
            </>
          );

          return isGlitched ? (
            <GlitchEffect>{imageContent}</GlitchEffect>
          ) : (
            imageContent
          );
        })()}
        {imageSubtext && (
          <div className="font-bold absolute bottom-2 left-1/2 -translate-x-1/2 text-center text-sm text-white transform-gpu drop-shadow-[0_0_4px_rgba(0,0,0,0.75)] w-full px-2 z-10">
            {imageSubtext}
          </div>
        )}
      </div>
      <table className={cn(COPY_ONLY_CLASS, COPY_NO_EXTRA_LINES_CLASS)}>
        <tbody>
          <tr>
            {imageSubtext && (
              <td>
                <b>{imageSubtext}</b>
              </td>
            )}
            <td>{resolvedImage && <img src={resolvedImage} alt={name} />}</td>
          </tr>
        </tbody>
      </table>
    </>
  );
}

function PuzzmonSection({
  title,
  children,
  className,
  isGlitched,
}: {
  title: string;
  children: React.ReactNode;
  className?: string;
  isGlitched?: boolean;
}) {
  return (
    <div className={cn("flex flex-col gap-2", className)}>
      <h2 className="font-body font-bold max-lg:text-base max-xl:text-lg text-2xl p-0 m-0">
        {title}
      </h2>
      <div className="max-lg:text-sm max-xl:text-base text-lg">
        {isGlitched ? <GlitchEffect>{children}</GlitchEffect> : children}
      </div>
    </div>
  );
}

function DescriptionContent({
  sections,
}: {
  sections: {
    title: string;
    content?: React.ReactNode;
    // We include some special handling for copy-to-clipboard so that the data is formatted nicely.
    // For any content that is a list of strings or items, we will show each item in its own row.
    copyableContent?: React.ReactNode[];
    isGlitched?: boolean;
  }[];
}) {
  return (
    <>
      {sections.map((section) => {
        return section.content ? (
          <PuzzmonSection
            key={section.title}
            title={section.title}
            className={NO_COPY_CLASS}
            isGlitched={section.isGlitched}
          >
            {section.content}
          </PuzzmonSection>
        ) : null;
      })}
      <table className={cn(COPY_ONLY_CLASS, COPY_NO_EXTRA_LINES_CLASS)}>
        <tbody>
          {sections.map((section) => {
            if (!section.copyableContent) {
              return section.content ? (
                <tr key={section.title}>
                  <td className="font-bold">{section.title}</td>
                  <td>{section.content}</td>
                </tr>
              ) : null;
            }

            // If there are multiple lines in the section, we want to create a new row for each line.
            return section.copyableContent.map((sectionItem, index) => (
              <tr key={`${section.title}-${index}`}>
                <td className="font-bold">
                  {index === 0 ? section.title : ""}
                </td>
                <td>{sectionItem}</td>
              </tr>
            ));
          })}
        </tbody>
      </table>
    </>
  );
}

const getPuzzificationStages = (puzzificationLine: string[]) => {
  return puzzificationLine.map(
    (stage, index) => `Stage ${index + 1}: ${stage}`,
  );
};

const insertPuzzmonName = (text: string | undefined, name: string) => {
  if (!text) return text;
  return text.replace(/\{\{name\}\}/g, name);
};

const NextPuzzmonButton = ({
  nextPuzzmon,
  zone,
  setSelectedMonsterName,
}: {
  nextPuzzmon?: string | null;
  zone: string;
  setSelectedMonsterName: React.Dispatch<
    React.SetStateAction<string | undefined>
  >;
}) => {
  return (
    <div className={cn(!nextPuzzmon && "invisible")}>
      <button
        aria-label={`Next Puzzmon in ${zone}`}
        disabled={!nextPuzzmon}
        onClick={
          nextPuzzmon
            ? () => {
                updateQueryParam(
                  MONARCH_QUERY_KEYS.PUZZMON_SLUG,
                  slugify(nextPuzzmon),
                );
                setSelectedMonsterName(nextPuzzmon);
              }
            : undefined
        }
      >
        <CircleArrowRight className={ARROW_CLASSNAME} />
      </button>
    </div>
  );
};

const PreviousPuzzmonButton = ({
  previousPuzzmon,
  zone,
  setSelectedMonsterName,
}: {
  previousPuzzmon?: string | null;
  zone: string;
  setSelectedMonsterName: React.Dispatch<
    React.SetStateAction<string | undefined>
  >;
}) => {
  return (
    <div className={cn(!previousPuzzmon && "invisible")}>
      <button
        aria-label={`Previous Puzzmon in ${zone}`}
        disabled={!previousPuzzmon}
        onClick={
          previousPuzzmon
            ? () => {
                updateQueryParam(
                  MONARCH_QUERY_KEYS.PUZZMON_SLUG,
                  slugify(previousPuzzmon),
                );
                setSelectedMonsterName(previousPuzzmon);
              }
            : undefined
        }
      >
        <CircleArrowLeft className={ARROW_CLASSNAME} />
      </button>
    </div>
  );
};

type IndividualPuzzmonPageProps = {
  puzzmonDetails: MonsterDetails;
  setSelectedMonsterName: React.Dispatch<
    React.SetStateAction<string | undefined>
  >;
  capstoneSlug?: string;
  previousPuzzmon?: string | null;
  nextPuzzmon?: string | null;
  isDarkMode: boolean;
};

function IndividualPuzzmonPage({
  puzzmonDetails,
  setSelectedMonsterName,
  capstoneSlug,
  previousPuzzmon,
  nextPuzzmon,
  isDarkMode,
}: IndividualPuzzmonPageProps) {
  const {
    zone,
    name,
    displayNameSplit,
    subtitle,
    imageSrc,
    imageSrc2,
    altText,
    imageSubtext,
    pronunciationSrc,
    description,
    appetite,
    dimension,
    puzzificationLine,
    fetchableItems,
    favoriteQuote,
    curiosities,
    glitchSections,
    credits,
  } = puzzmonDetails;

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      // Add keyboard listeners so that we can use the arrow keys to navigate between Puzzmon in the same zone.
      if (event.key === "ArrowLeft" && previousPuzzmon) {
        event.preventDefault();
        updateQueryParam(
          MONARCH_QUERY_KEYS.PUZZMON_SLUG,
          slugify(previousPuzzmon),
        );
        setSelectedMonsterName(previousPuzzmon);
      } else if (event.key === "ArrowRight" && nextPuzzmon) {
        event.preventDefault();
        updateQueryParam(MONARCH_QUERY_KEYS.PUZZMON_SLUG, slugify(nextPuzzmon));
        setSelectedMonsterName(nextPuzzmon);
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [previousPuzzmon, nextPuzzmon, setSelectedMonsterName]);

  return (
    <div
      className={`
        monarch-screen-scroll flex h-full
        max-lg:gap-2 max-xl:gap-3 gap-4
        max-lg:py-4 max-xl:py-5 py-6
        overflow-hidden overflow-y-scroll
      `}
    >
      <BackToArchiveButton
        onClick={() => {
          deleteQueryParam(MONARCH_QUERY_KEYS.PUZZMON_SLUG);
          setSelectedMonsterName("");
        }}
        className={`
          absolute max-sm:top-3 max-md:top-4 max-lg:top-6 max-xl:top-9 top-10
          max-sm:left-2 max-md:left-3 max-lg:left-6 max-xl:left-16 left-12
        `}
      />
      <div className={cn(ARROW_WRAPPER_CLASSNAME, "max-sm:hidden")}>
        <PreviousPuzzmonButton
          previousPuzzmon={previousPuzzmon}
          zone={zone}
          setSelectedMonsterName={setSelectedMonsterName}
        />
      </div>
      <div className="flex flex-col flex-1 max-sm:px-4" id="monarch-entry">
        <div className="sm:hidden flex justify-center items-center gap-2">
          <PreviousPuzzmonButton
            previousPuzzmon={previousPuzzmon}
            zone={zone}
            setSelectedMonsterName={setSelectedMonsterName}
          />
          <NextPuzzmonButton
            nextPuzzmon={nextPuzzmon}
            zone={zone}
            setSelectedMonsterName={setSelectedMonsterName}
          />
        </div>
        {/* Puzzmon name & subtitle */}
        <PuzzmonNameAndSubtitle
          name={name}
          displayNameSplit={displayNameSplit}
          subtitle={subtitle}
          pronunciationSrc={pronunciationSrc}
        />
        {!!glitchSections?.length && <style>{GlitchStyles}</style>}
        <div className="flex max-sm:flex-col gap-8 pb-2">
          {/* Puzzmon image */}
          <div className="sm:w-[50%] sm:h-full flex flex-col items-end gap-2">
            <PuzzmonImage
              imageSrc={imageSrc}
              imageSrcDark={imageSrc2}
              altText={altText}
              name={name}
              imageSubtext={imageSubtext}
              isGlitched={!!glitchSections?.length}
              zone={zone}
              isDarkMode={isDarkMode}
            />
            {credits && (
              <div className="flex flex-wrap justify-end text-xs md:text-sm text-monarch-light italic gap-x-2 gap-y-0 max-w-[75%]">
                {credits.design && (
                  <span>Design: {credits.design.join(", ")}</span>
                )}
                {credits.design && credits.render && <span>•</span>}
                {credits.render && (
                  <span>Render: {credits.render.join(", ")}</span>
                )}
                {credits.render && credits.art && <span>•</span>}
                {credits.art && <span>Art: {credits.art.join(", ")}</span>}
              </div>
            )}
            <div className="max-sm:hidden">
              <CopyMonarchEntryButton contentId="monarch-content" />
            </div>
          </div>
          {/* Puzzmon details */}
          <div className="flex flex-col flex-1 gap-4 pr-2 mb-6">
            <DescriptionContent
              sections={[
                {
                  title:
                    zone === MONSTER_ZONES.BUBBLE_COVE
                      ? "Herring description"
                      : "Red herring description",
                  content: parseDescription(
                    insertPuzzmonName(description, name),
                  ),
                },
                {
                  title: "Appetite",
                  content: appetite && (
                    <div className="flex items-center gap-1.5">
                      {[...Array(appetite).keys()].map((_, i) => (
                        <Apple key={i} className="w-8 h-8 fill-white" />
                      ))}
                    </div>
                  ),
                  copyableContent: appetite ? [appetite] : undefined,
                },
                {
                  title: "Puzzification line",
                  content: puzzificationLine && (
                    <ul className="list-none">
                      {getPuzzificationStages(puzzificationLine).map(
                        (stage) => (
                          <li key={stage}>{stage}</li>
                        ),
                      )}
                    </ul>
                  ),
                  copyableContent:
                    puzzificationLine &&
                    getPuzzificationStages(puzzificationLine),
                },
                {
                  title: "Fetchable items",
                  content: fetchableItems && (
                    <div className="flex items-center">
                      {fetchableItems.map(({ src, alt }, i) => {
                        return (
                          <img
                            key={i}
                            src={src}
                            alt={alt}
                            className="max-md:w-16 max-lg:w-20 max-xl:w-28 w-32"
                          />
                        );
                      })}
                    </div>
                  ),
                  copyableContent: fetchableItems?.map(({ src, alt }, i) => {
                    return <img key={i} src={src} alt={alt} />;
                  }),
                },
                {
                  title: "Favorite quote",
                  content: favoriteQuote,
                },
                {
                  title: "Curiosities",
                  content: curiosities && (
                    <ul className="list-disc ml-4">
                      {curiosities.map((curiosity, i) => (
                        <li key={i}>{curiosity}</li>
                      ))}
                    </ul>
                  ),
                  copyableContent: curiosities,
                },
                {
                  title: "Capstone",
                  content: capstoneSlug && (
                    <a
                      href={`/puzzles/${capstoneSlug}`}
                      className="text-[#6BA5F2] hover:text-monarch-accent"
                    >
                      Go to capstone puzzle
                    </a>
                  ),
                },
                {
                  title: "Dimension",
                  content: dimension && (
                    <a
                      href={dimension.url}
                      className="text-[#6BA5F2] hover:text-monarch-accent"
                    >
                      {dimension.name}
                    </a>
                  ),
                },
                {
                  title: "Encounters",
                  content: dimension && (
                    <ul className="list-disc ml-4">
                      <li>
                        <a
                          href={dimension.intro}
                          className="text-[#6BA5F2] hover:text-monarch-accent"
                        >
                          First meeting
                        </a>
                      </li>
                      <li>
                        <a
                          href={dimension.outro}
                          className="text-[#6BA5F2] hover:text-monarch-accent"
                        >
                          Becoming friends
                        </a>
                      </li>
                    </ul>
                  ),
                  copyableContent: dimension
                    ? [
                        <a
                          key="first-meeting"
                          href={dimension.intro}
                          className="text-[#6BA5F2] hover:text-monarch-accent"
                        >
                          First meeting
                        </a>,
                        <a
                          key="becoming-friends"
                          href={dimension.outro}
                          className="text-[#6BA5F2] hover:text-monarch-accent"
                        >
                          Becoming friends
                        </a>,
                      ]
                    : undefined,
                },
                ...(glitchSections ?? []).map((glitchSection) => ({
                  title: glitchSection.title,
                  content: glitchSection.content,
                  isGlitched: true,
                })),
              ]}
            />
          </div>
        </div>
      </div>
      <div className={cn(ARROW_WRAPPER_CLASSNAME, "max-sm:hidden")}>
        <NextPuzzmonButton
          nextPuzzmon={nextPuzzmon}
          zone={zone}
          setSelectedMonsterName={setSelectedMonsterName}
        />
      </div>
    </div>
  );
}

export default IndividualPuzzmonPage;
