import { MONSTER_ZONES, type MonsterDetails } from "@hunt/hunt-data/monarch";
import React from "react";
import MonarchCard from "./MonarchCard";

const sortMonsterList = (monsterDataList: MonsterDetails[], zone?: string) => {
  // Keepers are already sorted in dimension order, so don't re-sort them
  if (zone === MONSTER_ZONES.KEEPERS) {
    return [...monsterDataList];
  }
  // Sort other zones alphabetically by name
  return [...monsterDataList].sort((a, b) => {
    return a.name.localeCompare(b.name);
  });
};

type MonarchSectionProps = {
  monsterDataList: MonsterDetails[];
  updateSelectedMonster: (newMonsterName: string) => void;
  totalCount: number;
  hideUndiscoveredPuzzmon: boolean;
  isDarkMode: boolean;
  zone?: string;
};

function MonarchSection({
  monsterDataList,
  updateSelectedMonster,
  totalCount,
  hideUndiscoveredPuzzmon,
  isDarkMode,
  zone,
}: MonarchSectionProps) {
  return (
    <div className="flex gap-4 flex-wrap">
      {sortMonsterList(monsterDataList, zone).map(
        ({ name, displayNameSplit, imageSrc, imageSrc2, zone }) => {
          const resolvedImage =
            zone === MONSTER_ZONES.THE_BRIGHTS && isDarkMode
              ? (imageSrc2 ?? imageSrc)
              : imageSrc;
          return (
            <MonarchCard
              key={name}
              name={name}
              displayNameSplit={displayNameSplit}
              updateSelectedMonster={updateSelectedMonster}
              puzzmonImage={{
                imageSrc: resolvedImage,
              }}
              isDiscovered
            />
          );
        },
      )}
      {/* Show undiscovered cards. */}
      {!hideUndiscoveredPuzzmon &&
        [...Array(totalCount - monsterDataList.length).keys()].map((i) => {
          return <MonarchCard key={i} />;
        })}
    </div>
  );
}

export default MonarchSection;
