import { MONSTER_DATA, MONSTER_ZONES } from "@hunt/hunt-data/monarch";

type LevelConfig = {
  level: number;
  availablePuzzmon: {
    id: string;
    name: string;
    image: string;
    slug: string;
    order: number | undefined;
    input: string;
    output: string;
    otherText?: string;
  }[];
};

export type TaskDataResponse = {
  levels: LevelConfig[];
  targetPositions: {
    level: number;
    positions: {
      row: number;
      col: number;
      requiredColor:
        | "red"
        | "green"
        | "blue"
        | "yellow"
        | "magenta"
        | "cyan"
        | "lightred"
        | "lightgreen"
        | "lightblue"
        | "white";
    }[];
  }[];
  targetImages: {
    image: string;
    imageSolved: string;
  };
};

// Mapping from puzzmon slug to numeric type ID
// These IDs are used in the frontend to determine transformation behavior
// without exposing slug names in the frontend bundle
const PUZZMON_TYPE_IDS = {
  bumblebeam: 1,
  twinkleish: 2,
  knightbulb: 3,
  lanternbot: 4,
  incandabra: 5,
  glimmerpom: 6,
  prismoidia: 7,
  comettails: 8,
  mistermoon: 9,
} as const;

const LEVEL_CONFIGS = [
  {
    level: 1,
    puzzmonSlugs: [
      "lanternbot",
      "incandabra",
      "glimmerpom",
      "bumblebeam",
      "twinkleish",
      "knightbulb",
      "prismoidia",
      "comettails",
      "mistermoon",
    ],
  },
  {
    level: 2,
    puzzmonSlugs: ["lanternbot", "incandabra", "glimmerpom"],
  },
  {
    level: 3,
    puzzmonSlugs: ["bumblebeam", "twinkleish", "knightbulb"],
  },
  {
    level: 4,
    puzzmonSlugs: ["prismoidia", "comettails", "mistermoon"],
  },
];

const PUZZMON_INPUTS = {
  bumblebeam: {
    input: "1 beam",
    output: "≤ 3 beams",
  },
  twinkleish: {
    input: "3 beams",
    output: "≤ 1 beam",
    otherText: "Hint: In our differences, we are brighter",
  },
  knightbulb: {
    input: "1 beam",
    output: "≤ 1 beam",
  },
  lanternbot: {
    input: "1 beam or 1 spot",
    output: "≤ 1 beam",
  },
  incandabra: {
    input: "1 beam or 1 spot",
    output: "≤ 1 beam",
  },
  glimmerpom: {
    input: "1 beam or 1 spot",
    output: "≤ 8 spots",
  },
  prismoidia: {
    input: "1 beam",
    output: "1 beam and ≤ 6 spots",
  },
  comettails: {
    input: "1 beam",
    output: "2 beams",
  },
  mistermoon: {
    input: "1 spot",
    output: "≤ 4 beams",
    otherText: "Hint: It needs space to truly shine",
  },
};

// Wattissimo position & goals with color requirements per position
const WATTISSIMO_POSITIONS = [
  {
    level: 1,
    positions: [], // Sandbox level has no targets
  },
  {
    level: 2,
    positions: [
      { row: 0, col: 0, requiredColor: "blue" as const, hex: "#0000FF" },
      { row: 0, col: 6, requiredColor: "magenta" as const, hex: "#FF00FF" },
      { row: 1, col: 5, requiredColor: "red" as const, hex: "#FF0000" },
      { row: 3, col: 3, requiredColor: "magenta" as const, hex: "#FF00FF" },
      { row: 4, col: 0, requiredColor: "blue" as const, hex: "#0000FF" },
      { row: 4, col: 4, requiredColor: "red" as const, hex: "#FF0000" },
    ],
  },
  {
    level: 3,
    positions: [
      { row: 2, col: 6, requiredColor: "yellow" as const, hex: "#FFFF00" },
    ],
  },
  {
    level: 4,
    positions: [
      { row: 0, col: 0, requiredColor: "yellow" as const, hex: "#FFFF00" },
      { row: 2, col: 6, requiredColor: "magenta" as const, hex: "#FF00FF" },
      { row: 3, col: 0, requiredColor: "cyan" as const, hex: "#00FFFF" },
      { row: 4, col: 6, requiredColor: "white" as const, hex: "#FFFFFF" },
    ],
  },
];

export const getData = (): TaskDataResponse => {
  const theBrightsPuzzmon = MONSTER_DATA[MONSTER_ZONES.THE_BRIGHTS];

  const levels: LevelConfig[] = LEVEL_CONFIGS.map((config) => ({
    level: config.level,
    availablePuzzmon: config.puzzmonSlugs
      .map((slug) => {
        const puzzmonData =
          theBrightsPuzzmon[slug as keyof typeof theBrightsPuzzmon];
        if (!puzzmonData) return null;

        // Get numeric type ID for this puzzmon (defaults to 0 if not found)
        const typeId =
          PUZZMON_TYPE_IDS[slug as keyof typeof PUZZMON_TYPE_IDS] ?? 0;
        const puzzmonInputs =
          PUZZMON_INPUTS[slug as keyof typeof PUZZMON_INPUTS];

        return {
          id: String(typeId), // Send numeric ID as string
          name: puzzmonData.name,
          image: puzzmonData.imageSrc,
          slug: slug, // Keep slug for internal use, but frontend uses id
          order: puzzmonData.order,
          input: puzzmonInputs.input,
          output: puzzmonInputs.output,
          otherText:
            "otherText" in puzzmonInputs ? puzzmonInputs.otherText : undefined,
        };
      })
      .filter((p): p is NonNullable<typeof p> => p !== null),
  }));

  const wattissimo = theBrightsPuzzmon.wattissimo as {
    imageSrc: string;
    imageSrc2?: string;
  };

  return {
    levels,
    targetPositions: WATTISSIMO_POSITIONS,
    targetImages: {
      image: wattissimo.imageSrc2 ?? wattissimo.imageSrc,
      imageSolved: wattissimo.imageSrc ?? wattissimo.imageSrc2,
    },
  };
};
