import { useDraggable, useDroppable } from "@dnd-kit/core";
import {
  type Tile,
  type PuzzmonPreferences,
  checkPreferenceAtPosition,
} from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import { Check, X } from "lucide-react";
import React from "react";

type GridCellProps = {
  row: number;
  col: number;
  tile: Tile | null;
  onDrop: (tile: Tile, row: number, col: number) => void;
  onRemove: (row: number, col: number) => void;
  draggedTile?:
    | (Tile & { fromGrid?: boolean; gridRow?: number; gridCol?: number })
    | null;
  preferencesData: PuzzmonPreferences[];
  gridState: (Tile | null)[][];
};

const GridTile: React.FC<{
  tile: Tile;
  row: number;
  col: number;
  onRemove: (row: number, col: number) => void;
  preferencesData: PuzzmonPreferences[];
  gridState: (Tile | null)[][];
}> = ({ tile, row, col, onRemove: _onRemove, preferencesData, gridState }) => {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: `grid-tile-${row}-${col}`,
    data: {
      ...tile,
      fromGrid: true,
      gridRow: row,
      gridCol: col,
    },
  });

  // Get preferences for puzzmon tiles and evaluate them for this specific position
  const preferences =
    tile.type === "puzzmon"
      ? (() => {
          const puzzmonData = preferencesData.find((p) => p.id === tile.id);
          if (!puzzmonData) return [];

          return puzzmonData.preferences.map((preference) => ({
            ...preference,
            satisfied: checkPreferenceAtPosition(
              gridState,
              row,
              col,
              preference,
            ),
          }));
        })()
      : [];

  return (
    <div ref={setNodeRef} className="relative w-full h-full">
      <img
        {...attributes}
        {...listeners}
        className={cn(
          "w-full h-full object-contain cursor-grab",
          isDragging && "opacity-40",
        )}
        style={isDragging ? { transform: "none" } : undefined}
        alt={tile.name}
        src={tile.image}
      />

      {/* Preference status indicators */}
      {preferences.length > 0 && !isDragging && (
        <div className="absolute top-1 left-1 flex flex-col gap-0.5">
          {preferences.map((preference) => (
            <div
              key={preference.id}
              className="w-4 h-4 rounded-full bg-white border border-gray-300 flex items-center justify-center shadow-sm"
            >
              {preference.satisfied ? (
                <Check className="w-2.5 h-2.5 text-green-600" strokeWidth={4} />
              ) : (
                <X className="w-2.5 h-2.5 text-red-500" strokeWidth={4} />
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

const GridCell: React.FC<GridCellProps> = ({
  row,
  col,
  tile,
  onDrop: _onDrop,
  onRemove,
  draggedTile,
  preferencesData,
  gridState,
}) => {
  const { setNodeRef, isOver } = useDroppable({
    id: `grid-cell-${row}-${col}`,
    data: {
      row,
      col,
      type: "grid-cell",
    },
  });

  const showPreview = isOver && draggedTile && !tile;
  const isSameCell =
    draggedTile?.fromGrid &&
    draggedTile.gridRow === row &&
    draggedTile.gridCol === col;

  return (
    <div
      ref={setNodeRef}
      className={cn(
        "aspect-square border-2 border-gray-300 flex items-center justify-center text-sm font-medium",
        isOver && !isSameCell && "border-blue-400",
        tile && "border-gray-500",
      )}
    >
      {tile && (
        <GridTile
          tile={tile}
          row={row}
          col={col}
          onRemove={onRemove}
          preferencesData={preferencesData}
          gridState={gridState}
        />
      )}
      {showPreview && draggedTile && (
        <img
          className="w-full h-full object-contain opacity-50"
          alt={draggedTile.name}
          src={draggedTile.image}
        />
      )}
    </div>
  );
};

type GridGameBoardProps = {
  onTilePlace: (tile: Tile, row: number, col: number) => void;
  onTileRemove: (row: number, col: number) => void;
  gridState: (Tile | null)[][];
  draggedTile?:
    | (Tile & { fromGrid?: boolean; gridRow?: number; gridCol?: number })
    | null;
  preferencesData: PuzzmonPreferences[];
};

export const GridGameBoard: React.FC<GridGameBoardProps> = ({
  onTilePlace,
  onTileRemove,
  gridState,
  draggedTile,
  preferencesData,
}) => {
  return (
    <div className="aspect-square grow h-full max-h-full grid grid-cols-5 grid-rows-5 gap-1">
      {gridState.map((row, rowIndex) =>
        row.map((tile, colIndex) => (
          <GridCell
            key={`${rowIndex}-${colIndex}`}
            row={rowIndex}
            col={colIndex}
            tile={tile}
            onDrop={onTilePlace}
            onRemove={onTileRemove}
            draggedTile={draggedTile}
            preferencesData={preferencesData}
            gridState={gridState}
          />
        )),
      )}
    </div>
  );
};
