import { type MonsterDetails } from "@hunt/hunt-data/monarch";
import { newClient, type TeamHuntState } from "@hunt/public-client";
import { useGlobalVolume } from "@hunt/puzzle-components";
import { useCallback, useState, useEffect, useMemo, useRef } from "react";
import apiUrl from "../../../../utils/apiUrl";
import { IS_STATIC_SITE } from "../../../../utils/staticSite";
import { markTaskSolved } from "../../../puzzleSolveLocalState";
import appleMunchSound from "./assets/apple_munch.mp3";
import gemCollectSound from "./assets/gem_munch.mp3";
import PortalBlue from "./assets/portal_blue.png";
import PortalPurple from "./assets/portal_purple.png";
import { type Direction, GameState, type Position, type Wall } from "./types";

export type Bomb = {
  position: Position;
  value: number;
};

export type SnakeType =
  | "blue"
  | "brown"
  | "green"
  | "grey"
  | "light_blue"
  | "orange"
  | "dark_orange";

export type Gem = {
  position: Position;
  snakeType: SnakeType;
};

export type Portal = {
  id: string;
  position: Position;
  linkedPortalId: string;
  imageSrc: string;
};

export type SnakePower =
  | "use_portals"
  | "move_rocks"
  | "eat_bombs"
  | "pass_through_walls"
  | "pass_through_itself"
  | "ice_movement"
  | "only_one_apple";

export enum DeathReason {
  HIT_WALL = "HIT_WALL",
  BOMB_EXPLODED = "BOMB_EXPLODED",
  HIT_BOULDER = "HIT_BOULDER",
  HIT_SELF = "HIT_SELF",
  TOO_MANY_APPLES = "TOO_MANY_APPLES",
}

const GRID_ROWS = 8;
const GRID_COLS = 12;
export const END_LOCATION: Position = { x: 8, y: 1 };
const SUBMISSION_ERROR =
  "An unexpected error occurred submitting the task. Please try again later.";

// Define walls as borders between tiles
const WALLS: Wall[] = [
  { from: { x: 5, y: 0 }, to: { x: 5, y: 7 }, direction: "vertical" },
  { from: { x: 0, y: 4 }, to: { x: 1, y: 4 }, direction: "horizontal" },
  { from: { x: 2, y: 5 }, to: { x: 2, y: 5 }, direction: "horizontal" },
  { from: { x: 1, y: 5 }, to: { x: 1, y: 5 }, direction: "vertical" },
  { from: { x: 2, y: 6 }, to: { x: 2, y: 7 }, direction: "vertical" },
  { from: { x: 8, y: 0 }, to: { x: 8, y: 3 }, direction: "vertical" },
  { from: { x: 9, y: 3 }, to: { x: 9, y: 3 }, direction: "horizontal" },
  { from: { x: 9, y: 3 }, to: { x: 9, y: 3 }, direction: "vertical" },
  { from: { x: 10, y: 2 }, to: { x: 11, y: 2 }, direction: "horizontal" },
  { from: { x: -1, y: 0 }, to: { x: -1, y: 7 }, direction: "vertical" },
  { from: { x: 0, y: 7 }, to: { x: 11, y: 7 }, direction: "horizontal" },
  { from: { x: 11, y: 0 }, to: { x: 11, y: 7 }, direction: "vertical" },
  { from: { x: 0, y: -1 }, to: { x: 11, y: -1 }, direction: "horizontal" },
];

// Check if there's a wall blocking movement from one position to another
const isWallBlocking = (from: Position, to: Position): boolean => {
  const deltaX = to.x - from.x;
  const deltaY = to.y - from.y;

  return WALLS.some((wall) => {
    if (deltaX !== 0 && wall.direction === "vertical") {
      return (
        Math.min(from.x, to.x) === wall.from.x &&
        Math.max(from.x, to.x) === wall.from.x + 1 &&
        Math.min(wall.from.y, wall.to.y) <= from.y &&
        Math.max(wall.from.y, wall.to.y) >= from.y
      );
    }

    if (deltaY !== 0 && wall.direction === "horizontal") {
      return (
        Math.min(from.y, to.y) === wall.from.y &&
        Math.max(from.y, to.y) === wall.from.y + 1 &&
        Math.min(wall.from.x, wall.to.x) <= from.x &&
        Math.max(wall.from.x, wall.to.x) >= from.x
      );
    }
  });
};

// Define apple positions as fixed locations
const APPLES: Position[] = [
  { x: 1, y: 0 },
  { x: 5, y: 1 },
  { x: 1, y: 2 },
  { x: 6, y: 0 },
  { x: 11, y: 6 },
  { x: 8, y: 7 },
  { x: 9, y: 1 },
];

const STARTING_BOULDERS = [
  { x: 0, y: 1 },
  { x: 4, y: 1 },
  { x: 4, y: 2 },
  { x: 5, y: 2 },
  { x: 8, y: 0 },
  { x: 6, y: 2 },
  { x: 8, y: 2 },
  { x: 8, y: 4 },
  { x: 6, y: 6 },
  { x: 10, y: 7 },
];

const STARTING_BOMBS: Bomb[] = [{ position: { x: 4, y: 4 }, value: 10 }];

const STARTING_GEMS: Gem[] = [
  { position: { x: 1, y: 1 }, snakeType: "blue" },
  { position: { x: 1, y: 3 }, snakeType: "orange" },
  { position: { x: 0, y: 5 }, snakeType: "grey" },
  { position: { x: 4, y: 6 }, snakeType: "green" },
  { position: { x: 6, y: 3 }, snakeType: "light_blue" },
  { position: { x: 10, y: 2 }, snakeType: "green" },
  { position: { x: 9, y: 7 }, snakeType: "dark_orange" },
];

const STARTING_PORTALS: Portal[] = [
  {
    id: "portal1",
    position: { x: 4, y: 7 },
    linkedPortalId: "portal2",
    imageSrc: PortalBlue,
  },
  {
    id: "portal2",
    position: { x: 0, y: 7 },
    linkedPortalId: "portal1",
    imageSrc: PortalBlue,
  },
  {
    id: "portal3",
    position: { x: 7, y: 3 },
    linkedPortalId: "portal4",
    imageSrc: PortalPurple,
  },
  {
    id: "portal4",
    position: { x: 9, y: 0 },
    linkedPortalId: "portal3",
    imageSrc: PortalPurple,
  },
];

function useSnake(
  puzzmonData: MonsterDetails[],
  teamState: TeamHuntState | undefined,
  taskSlug: string | undefined,
) {
  const [gameState, setGameState] = useState<GameState>(GameState.START_SCREEN);
  const [deathReason, setDeathReason] = useState<DeathReason | undefined>();
  const [snake, setSnake] = useState<
    { position: Position; visible: boolean }[]
  >([
    { position: { x: 0, y: 0 }, visible: true },
    { position: { x: -1, y: 0 }, visible: false },
  ]);
  const [direction, setDirection] = useState<Direction | null>(null);
  const [collectedApples, setCollectedApples] = useState<Set<number>>(
    new Set(),
  );
  const [boulders, setBoulders] = useState<Position[]>(STARTING_BOULDERS);
  const [bombs, setBombs] = useState<Bomb[]>(STARTING_BOMBS);
  const [gems, setGems] = useState<Gem[]>(STARTING_GEMS);
  const [collectedGems, setCollectedGems] = useState<Set<number>>(new Set());
  const [snakeType, setSnakeType] = useState<SnakeType>("brown");
  const [explosionPosition, setExplosionPosition] = useState<Position | null>(
    null,
  );
  const [portals] = useState<Portal[]>(STARTING_PORTALS);
  const [isMoving, setIsMoving] = useState(false); // For ice_movement power
  const [showWinAnimation, setShowWinAnimation] = useState(false);
  const [submissionError, setSubmissionError] = useState<string | undefined>();
  const previousDirection = useRef<Direction | null>();
  const [applesEaten, setApplesEaten] = useState<number>(0);
  const [showExplosionDelay, setShowExplosionDelay] = useState(false);

  const appleMunchAudioRef = useRef<HTMLAudioElement | null>(null);
  const gemCollectAudioRef = useRef<HTMLAudioElement | null>(null);
  const explosionTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const globalVolume = useGlobalVolume();

  const powers = useMemo(
    () =>
      puzzmonData.find((p) => p.serpentineHillsMonarchTask?.color === snakeType)
        ?.serpentineHillsMonarchTask?.specialPowers ?? [],
    [puzzmonData, snakeType],
  );

  const hasTeamSubmitted = !!teamState?.puzzles[taskSlug ?? ""]?.solved;

  const startGame = useCallback(() => {
    setGameState(GameState.PLAYING);
    setSnake([
      { position: { x: 0, y: 0 }, visible: true },
      { position: { x: -1, y: 0 }, visible: false },
    ]);
    setDirection(null);
    setCollectedApples(new Set());
    setCollectedGems(new Set());
    setSnakeType("brown");
    setApplesEaten(0);
    setExplosionPosition(null);
    setIsMoving(false);
    setBombs(STARTING_BOMBS.map((bomb) => ({ ...bomb })));
    setGems(STARTING_GEMS.map((gem) => ({ ...gem })));
    setBoulders(STARTING_BOULDERS);
    setShowExplosionDelay(false);
    // Clear any pending explosion timeout
    if (explosionTimeoutRef.current) {
      clearTimeout(explosionTimeoutRef.current);
      explosionTimeoutRef.current = null;
    }
  }, []);

  const submitTask = useCallback(async () => {
    // If already submitted, just show the win animation without hitting the server
    if (hasTeamSubmitted) {
      setShowWinAnimation(true);
      setSubmissionError(undefined);
      return;
    }

    if (IS_STATIC_SITE) {
      const slug = taskSlug ?? "monarch_serpentine_hills_task";
      markTaskSolved(slug);
      setShowWinAnimation(true);
      setSubmissionError(undefined);
      return;
    }

    setSubmissionError("Submitting...");

    try {
      const apiClient = newClient(apiUrl(), undefined);
      const response = await apiClient.submitGuess({
        body: { guess: "" },
        params: { slug: taskSlug ?? "monarch_serpentine_hills_task" },
      });

      if (response.status === 200) {
        const solved = response.body.guesses.some(
          (guess) => guess.status === "correct",
        );
        if (solved) {
          setShowWinAnimation(true);
          setSubmissionError(undefined);
        } else {
          setSubmissionError(SUBMISSION_ERROR);
        }
      } else {
        setSubmissionError(SUBMISSION_ERROR);
      }
    } catch (error: unknown) {
      console.error("Failed to submit score:", error);
      setSubmissionError(SUBMISSION_ERROR);
    }
  }, [taskSlug, hasTeamSubmitted]);

  const moveSnake = useCallback(
    (newDirection: Direction) => {
      if (gameState !== GameState.PLAYING) return;

      // Ice movement: once moving, can't change direction until hitting wall

      if (!powers.includes("ice_movement") || !isMoving) {
        setDirection(newDirection);
      } else {
        newDirection = direction ?? newDirection;
      }
      setIsMoving(true);

      const head = snake[0];

      let newHead: Position = applyDirection(head.position, newDirection);
      let extraSegments: { position: Position; visible: boolean }[] = [];
      let newSnakeType = snakeType;
      let newBombs = [...bombs];
      let newBoulders = [...boulders];

      const enteredPortal = portals.find(
        (portal) =>
          portal.position.x === newHead.x && portal.position.y === newHead.y,
      );

      if (enteredPortal && powers.includes("use_portals")) {
        const linkedPortal = portals.find(
          (p) => p.id === enteredPortal.linkedPortalId,
        );
        if (linkedPortal) {
          // Teleport the head to the linked portal position
          const teleportedHead = {
            x: linkedPortal.position.x,
            y: linkedPortal.position.y,
          };
          newHead = applyDirection(teleportedHead, newDirection);
          extraSegments = [
            { position: linkedPortal.position, visible: false },
            { position: enteredPortal.position, visible: false },
          ];
        }
      }

      const gemIndex = gems.findIndex(
        (gem) =>
          gem.position.x === newHead.x &&
          gem.position.y === newHead.y &&
          !collectedGems.has(gems.indexOf(gem)),
      );
      const ateGem = gemIndex !== -1;

      // Change snake type and mark gem as collected if one was eaten
      if (ateGem) {
        // Cancel any currently playing audio
        if (gemCollectAudioRef.current) {
          gemCollectAudioRef.current.pause();
          gemCollectAudioRef.current.currentTime = 0;
        }

        // Play gem collection sound
        const audio = new Audio(gemCollectSound);
        audio.volume = globalVolume;
        gemCollectAudioRef.current = audio;
        void audio.play().catch(() => {
          // Ignore audio play errors (e.g., if user hasn't interacted with page yet)
        });
        const gem = gems[gemIndex];
        newSnakeType = gem.snakeType;
        setSnakeType(gem.snakeType);
        setApplesEaten(0);
        setCollectedGems((prev) => new Set(prev).add(gemIndex));
      }
      const newPowers =
        puzzmonData.find(
          (p) => p.serpentineHillsMonarchTask?.color === newSnakeType,
        )?.serpentineHillsMonarchTask?.specialPowers ?? [];

      // Check if snake ate an apple (only if not pass_through_walls)
      let ateApple = false;
      let appleIndex = -1;
      if (!newPowers.includes("pass_through_walls")) {
        appleIndex = APPLES.findIndex(
          (apple) =>
            apple.x === newHead.x &&
            apple.y === newHead.y &&
            !collectedApples.has(APPLES.indexOf(apple)),
        );
        ateApple = appleIndex !== -1;
      }

      let hitBomb = newBombs.find(
        (bomb) =>
          bomb.position.x === newHead.x && bomb.position.y === newHead.y,
      );
      if (newPowers.includes("eat_bombs") && hitBomb !== undefined) {
        // Remove the bomb instead of dying
        newBombs = newBombs.filter(
          (b) =>
            b.position.x !== hitBomb?.position.x ||
            b.position.y !== hitBomb?.position.y,
        );
        ateApple = true;
        hitBomb = undefined;
      }

      if (ateApple) {
        // Cancel any currently playing audio
        if (appleMunchAudioRef.current) {
          appleMunchAudioRef.current.pause();
          appleMunchAudioRef.current.currentTime = 0;
        }

        // Play apple munch sound
        const audio = new Audio(appleMunchSound);
        audio.volume = globalVolume;
        appleMunchAudioRef.current = audio;
        void audio.play().catch(() => {
          // Ignore audio play errors (e.g., if user hasn't interacted with page yet)
        });
        setApplesEaten((prev) => prev + 1);
      }

      let snakeCopy = snake.map((s) => ({
        position: { x: s.position.x, y: s.position.y },
        visible: s.visible,
      }));

      // Sort of hacky - to get the snake to look right when going through portals we insert
      // invisible segments on top of the portal. Once these get to the end of the snake, we
      // need to remove them.
      for (let i = snakeCopy.length - 1; i >= 0; i--) {
        if (!snakeCopy[i].visible && i - 1 >= 0 && !snakeCopy[i - 1].visible) {
          snakeCopy = snakeCopy.slice(0, i);
        } else {
          break;
        }
      }

      // Move snake - if ate apple, don't remove tail (grow by 1)
      const newSnakeBody = ateApple ? snakeCopy : snakeCopy.slice(0, -1);
      newSnakeBody[newSnakeBody.length - 1].visible = false;
      const newSnake = [
        { position: newHead, visible: true },
        ...extraSegments,
        ...newSnakeBody,
      ];

      setSnake(newSnake);

      // Mark apple as collected if one was eaten
      if (ateApple) {
        setCollectedApples((prev) => new Set(prev).add(appleIndex));
      }

      if (ateApple && newPowers.includes("only_one_apple") && applesEaten > 0) {
        setGameState(GameState.GAME_OVER);
        setDeathReason(DeathReason.TOO_MANY_APPLES);
        return;
      }

      // Check boundary collision (always applies)
      if (
        !powers.includes("pass_through_walls") &&
        (newHead.x < 0 ||
          newHead.x >= GRID_COLS ||
          newHead.y < 0 ||
          newHead.y >= GRID_ROWS)
      ) {
        setDeathReason(DeathReason.HIT_WALL);
        setGameState(GameState.GAME_OVER);
        return;
      }

      const squareInFront = applyDirection(newSnake[0].position, newDirection);
      if (
        squareInFront.x < 0 ||
        squareInFront.y < 0 ||
        squareInFront.x >= GRID_COLS ||
        squareInFront.y >= GRID_ROWS ||
        isWallBlocking(newHead, squareInFront) ||
        newBoulders.some(
          (boulder) =>
            boulder.x === squareInFront.x && boulder.y === squareInFront.y,
        )
      ) {
        setIsMoving(false);
      }

      // Check self collision (only if not pass_through_walls or doesn't have pass_through_itself)
      if (!newPowers.includes("pass_through_itself")) {
        if (
          newSnakeBody.some(
            (segment) =>
              segment.visible &&
              segment.position.x === newHead.x &&
              segment.position.y === newHead.y,
          )
        ) {
          setDeathReason(DeathReason.HIT_SELF);
          setGameState(GameState.GAME_OVER);
          return;
        }
      }

      // Pass through walls power - skip most collision checks
      if (!newPowers.includes("pass_through_walls")) {
        // Check wall collision
        if (isWallBlocking(head.position, newHead)) {
          setDeathReason(DeathReason.HIT_WALL);
          setGameState(GameState.GAME_OVER);
          return;
        }

        // Check boulder collision
        const hitBoulder = newBoulders.find(
          (boulder) => boulder.x === newHead.x && boulder.y === newHead.y,
        );
        if (hitBoulder) {
          if (newPowers.includes("move_rocks")) {
            // Push the boulder
            const pushDirection = {
              x: newHead.x - head.position.x,
              y: newHead.y - head.position.y,
            };
            const newBoulderPos = {
              x: hitBoulder.x + pushDirection.x,
              y: hitBoulder.y + pushDirection.y,
            };

            // Check if boulder can be pushed (within bounds and no obstacles)
            if (
              newBoulderPos.x >= 0 &&
              newBoulderPos.x < GRID_COLS &&
              newBoulderPos.y >= 0 &&
              newBoulderPos.y < GRID_ROWS &&
              !boulders.some(
                (b) => b.x === newBoulderPos.x && b.y === newBoulderPos.y,
              ) &&
              !bombs.some(
                (b) =>
                  b.position.x === newBoulderPos.x &&
                  b.position.y === newBoulderPos.y,
              )
            ) {
              newBoulders = newBoulders.map((b) =>
                b.x === hitBoulder.x && b.y === hitBoulder.y
                  ? newBoulderPos
                  : b,
              );
            } else {
              // Can't push boulder, game over
              setGameState(GameState.GAME_OVER);
              setDeathReason(DeathReason.HIT_BOULDER);
              return;
            }
          } else {
            setGameState(GameState.GAME_OVER);
            setDeathReason(DeathReason.HIT_BOULDER);
            return;
          }
        }

        // Check bomb collision
        if (hitBomb) {
          // Clear any existing explosion timeout
          if (explosionTimeoutRef.current) {
            clearTimeout(explosionTimeoutRef.current);
          }
          setExplosionPosition(hitBomb.position);
          setShowExplosionDelay(true);
          setDeathReason(DeathReason.BOMB_EXPLODED);
          // Delay game over to show explosion
          explosionTimeoutRef.current = setTimeout(() => {
            setGameState(GameState.GAME_OVER);
            setShowExplosionDelay(false);
            explosionTimeoutRef.current = null;
          }, 600);
          return;
        }
      }

      // Update bomb countdowns and check for explosion
      newBombs = newBombs.map((bomb) => ({
        ...bomb,
        value: bomb.value - 1,
      }));

      // Check if any bomb reached 0
      const explodedBomb = newBombs.find((bomb) => bomb.value <= 0);
      if (explodedBomb) {
        // Clear any existing explosion timeout
        if (explosionTimeoutRef.current) {
          clearTimeout(explosionTimeoutRef.current);
        }
        setExplosionPosition(explodedBomb.position);
        setShowExplosionDelay(true);
        setDeathReason(DeathReason.BOMB_EXPLODED);
        // Delay game over to show explosion
        explosionTimeoutRef.current = setTimeout(() => {
          setGameState(GameState.GAME_OVER);
          setShowExplosionDelay(false);
          explosionTimeoutRef.current = null;
        }, 600);
      }

      if (
        END_LOCATION.x === newHead.x &&
        END_LOCATION.y === newHead.y &&
        collectedApples.size === APPLES.length + STARTING_BOMBS.length
      ) {
        setGameState(GameState.WON);
        void submitTask();
        return;
      }

      setBombs(newBombs);
      setBoulders(newBoulders);

      // If the player just changed snake types then something might be in the middle of
      // their body (e.g. a wall or a rock).
      if (!newPowers.includes("pass_through_walls")) {
        if (
          newSnake.some((p) =>
            newBombs.some(
              (bomb) =>
                p.visible &&
                bomb.position.x === p.position.x &&
                bomb.position.y === p.position.y,
            ),
          )
        ) {
          setDeathReason(DeathReason.BOMB_EXPLODED);
          // Find the bomb that the snake is overlapping with
          const overlappingBomb = newBombs.find((bomb) =>
            newSnake.some(
              (p) =>
                p.visible &&
                bomb.position.x === p.position.x &&
                bomb.position.y === p.position.y,
            ),
          );
          if (overlappingBomb) {
            // Clear any existing explosion timeout
            if (explosionTimeoutRef.current) {
              clearTimeout(explosionTimeoutRef.current);
            }
            setExplosionPosition(overlappingBomb.position);
            setShowExplosionDelay(true);
            // Delay game over to show explosion
            explosionTimeoutRef.current = setTimeout(() => {
              setGameState(GameState.GAME_OVER);
              setShowExplosionDelay(false);
              explosionTimeoutRef.current = null;
            }, 600);
          } else {
            setGameState(GameState.GAME_OVER);
          }
          return;
        }

        if (
          newSnake.some((p) =>
            newBoulders.some(
              (boulder) =>
                p.visible &&
                boulder.x === p.position.x &&
                boulder.y === p.position.y,
            ),
          )
        ) {
          setDeathReason(DeathReason.HIT_BOULDER);
          setGameState(GameState.GAME_OVER);
          return;
        }

        if (
          newSnake
            .slice(0, -1)
            .some(
              (p, i) =>
                p.visible &&
                newSnake[i + 1].visible &&
                isWallBlocking(p.position, newSnake[i + 1].position),
            )
        ) {
          setDeathReason(DeathReason.HIT_WALL);
          setGameState(GameState.GAME_OVER);
          return;
        }
      }

      if (
        !newPowers.includes("pass_through_itself") &&
        newSnake.some(
          (p) =>
            count(
              newSnake.filter((p) => p.visible).map((s) => s.position),
              p.position,
            ) > 1,
        )
      ) {
        setDeathReason(DeathReason.HIT_SELF);
        setGameState(GameState.GAME_OVER);
      }
    },
    [
      gameState,
      powers,
      isMoving,
      snake,
      snakeType,
      bombs,
      boulders,
      portals,
      gems,
      puzzmonData,
      applesEaten,
      collectedApples,
      direction,
      collectedGems,
      globalVolume,
      submitTask,
    ],
  );

  // Handle keyboard input
  useEffect(() => {
    const handleKeyPress = (e: KeyboardEvent) => {
      if (gameState !== GameState.PLAYING || showExplosionDelay) return;

      if (powers.includes("ice_movement") && isMoving) {
        return;
      }

      switch (e.key) {
        case "W":
        case "w":
        case "ArrowUp":
          if (direction !== "DOWN") {
            e.preventDefault();
            moveSnake("UP");
          }
          break;
        case "S":
        case "s":
        case "ArrowDown":
          if (direction !== "UP") {
            e.preventDefault();
            moveSnake("DOWN");
          }
          break;
        case "A":
        case "a":
        case "ArrowLeft":
          if (direction !== "RIGHT") {
            e.preventDefault();
            moveSnake("LEFT");
          }
          break;
        case "D":
        case "d":
        case "ArrowRight":
          if (direction !== "LEFT") {
            e.preventDefault();
            moveSnake("RIGHT");
          }
          break;
      }

      previousDirection.current = direction;
    };

    window.addEventListener("keydown", handleKeyPress);
    return () => {
      window.removeEventListener("keydown", handleKeyPress);
    };
  }, [gameState, moveSnake, direction, powers, isMoving, showExplosionDelay]);

  const hideWinAnimation = useCallback(() => {
    setShowWinAnimation(false);
  }, []);

  useEffect(() => {
    if (powers.includes("ice_movement") && isMoving && !showExplosionDelay) {
      setTimeout(() => {
        moveSnake(direction ?? "RIGHT");
      }, 300);
    }
  }, [moveSnake, direction, powers, isMoving, showExplosionDelay]);

  // Cleanup explosion timeout on unmount
  useEffect(() => {
    return () => {
      if (explosionTimeoutRef.current) {
        clearTimeout(explosionTimeoutRef.current);
        explosionTimeoutRef.current = null;
      }
    };
  }, []);

  return {
    startGame,
    gameState,
    snake,
    direction,
    previousDirection: previousDirection.current,
    walls: WALLS,
    apples: APPLES,
    collectedApples,
    boulders,
    bombs,
    gems,
    collectedGems,
    snakeType,
    explosionPosition,
    portals,
    showWinAnimation,
    hideWinAnimation,
    submissionError,
    powers,
    deathReason,
    showExplosionDelay,
  };
}

const applyDirection = (position: Position, direction: Direction): Position => {
  switch (direction) {
    case "UP":
      return { x: position.x, y: position.y - 1 };
    case "DOWN":
      return { x: position.x, y: position.y + 1 };
    case "LEFT":
      return { x: position.x - 1, y: position.y };
    case "RIGHT":
      return { x: position.x + 1, y: position.y };
    default:
      throw new Error("what");
  }
};

const count = (snake: Position[], target: Position): number =>
  snake.reduce(
    (acc, p) => (p.x === target.x && p.y === target.y ? acc + 1 : acc),
    0,
  );

export default useSnake;
