import { useCallback, useEffect, useState } from "react";
import { ROUND_1_WORD_POOL, ROUND_2_WORD_POOL, type Word } from "./constants";

type UseWordManagerReturn = {
  reset: () => void;
  nextWordWrapper: { fn: () => [string, string] | undefined };
  advanceRound: () => void;
  roundNumber: number;
};

export function useWordManager(length: number): UseWordManagerReturn {
  const [wordList, setWordList] = useState((): Word[] =>
    generateWordList(length),
  );

  const [nextWordIndex, setNextWordIndex] = useState(0);
  const [roundNumber, setRoundNumber] = useState(0);
  const [nextWordWrapper] = useState<{
    fn: () => [string, string] | undefined;
  }>({
    fn: () => ["", ""],
  });

  const getNextWord = useCallback((): [string, string] | undefined => {
    if (nextWordIndex >= wordList.length) {
      return undefined;
    }

    setNextWordIndex(nextWordIndex + 1);

    const key = wordList[nextWordIndex];
    let value: string;
    if (roundNumber === 0) {
      value = ROUND_1_WORD_POOL[key];
    } else if (roundNumber === 1) {
      value = ROUND_2_WORD_POOL[key];
    } else {
      throw new Error("invalid!");
    }

    return [key, value];
  }, [nextWordIndex, roundNumber, wordList]);

  useEffect(() => {
    nextWordWrapper.fn = getNextWord;
  }, [getNextWord, nextWordWrapper]);

  const reset = useCallback(() => {
    setRoundNumber(0);
    setNextWordIndex(0);
    setWordList(generateWordList(length));
  }, [length]);

  const advanceRound = useCallback(() => {
    if (roundNumber === 1) {
      throw new Error("cannot advance past the last round");
    }

    setRoundNumber(roundNumber + 1);
    setNextWordIndex(0);

    setWordList(shuffle(wordList));
  }, [roundNumber, wordList]);

  const roundNumber1Indexed: number = roundNumber + 1;

  return {
    reset,
    nextWordWrapper,
    advanceRound,
    roundNumber: roundNumber1Indexed, // Convert to 1-indexed (1 = round 1, 2 = round 2)
  };
}

function generateWordList(length: number): Word[] {
  if (length > Object.keys(ROUND_1_WORD_POOL).length) {
    throw new Error("required round score must be less than word list length");
  }

  return shuffle(Array.from(Object.keys(ROUND_1_WORD_POOL)) as Word[]).slice(
    0,
    length,
  );
}

function shuffle(array: Word[]) {
  let currentIndex = array.length;

  const copy = [...array];

  // While there remain elements to shuffle...
  while (currentIndex !== 0) {
    // Pick a remaining element...
    const randomIndex = Math.floor(Math.random() * currentIndex);
    currentIndex--;

    // And swap it with the current element.
    [copy[currentIndex], copy[randomIndex]] = [
      copy[randomIndex],
      copy[currentIndex],
    ];
  }

  return copy;
}
