import { newClient } from "@hunt/public-client";
import { useGlobalVolume } from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import React, { useCallback, useState, useRef, useMemo } from "react";
import apiUrl from "../../../../utils/apiUrl";
import { IS_STATIC_SITE } from "../../../../utils/staticSite";
import { markTaskSolved } from "../../../puzzleSolveLocalState";
import { BackToArchiveButton } from "../../components/MonarchButton";
import MonarchTaskWrapper from "../MonarchTaskWrapper";
import TaskSolvedMessage from "../TaskSolvedMessage";
import TaskSuccessAnimation from "../TaskSuccessAnimation";
import clickSound from "../assets/sounds/click_puzzmon.mp3";
import { type MonarchTaskProps } from "../monarch_tasks_defs";
import { checkAnswerImpl, wordsInQuote } from "./data";

// Hard-coded positions and sizes for puzzmon (as percentage of background)
// Positions are in format: { x: percentage, y: percentage, width: percentage }
// x and y represent the center point of the puzzmon
const PUZZMON_POSITIONS = [
  { x: 88, y: 80, width: 10 },
  { x: 7, y: 93, width: 8 },
  { x: 82, y: 56, width: 10 },
  { x: 66, y: 47, width: 10 },
  { x: 95, y: 36, width: 10 },
  { x: 58, y: 83, width: 10 },
  { x: 43, y: 60, width: 13 },
  { x: 51, y: 37.5, width: 13 },
  { x: 40, y: 88, width: 7 },
  { x: 21, y: 49, width: 10 },
  { x: 30.5, y: 66, width: 15 },
  { x: 6, y: 55, width: 10 },
];

function ElderDriftsTask({
  returnToArchive,
  puzzmonData,
  backgroundImageSrc,
  teamState,
  taskSlug,
}: MonarchTaskProps) {
  const guesses = useRef<string[]>([]);
  const [selectedWord, setSelectedWord] = useState<string>();
  const [visibleSpeechBubble, setVisibleSpeechBubble] = useState<number | null>(
    null,
  );
  const [showWinAnimation, setShowWinAnimation] = useState(false);
  const currentAudioRef = useRef<HTMLAudioElement | null>(null);
  const words = useMemo(() => wordsInQuote(), []);

  const globalVolume = useGlobalVolume();
  const hasTeamSubmitted = !!teamState?.puzzles[taskSlug ?? ""]?.solved;

  const currentPuzzmonData = useMemo(() => {
    if (!puzzmonData) {
      return undefined;
    }

    // This is a hack to be able to substitute this task for a different zone.
    // We put the same Puzzmon in 12 times :)
    if (puzzmonData.length < PUZZMON_POSITIONS.length) {
      return [...new Array(PUZZMON_POSITIONS.length).keys()].map((_, i) => {
        if (!puzzmonData.length) return null;
        const idx = i % puzzmonData.length;
        return puzzmonData[idx] ?? null;
      });
    }

    return puzzmonData;
  }, [puzzmonData]);

  const clickWord = useCallback(
    async (word: string) => {
      // Cancel any currently playing audio
      if (currentAudioRef.current) {
        currentAudioRef.current.pause();
        currentAudioRef.current.currentTime = 0;
      }

      // Play click sound
      const audio = new Audio(clickSound);
      audio.volume = globalVolume;
      currentAudioRef.current = audio;
      void audio.play().catch(() => {
        // Ignore audio play errors (e.g., if user hasn't interacted with page yet)
      });

      // Show speech bubble - get the Puzzmon index to use hard-coded position
      const puzzmonIndex = words?.indexOf(word) ?? -1;

      setSelectedWord(word);
      if (puzzmonIndex !== -1) {
        setVisibleSpeechBubble(puzzmonIndex);
      } else {
        setVisibleSpeechBubble(null);
      }

      // Add to guesses and check answer
      guesses.current.push(word);
      // Truncate just to prevent crazy edge cases, but use 50 to avoid revealing anything
      // about the lengths of the quotes.
      if (guesses.current.length > 50) {
        guesses.current = guesses.current.slice(-50);
      }

      const requestBody = JSON.stringify({
        guesses: guesses.current,
      });
      const isCorrect = checkAnswerImpl(guesses.current);
      if (!isCorrect) {
        return;
      }

      if (IS_STATIC_SITE) {
        const slug = taskSlug ?? "monarch_elder_drifts_task";
        markTaskSolved(slug);
        setShowWinAnimation(true);
        setSelectedWord(undefined);
        setTimeout(() => {
          setShowWinAnimation(false);
        }, 2000);
        return;
      }

      // If the user has clicked the correct sequence of words then we submit it.
      const apiClient = newClient(apiUrl(), undefined);
      const response = await apiClient.submitGuess({
        body: {
          guess: requestBody,
        },
        params: { slug: "monarch_elder_drifts_task" },
      });
      if (response.status === 200) {
        const solved = response.body.guesses.some(
          (guess) => guess.status === "correct",
        );
        if (solved) {
          setShowWinAnimation(true);
          setSelectedWord(undefined);
          // Hide animation after 2 seconds
          setTimeout(() => {
            setShowWinAnimation(false);
          }, 2000);
        }
      }
    },
    [globalVolume, taskSlug, words],
  );

  const handleContainerClick = (event: React.MouseEvent<HTMLDivElement>) => {
    // Only hide if clicking on the container itself, not on Puzzmon or speech bubbles
    if (event.target === event.currentTarget) {
      setSelectedWord(undefined);
      setVisibleSpeechBubble(null);
    }
  };

  return (
    <MonarchTaskWrapper
      returnToArchive={returnToArchive}
      taskClassName="md:hidden lg:flex"
      warningClassName="md:flex lg:hidden"
    >
      <div className="relative w-full h-full flex flex-col items-center justify-center gap-2 lg:gap-4 mt-auto overflow-x-auto overflow-y-hidden">
        <BackToArchiveButton
          onClick={returnToArchive}
          className="absolute top-4 left-6 z-50"
        />

        {/* Solved message */}
        <TaskSolvedMessage
          teamState={teamState}
          taskSlug={taskSlug}
          className="mb-2"
        />

        {/* Main game area */}
        <div
          className={cn(
            "relative mb-4 max-w-full max-h-full min-h-0 aspect-[3/2]",
            !hasTeamSubmitted && "mt-12 md:mt-20",
          )}
        >
          {/* Background image */}
          {backgroundImageSrc && (
            <img
              className="w-full h-full object-cover"
              src={backgroundImageSrc}
              alt=""
              aria-hidden="true"
            />
          )}

          {/* Puzzmon positioned at fixed locations */}
          {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */}
          <div className="absolute inset-0" onClick={handleContainerClick}>
            {words?.map((word, index) => {
              const position = PUZZMON_POSITIONS[index] || {
                x: 50,
                y: 50,
                width: 0,
              };
              const width = position.width;

              return (
                <div
                  key={word}
                  className="absolute -translate-x-1/2 -translate-y-1/2"
                  style={{
                    left: `${position.x}%`,
                    top: `${position.y}%`,
                    width: `${width}%`,
                    aspectRatio: "7/5",
                  }}
                >
                  {/* Speech bubble */}
                  {word === selectedWord && visibleSpeechBubble === index && (
                    <div className="absolute left-1/2 bottom-full -translate-x-1/2 -translate-y-2 bg-white rounded-[100%] text-center min-w-16 py-4 px-3 shadow-lg z-10">
                      <div className="text-sm font-medium text-gray-800">
                        {selectedWord}
                      </div>
                      {/* Speech bubble tail */}
                      <div className="absolute top-full left-1/2 -translate-x-1/2 -translate-y-px w-0 h-0 border-l-[6px] border-r-[6px] border-t-[10px] border-l-transparent border-r-transparent border-t-white" />
                    </div>
                  )}

                  {/* Puzzmon! */}
                  <button
                    onClick={() => {
                      void clickWord(word);
                    }}
                    className="relative w-full h-full cursor-pointer transform-gpu hover:drop-shadow-[0_0_16px_rgba(255,255,255,0.6)] select-none focus-visible:outline-monarch-dark"
                    aria-label={`Click ${word}`}
                  >
                    <img
                      src={currentPuzzmonData?.[index]?.imageSrc}
                      alt={currentPuzzmonData?.[index]?.altText}
                      className="w-full h-full object-contain"
                    />
                  </button>
                </div>
              );
            })}
          </div>

          {/* Winning animation */}
          {showWinAnimation && (
            <TaskSuccessAnimation
              onComplete={() => {
                setShowWinAnimation(false);
              }}
            />
          )}
        </div>
      </div>
    </MonarchTaskWrapper>
  );
}

export default ElderDriftsTask;
