import { type MonsterDetails } from "@hunt/hunt-data/monarch";
import { useGlobalVolume } from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import { Camera, Eye } from "lucide-react";
import { motion } from "motion/react";
import React, { useCallback, useRef, useState } from "react";
import cameraSound from "../../assets/sounds/camera_shutter.mp3";

type PlacedCatProps = {
  cat: MonsterDetails;
  catIndex: number;
  position: { x: number; y: number; width: number };
  hasPhoto: boolean;
  onTakePhoto: (catIndex: number, cat: MonsterDetails) => void;
  onOpenAlbum: () => void;
  onFlash: () => void;
};

export function PlacedCat({
  cat,
  catIndex,
  position,
  hasPhoto,
  onTakePhoto,
  onOpenAlbum,
  onFlash,
}: PlacedCatProps) {
  const [hoveredCat, setHoveredCat] = useState(false);
  const currentAudioRef = useRef<HTMLAudioElement | null>(null);
  const globalVolume = useGlobalVolume();

  const handleClick = useCallback(() => {
    if (hasPhoto) {
      // If cat already has a photo, open the album
      onOpenAlbum();
      return;
    }

    // Cancel any currently playing audio
    if (currentAudioRef.current) {
      currentAudioRef.current.pause();
      currentAudioRef.current.currentTime = 0;
    }

    // Play camera sound
    const cameraAudio = new Audio(cameraSound);
    cameraAudio.volume = globalVolume;
    currentAudioRef.current = cameraAudio;
    void cameraAudio.play().catch(() => {
      // Ignore audio play errors
    });

    // Flash effect
    onFlash();

    // Take photo
    onTakePhoto(catIndex, cat);
  }, [
    cat,
    catIndex,
    hasPhoto,
    globalVolume,
    onTakePhoto,
    onOpenAlbum,
    onFlash,
  ]);

  return (
    <div
      className="absolute z-30"
      style={{
        left: `${position.x * 100}%`,
        top: `${position.y * 100}%`,
        width: `${position.width * 100}%`,
      }}
    >
      <button
        type="button"
        onMouseEnter={() => {
          setHoveredCat(true);
        }}
        onMouseLeave={() => {
          setHoveredCat(false);
        }}
        onClick={handleClick}
        className="relative w-full h-full cursor-pointer focus-visible:outline-monarch-dark"
        aria-label={
          hasPhoto ? `View photo of ${cat.name}` : `Take a photo of ${cat.name}`
        }
      >
        <img
          src={cat.imageSrc}
          alt={cat.name}
          className="w-full h-full object-contain"
        />
        {/* Camera scope appears on hover */}
        {hoveredCat && (
          <>
            <motion.div
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1.1 }}
              exit={{ opacity: 0, scale: 0.8 }}
              transition={{ duration: 0.2 }}
              className={cn(
                "absolute inset-0 border-2 z-10",
                hasPhoto
                  ? "border-[#00FF00] bg-[#00FF00]/20"
                  : "border-black bg-black/20",
              )}
            />
            <motion.div
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.8 }}
              transition={{ duration: 0.2 }}
              className="absolute inset-0 flex items-center justify-center pointer-events-none z-40"
            >
              {hasPhoto ? (
                <Eye size={24} className="text-[#00FF00]" />
              ) : (
                <Camera size={24} className="text-black" />
              )}
            </motion.div>
          </>
        )}
      </button>
    </div>
  );
}
