// Beam propagation logic - handles beam movement, bounds checking, and puzzmon interaction

import type {
  LightBeam,
  PuzzmonBeamInfo,
  PuzzmonTransformResult,
  RGBColor,
} from "./beamTypes";
import { mixColors } from "./beamUtils";
import { applyPuzzmonTransformation } from "./puzzmonTransforms";
import type { GridPuzzmon } from "./types";

export type BeamProcessingOptions = {
  visitedSet: Set<string>;
  processStillLight: boolean;
  shouldSkipStillLightCheck?: (
    puzzmon: GridPuzzmon,
    puzzmonKey: string,
    info: PuzzmonBeamInfo | undefined,
  ) => boolean;
  checkSkipStillLightBeforeTracking?: boolean; // If true, check before tracking incoming beam
};

export type BeamProcessingContext = {
  gridState: (GridPuzzmon | null)[][];
  gridRows: number;
  gridCols: number;
  cellBeams: Map<string, RGBColor[]>;
  puzzmonBeams: Map<string, PuzzmonBeamInfo>;
  targetBeams: Map<string, RGBColor[]>;
  stillLightMap: Map<string, RGBColor[]>;
  isTargetPosition: (row: number, col: number) => boolean;
};

/**
 * Processes a single beam through the grid
 * Handles common logic: movement, bounds checking, target detection, puzzmon interaction
 * Returns an array of beams to add to the queue (empty if beam should stop)
 */
export function processBeam(
  beam: LightBeam,
  options: BeamProcessingOptions,
  context: BeamProcessingContext,
): LightBeam[] {
  const {
    gridState,
    gridRows,
    gridCols,
    cellBeams,
    puzzmonBeams,
    targetBeams,
    stillLightMap,
    isTargetPosition,
  } = context;

  const stateKey = `${beam.row}-${beam.col}-${beam.direction}-${beam.color.r.toFixed(2)}-${beam.color.g.toFixed(2)}-${beam.color.b.toFixed(2)}`;

  // Prevent infinite loops
  if (options.visitedSet.has(stateKey)) {
    return [];
  }
  options.visitedSet.add(stateKey);

  // Move beam forward to next cell
  let nextRow = beam.row;
  let nextCol = beam.col;

  switch (beam.direction) {
    case "down":
      nextRow += 1;
      break;
    case "up":
      nextRow -= 1;
      break;
    case "right":
      nextCol += 1;
      break;
    case "left":
      nextCol -= 1;
      break;
  }

  // Check bounds - if beam exits grid, stop
  if (
    nextRow < 0 ||
    nextRow >= gridRows ||
    nextCol < 0 ||
    nextCol >= gridCols
  ) {
    // Still record beam at current cell if it's valid and no puzzmon/target
    if (
      beam.row >= 0 &&
      beam.row < gridRows &&
      beam.col >= 0 &&
      beam.col < gridCols
    ) {
      const hasPuzzmon = gridState[beam.row]?.[beam.col] !== null;
      const isTarget = isTargetPosition(beam.row, beam.col);
      if (!hasPuzzmon && !isTarget) {
        const cellKey = `${beam.row}-${beam.col}-${beam.direction}`;
        if (!cellBeams.has(cellKey)) {
          cellBeams.set(cellKey, []);
        }
        const beamsAtCell = cellBeams.get(cellKey);
        if (beamsAtCell) {
          beamsAtCell.push(beam.color);
        }
      }
    }
    return [];
  }

  // Record beam at current cell (if within bounds and no puzzmon/target)
  if (
    beam.row >= 0 &&
    beam.row < gridRows &&
    beam.col >= 0 &&
    beam.col < gridCols
  ) {
    const hasPuzzmon = gridState[beam.row]?.[beam.col] !== null;
    const isTarget = isTargetPosition(beam.row, beam.col);

    if (!hasPuzzmon && !isTarget) {
      // Only record beams in cells without puzzmon or target
      const cellKey = `${beam.row}-${beam.col}-${beam.direction}`;
      if (!cellBeams.has(cellKey)) {
        cellBeams.set(cellKey, []);
      }
      const beamsAtCell = cellBeams.get(cellKey);
      if (beamsAtCell) {
        beamsAtCell.push(beam.color);
      }
    }
  }

  // Check if there's a target at the next cell (targets block light)
  const isNextCellTarget = isTargetPosition(nextRow, nextCol);
  if (isNextCellTarget) {
    // Track beam hitting target
    const targetKey = `${nextRow}-${nextCol}`;
    if (!targetBeams.has(targetKey)) {
      targetBeams.set(targetKey, []);
    }
    const targetColors = targetBeams.get(targetKey);
    if (targetColors) {
      targetColors.push(beam.color);
    }
    // Target blocks light - don't continue
    return [];
  }

  // Check if there's a puzzmon at the next cell
  const puzzmon = gridState[nextRow]?.[nextCol];

  if (puzzmon) {
    // Track incoming beam at the puzzmon cell (the cell the beam is entering)
    const puzzmonKey = `${nextRow}-${nextCol}`;
    if (!puzzmonBeams.has(puzzmonKey)) {
      puzzmonBeams.set(puzzmonKey, {
        incoming: new Map(),
        outgoing: new Map(),
      });
    }
    const info = puzzmonBeams.get(puzzmonKey);

    // Check if we should skip still light processing (for still light consumption loop)
    // This check can happen BEFORE or AFTER tracking the incoming beam depending on the loop
    let shouldSkipStillLight = false;
    if (
      options.checkSkipStillLightBeforeTracking &&
      options.shouldSkipStillLightCheck
    ) {
      // Check BEFORE tracking (for second loop)
      shouldSkipStillLight = options.shouldSkipStillLightCheck(
        puzzmon,
        puzzmonKey,
        info,
      );
    }

    // Track incoming beam - the direction tells us which side it's entering from
    if (info) {
      if (!info.incoming.has(beam.direction)) {
        info.incoming.set(beam.direction, []);
      }
      const incomingColors = info.incoming.get(beam.direction);
      if (incomingColors) {
        incomingColors.push(beam.color);
      }
    }

    // Check AFTER tracking if not checked before (for first loop)
    if (
      !options.checkSkipStillLightBeforeTracking &&
      options.shouldSkipStillLightCheck
    ) {
      shouldSkipStillLight = options.shouldSkipStillLightCheck(
        puzzmon,
        puzzmonKey,
        info,
      );
    }

    // Check if this puzzmon should block outputs when multiple inputs are present
    // Bumblebeam (order 1), Knightbulb (order 3), and Comettails (order 8) should block outputs
    // Check AFTER tracking incoming beam so we have the full picture
    const incomingDirections = info ? Array.from(info.incoming.keys()) : [];
    const hasMultipleInputs = incomingDirections.length > 1;
    const shouldBlockMultipleInputs = hasMultipleInputs && puzzmon.order !== 2;

    // If multiple inputs should be blocked, clear outgoing beams and return empty
    // Path cleanup is handled in post-processing in beamCalculation.ts
    if (shouldBlockMultipleInputs) {
      if (info) {
        info.outgoing.clear();
      }
      return [];
    }

    // Apply puzzmon transformation
    // Pass beamInfo so transform can check for multiple inputs
    const transformResult: PuzzmonTransformResult = info
      ? applyPuzzmonTransformation(puzzmon, beam.direction, beam.color, info)
      : { beams: [] };

    // Track outgoing beams
    const outgoingBeams: LightBeam[] = [];
    if (info) {
      for (const transformedBeam of transformResult.beams) {
        if (!info.outgoing.has(transformedBeam.direction)) {
          info.outgoing.set(transformedBeam.direction, []);
        }
        const outgoingColors = info.outgoing.get(transformedBeam.direction);
        if (outgoingColors) {
          outgoingColors.push(transformedBeam.color);
        }

        transformedBeam.row = nextRow;
        transformedBeam.col = nextCol;
        outgoingBeams.push(transformedBeam);
      }

      // Process still light positions from transform
      if (options.processStillLight && transformResult.stillLightPositions) {
        if (shouldSkipStillLight) {
          // Skip creating still light - this puzzmon has multiple sources
          return outgoingBeams;
        }

        // Check if this puzzmon should block still light when multiple inputs are present
        // Glimmerpom (order 6) and Prismoidia (order 7) should block still light with multiple inputs
        const incomingDirections = info ? Array.from(info.incoming.keys()) : [];
        const hasMultipleInputs = incomingDirections.length > 1;
        const shouldBlockStillLight =
          hasMultipleInputs && (puzzmon.order === 6 || puzzmon.order === 7);

        if (shouldBlockStillLight) {
          // Don't create still light if multiple inputs are detected
          return outgoingBeams;
        }

        // For puzzmon that disperse still light, we need to mix all incoming beam colors together
        // Collect all incoming beam colors from all directions
        const allIncomingColors: RGBColor[] = [];
        if (info) {
          for (const directionColors of info.incoming.values()) {
            allIncomingColors.push(...directionColors);
          }
        }
        // Mix all incoming colors together
        // This ensures that if red and blue beams intersect, we get magenta
        const mixedIncomingColor =
          allIncomingColors.length > 0
            ? mixColors(allIncomingColors)
            : beam.color; // Fallback to current beam color if no incoming colors

        for (const pos of transformResult.stillLightPositions) {
          const targetRow = nextRow + pos.rowOffset;
          const targetCol = nextCol + pos.colOffset;

          // Check bounds
          if (
            targetRow >= 0 &&
            targetRow < gridRows &&
            targetCol >= 0 &&
            targetCol < gridCols
          ) {
            // Allow still light on cells that can accept still light
            // Still light can be placed on empty cells, targets, or puzzmon that can consume still light
            const puzzmonAtTarget = gridState[targetRow]?.[targetCol];
            const isTarget = isTargetPosition(targetRow, targetCol);

            // Check if the puzzmon at target can consume still light by checking its transform
            let canTargetConsumeStillLight = false;
            if (puzzmonAtTarget) {
              // Mistermoon (order 9), Incandabra (order 5), and Lanternbot (order 4) can consume still light
              // even though their transforms don't return beams or still light positions
              // Their still light consumption is handled in processStillLightConsumption
              if (
                puzzmonAtTarget.order === 9 ||
                puzzmonAtTarget.order === 5 ||
                puzzmonAtTarget.order === 4
              ) {
                canTargetConsumeStillLight = true;
              } else {
                const targetKey = `${targetRow}-${targetCol}`;
                const targetBeamInfo = puzzmonBeams.get(targetKey) || {
                  incoming: new Map(),
                  outgoing: new Map(),
                };
                // Use the mixed incoming color for checking
                const targetStillLightColor = pos.color ?? mixedIncomingColor;
                const targetTransformResult = applyPuzzmonTransformation(
                  puzzmonAtTarget,
                  "down", // Dummy direction
                  targetStillLightColor,
                  targetBeamInfo,
                );
                // If it returns still light positions or beams, it can consume still light
                canTargetConsumeStillLight =
                  targetTransformResult.stillLightPositions !== undefined ||
                  targetTransformResult.beams.length > 0;
              }
            }

            const canPlaceStillLight =
              isTarget || !puzzmonAtTarget || canTargetConsumeStillLight;

            if (canPlaceStillLight) {
              const stillLightKey = `${targetRow}-${targetCol}`;
              // Use the mixed incoming color (all incoming beams combined) when there are multiple inputs
              // Otherwise use the color from the position (which may be specified) or the beam color
              // This ensures red + blue = magenta when multiple beams hit a still light disperser
              const stillLightColor =
                allIncomingColors.length > 1
                  ? mixedIncomingColor
                  : (pos.color ?? beam.color);

              // Skip creating still light if the color is effectively black (all components < 0.1)
              // This handles cases where Prismoidia extracts components that aren't present
              if (
                stillLightColor.r < 0.1 &&
                stillLightColor.g < 0.1 &&
                stillLightColor.b < 0.1
              ) {
                continue; // Skip - color is effectively black
              }

              if (!stillLightMap.has(stillLightKey)) {
                stillLightMap.set(stillLightKey, []);
              }
              const stillLightColors = stillLightMap.get(stillLightKey);
              if (stillLightColors) {
                stillLightColors.push(stillLightColor);
              }
            }
          }
        }
      }
    } else {
      // If info doesn't exist, still process beams
      for (const transformedBeam of transformResult.beams) {
        transformedBeam.row = nextRow;
        transformedBeam.col = nextCol;
        outgoingBeams.push(transformedBeam);
      }
    }

    return outgoingBeams;
  } else {
    // No puzzmon - beam continues straight
    const nextBeam: LightBeam = {
      row: nextRow,
      col: nextCol,
      direction: beam.direction,
      color: beam.color,
    };
    return [nextBeam];
  }
}
