import React from "react";
import { CLOCK_POSITION } from "../constants";
import { formatTime } from "../utils";

type ClockDisplayProps = {
  currentTime: Date;
};

export function ClockDisplay({ currentTime }: ClockDisplayProps) {
  const displayTime = formatTime(currentTime);

  return (
    <div
      className="absolute z-20 pointer-events-auto"
      style={{
        left: `${CLOCK_POSITION.x * 100}%`,
        top: `${CLOCK_POSITION.y * 100}%`,
        width: `${CLOCK_POSITION.width * 100}%`,
        height: `${CLOCK_POSITION.height * 100}%`,
      }}
    >
      <div className="flex h-full items-center justify-center text-black text-center font-mono text-base lg:text-xl xl:text-2xl">
        {displayTime}
      </div>
    </div>
  );
}
