import { type TeamHuntState } from "@hunt/public-client";
import { cn } from "@hunt/styled-ui";
import React from "react";

type TaskSolvedMessageProps = {
  teamState?: TeamHuntState;
  taskSlug?: string;
  className?: string;
};

export default function TaskSolvedMessage({
  teamState,
  taskSlug,
  className = "",
}: TaskSolvedMessageProps) {
  const isSolved = taskSlug && teamState?.puzzles[taskSlug]?.solved;

  if (!isSolved) {
    return null;
  }

  return (
    <div
      className={cn(
        "px-2 lg:px-4 py-2 bg-green-100 border border-green-400 text-green-800 text-xs lg:text-base rounded-lg text-center mx-32 mt-4",
        className,
      )}
    >
      This task was completed, but you can still play for fun.
    </div>
  );
}
