import { cn } from "@hunt/styled-ui";
import React, { useEffect } from "react";
import { CoffeeBase, CoffeeSpice, CoffeeSyrup } from "./constants";

const MENU_BASE_STYLE =
  "w-[11%] absolute z-30 text-black font-[Caveat] text-sm xl:text-base";
const LIST_ELEMENT_STYLE =
  "whitespace-nowrap overflow-hidden text-ellipsis leading-3 xl:leading-4 list-decimal list-inside box-border border rounded-full border-transparent";
const SELECTED_STYLE = "border-black";

type MenuProps = {
  selectedBase: CoffeeBase | undefined;
  selectedSyrup: CoffeeSyrup | undefined;
  selectedSpice: CoffeeSpice | undefined;
  setSelectedBase: (base: CoffeeBase) => void;
  setSelectedSyrup: (base: CoffeeSyrup) => void;
  setSelectedSpice: (base: CoffeeSpice) => void;
};

function Menu({
  selectedBase,
  selectedSyrup,
  selectedSpice,
  setSelectedBase,
  setSelectedSyrup,
  setSelectedSpice,
}: MenuProps) {
  const bases = Object.keys(CoffeeBase).filter((key) =>
    Number.isNaN(Number(key)),
  ) as CoffeeBase[];
  const syrups = Object.keys(CoffeeSyrup).filter((key) =>
    Number.isNaN(Number(key)),
  ) as CoffeeSyrup[];
  const spices = Object.keys(CoffeeSpice).filter((key) =>
    Number.isNaN(Number(key)),
  ) as CoffeeSpice[];

  useEffect(() => {
    const keyPress = (ev: KeyboardEvent) => {
      if (
        ev.key === "1" ||
        ev.key === "2" ||
        ev.key === "3" ||
        ev.key === "4"
      ) {
        if (!selectedBase) {
          setSelectedBase(bases[Number(ev.key) - 1]);
        } else if (!selectedSyrup) {
          setSelectedSyrup(syrups[Number(ev.key) - 1]);
        } else if (!selectedSpice) {
          setSelectedSpice(spices[Number(ev.key) - 1]);
        }
      }
    };

    window.addEventListener("keypress", keyPress);

    return () => {
      window.removeEventListener("keypress", keyPress);
    };
  }, [
    bases,
    selectedBase,
    selectedSpice,
    selectedSyrup,
    setSelectedBase,
    setSelectedSpice,
    setSelectedSyrup,
    spices,
    syrups,
  ]);

  return (
    <>
      <div
        className={cn(
          MENU_BASE_STYLE,
          "h-[19%] top-[31%] left-[67.3%] -rotate-[8deg]",
        )}
      >
        <div className="text-base xl:text-lg">Base:</div>
        <ol>
          {bases.map((key) => (
            <li
              key={key}
              className={cn(
                LIST_ELEMENT_STYLE,
                selectedBase === key && SELECTED_STYLE,
              )}
            >
              {key}
            </li>
          ))}
        </ol>
      </div>
      <div
        className={cn(
          MENU_BASE_STYLE,
          "h-[17%] top-[52%] left-[69.5%] rotate-1",
        )}
      >
        <div className="text-base xl:text-lg">Syrup:</div>
        <ol>
          {syrups.map((key) => (
            <li
              key={key}
              className={cn(
                LIST_ELEMENT_STYLE,
                selectedSyrup === key && SELECTED_STYLE,
              )}
            >
              {key}
            </li>
          ))}
        </ol>
      </div>
      <div
        className={cn(
          MENU_BASE_STYLE,
          "h-[16%] top-[70.2%] left-[66.5%] -rotate-3",
        )}
      >
        <div className="text-base xl:text-lg">Spice:</div>
        <ol>
          {spices.map((key) => (
            <li
              key={key}
              className={cn(
                LIST_ELEMENT_STYLE,
                selectedSpice === key && SELECTED_STYLE,
              )}
            >
              {key}
            </li>
          ))}
        </ol>
      </div>
    </>
  );
}

export default Menu;
