import {
  type MonsterDetails,
  type MonarchData,
  ALL_ZONES,
  zoneToSlug,
} from "@hunt/hunt-data/monarch";
import { useCallback, useMemo, useState } from "react";
import { deleteQueryParam, updateQueryParam } from "./lib/url";
import { MONARCH_QUERY_KEYS } from "./useMonarchQueryParams";

/**
 * Converts a zone slug to a zone name and attempts to match it to an active zone.
 * If the zone is not found in the active zones, it returns the default "All zones" selection.
 */
const zoneSlugToSelectedZone = (
  zone: string | undefined,
  activeZones: string[],
): string => {
  if (!zone) {
    return ALL_ZONES;
  }

  const zoneWithSpace = zone.replace("_", " ");

  const zoneString =
    zoneWithSpace[0].toUpperCase() + zoneWithSpace.substring(1);
  if (activeZones.includes(zoneString)) {
    return zoneString;
  }

  return ALL_ZONES;
};

function useMonarchData(
  initialSearchTerm?: string,
  initialZoneFilter?: string,
  monarchData?: MonarchData,
) {
  const [searchTerm, setSearchTerm] = useState(initialSearchTerm ?? "");
  const [selectedZone, setSelectedZone] = useState<string>(
    zoneSlugToSelectedZone(initialZoneFilter, Object.keys(monarchData ?? {})),
  );

  // Use server-loaded data if available, otherwise fall back to empty array.
  const allMonsterData: MonsterDetails[] = useMemo(() => {
    if (!monarchData) return [];

    // Flatten all solved puzzmon from all zones.
    return Object.values(monarchData).flatMap(
      (zoneData) => zoneData.solvedPuzzmon,
    );
  }, [monarchData]);

  const handleSearchInput = useCallback((newSearchTerm: string) => {
    setSearchTerm(newSearchTerm);
    if (newSearchTerm) {
      updateQueryParam(MONARCH_QUERY_KEYS.SEARCH, newSearchTerm, true);
    } else {
      deleteQueryParam(MONARCH_QUERY_KEYS.SEARCH, true);
    }
  }, []);

  const handleZoneUpdate = useCallback((newZone: string) => {
    setSelectedZone(newZone);
    if (newZone !== ALL_ZONES) {
      updateQueryParam(MONARCH_QUERY_KEYS.ZONE, zoneToSlug(newZone), true);
    } else {
      deleteQueryParam(MONARCH_QUERY_KEYS.ZONE, true);
    }
  }, []);

  const filteredMonsterData = useMemo(() => {
    return allMonsterData.filter(({ name, zone }) => {
      if (selectedZone !== ALL_ZONES && selectedZone !== (zone as string)) {
        return false;
      }

      return name.toLowerCase().includes(searchTerm.toLowerCase());
    });
  }, [allMonsterData, searchTerm, selectedZone]);

  const numMonstersBefriended = useMemo(() => {
    return filteredMonsterData.length;
  }, [filteredMonsterData]);

  const displayedMonsterData = useMemo(() => {
    // Groups by zone. Each puzzmon will be in exactly one zone group.
    const zoneGroups: Record<string, MonsterDetails[]> = {};

    filteredMonsterData.forEach((monster) => {
      const zone = monster.zone || "Unknown Zone";
      if (!zoneGroups[zone]) {
        zoneGroups[zone] = [];
      }
      zoneGroups[zone].push(monster);
    });

    // If we are searching by name, then we want to return the zone groups as is.
    if (searchTerm) return zoneGroups;

    // Otherwise, we want to make sure we are including empty zones so that the undiscovered cards are shown.
    // If the user has selected a zone filter, then we only want that zone to be included.
    // Otherwise, we add all zones that have not been added yet.
    if (selectedZone !== ALL_ZONES) {
      if (!(selectedZone in zoneGroups)) {
        zoneGroups[selectedZone] = [];
      }
    } else {
      Object.keys(monarchData ?? {}).forEach((zone) => {
        if (!(zone in zoneGroups)) {
          zoneGroups[zone] = [];
        }
      });
    }

    return zoneGroups;
  }, [filteredMonsterData, monarchData, searchTerm, selectedZone]);

  const zoneDetails = useMemo(() => {
    if (!monarchData) return {};

    return Object.fromEntries(
      Object.entries(monarchData).map(([zone, zoneData]) => [
        zone,
        { count: zoneData.count, taskPrompt: zoneData.taskPrompt },
      ]),
    );
  }, [monarchData]);

  return {
    allMonsterData,
    displayedMonsterData,
    numMonstersBefriended,
    searchTerm,
    handleSearchInput,
    selectedZone,
    handleZoneUpdate,
    zoneDetails,
  };
}

export default useMonarchData;
