import { MAX_TOYS } from "./constants";
import { KITTY_CITY_TASK_DATA_KEY, type StorageData } from "./types";

// LocalStorage helpers
export const getStoredData = (): StorageData => {
  if (typeof window === "undefined")
    return {
      placedItems: [],
      photos: [],
      hasSubmitted: false,
    };
  try {
    const stored = localStorage.getItem(KITTY_CITY_TASK_DATA_KEY);
    if (!stored)
      return {
        placedItems: [],
        photos: [],
        hasSubmitted: false,
      };
    const parsed = JSON.parse(stored) as StorageData;
    // Limit placedItems to first MAX_TOYS to prevent localStorage tampering
    const limitedPlacedItems =
      parsed.placedItems && Array.isArray(parsed.placedItems)
        ? parsed.placedItems.slice(0, MAX_TOYS)
        : [];
    return {
      placedItems: limitedPlacedItems,
      photos: parsed.photos ?? [],
      hasSubmitted: parsed.hasSubmitted ?? false,
    };
  } catch {
    return {
      placedItems: [],
      photos: [],
      hasSubmitted: false,
    };
  }
};

export const saveStoredData = (data: StorageData): void => {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(KITTY_CITY_TASK_DATA_KEY, JSON.stringify(data));
  } catch (error) {
    console.error("Failed to save kitty city task data:", error);
  }
};
