import { MONSTER_ZONES, type MonsterDetails } from "@hunt/hunt-data/monarch";
import { useEffect, useMemo, useState } from "react";
import { TOY_POSITIONS } from "./constants";
import { getStoredData, saveStoredData } from "./storage";
import type { Photo, PlacedItem } from "./types";
import { digitInTime, formatTime, getDigitFromToy } from "./utils";

export function useKittyCityState(puzzmonData?: MonsterDetails[]) {
  const [placedItems, setPlacedItems] = useState<PlacedItem[]>([]);
  const [initialPlacedItems, setInitialPlacedItems] = useState<PlacedItem[]>(
    [],
  );
  const [currentTime, setCurrentTime] = useState<Date>(new Date());
  const [photos, setPhotos] = useState<Photo[]>([]);
  const [hasSubmitted, setHasSubmitted] = useState(false);

  // Load data from localStorage on mount
  useEffect(() => {
    const stored = getStoredData();
    setPlacedItems(stored.placedItems);
    setInitialPlacedItems(stored.placedItems);
    setPhotos(stored.photos);
    setHasSubmitted(stored.hasSubmitted);
    setCurrentTime(new Date());
  }, []);

  // Get Kitty City cats sorted alphabetically by name
  const kittyCityCats = useMemo(() => {
    if (!puzzmonData) return [];
    const cats = puzzmonData.filter(
      (p) => p.zone === MONSTER_ZONES.KITTY_CITY,
    ) as MonsterDetails[];
    return cats.sort((a, b) => a.name.localeCompare(b.name));
  }, [puzzmonData]);

  // Get toys in the order they appear in TOY_POSITIONS
  const toysInOrder = useMemo(() => {
    return Object.keys(TOY_POSITIONS);
  }, []);

  // Map toy to cat index (based on alphabetical order of cats)
  const getCatIndexForToy = useMemo(() => {
    return (toy: string): number | null => {
      const toyIndex = toysInOrder.indexOf(toy);
      if (toyIndex === -1) return null;
      return toyIndex;
    };
  }, [toysInOrder]);

  // Determine which cats should be visible based on current time
  const visibleCats = useMemo(() => {
    if (initialPlacedItems.length === 0) return new Set<number>();

    const timeString = formatTime(currentTime);
    const visible = new Set<number>();

    initialPlacedItems.forEach((item) => {
      const digit = getDigitFromToy(item.toy);
      if (digit !== null && digitInTime(digit, timeString)) {
        const catIndex = getCatIndexForToy(item.toy);
        if (catIndex !== null) {
          visible.add(catIndex);
        }
      }
    });

    return visible;
  }, [currentTime, initialPlacedItems, getCatIndexForToy]);

  // Update placed items and save to storage
  const updatePlacedItems = (newItems: PlacedItem[]) => {
    setPlacedItems(newItems);
    const currentData = getStoredData();
    saveStoredData({
      placedItems: newItems,
      photos: currentData.photos,
      hasSubmitted: currentData.hasSubmitted,
    });
  };

  // Update photos and save to storage
  const updatePhotos = (newPhotos: Photo[]) => {
    setPhotos(newPhotos);
    const currentData = getStoredData();
    saveStoredData({
      placedItems: currentData.placedItems,
      photos: newPhotos,
      hasSubmitted: currentData.hasSubmitted,
    });
  };

  // Mark as submitted
  const markAsSubmitted = () => {
    setHasSubmitted(true);
    const data = getStoredData();
    data.hasSubmitted = true;
    saveStoredData(data);
  };

  return {
    placedItems,
    initialPlacedItems,
    currentTime,
    photos,
    hasSubmitted,
    kittyCityCats,
    toysInOrder,
    visibleCats,
    getCatIndexForToy,
    updatePlacedItems,
    updatePhotos,
    markAsSubmitted,
  };
}
