import { cn } from "@hunt/styled-ui";
import React, { useEffect, useRef } from "react";
import {
  PATIENCE_DECREASE_INTERVAL,
  PATIENCE_HIGH_THRESHOLD,
  PATIENCE_LOW_THRESHOLD,
} from "./constants";

type PatientMeterProps = {
  value: number; // 0-100
  onChange: (fn: (value: number) => number) => void;
  className?: string;
  decreaseRateRef: React.MutableRefObject<number>;
};

export default function PatienceMeter({
  value,
  onChange,
  className,
  decreaseRateRef,
}: PatientMeterProps) {
  const intervalRef = useRef<NodeJS.Timeout>();
  const lastInterval = useRef<number>(0);

  // Decrease meter over time
  useEffect(() => {
    intervalRef.current = setInterval(() => {
      if (Date.now() - lastInterval.current >= PATIENCE_DECREASE_INTERVAL) {
        onChange((prev: number) =>
          Math.min(100, Math.max(0, prev - decreaseRateRef.current)),
        );
        lastInterval.current = Date.now();
      }
    }, PATIENCE_DECREASE_INTERVAL);

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [decreaseRateRef, onChange]);

  return (
    <div className={cn("relative", className)}>
      {/* Main content wrapper */}
      <div className="w-64 flex flex-col gap-2">
        {/* Meter container */}
        <div className="relative w-full h-8 bg-gray-800 border-2 border-black rounded-md overflow-hidden">
          {/* Current value bar */}
          <div
            className={cn(
              "h-full transition-all duration-200 ease-out",
              value > PATIENCE_HIGH_THRESHOLD
                ? "bg-green-400"
                : value > PATIENCE_LOW_THRESHOLD
                  ? "bg-yellow-400"
                  : "bg-red-400",
            )}
            style={{ width: `${value}%` }}
          />
        </div>
      </div>
    </div>
  );
}
