import {
  ARC_DURATION_SECONDS,
  BASE_MEANDER_AMPLITUDE,
  BASE_MEANDER_FREQUENCY,
  DECORATION_SPOTS,
  POP_OUT_DURATION,
} from "./constants";
import { type Fish } from "./types";

// Round 2 is much harder than round 1, so everything is slowed by some factor compared to its pace in round 1.
const ROUND_2_MULTIPLIER = 0.75;

export type FishUpdateResult = {
  x: number;
  y: number;
  rotation: number;
  isMovingBack?: boolean;
};

export function updateFishPosition(
  fish: Fish,
  timeSinceSpawn: number,
  deltaTime: number,
  speedPercentPerSecond: number,
  roundNumber: number,
): FishUpdateResult {
  const roundMultiplier = getRoundMultiplier(roundNumber);
  let newX: number;
  let newY: number;
  let newRotation = fish.rotation || 0;
  let isMovingBack: boolean | undefined;

  switch (fish.behavior) {
    case "straight": {
      const direction = fish.direction ?? 1;
      // Slow down straight fish by 20%
      newX =
        fish.x -
        direction * speedPercentPerSecond * roundMultiplier * deltaTime;
      // Add simple meandering for straight behavior
      const meander =
        Math.sin(
          (newX / 100) *
            BASE_MEANDER_FREQUENCY *
            fish.meanderFrequency *
            Math.PI *
            2 +
            fish.meanderPhase,
        ) *
        BASE_MEANDER_AMPLITUDE *
        fish.meanderAmplitude;
      newY = fish.baseY + meander;
      break;
    }

    case "rotated_straight": {
      const direction = fish.direction ?? 1;
      newX =
        fish.x -
        direction * speedPercentPerSecond * roundMultiplier * deltaTime;
      // Add simple meandering
      const meander =
        Math.sin(
          (newX / 100) *
            BASE_MEANDER_FREQUENCY *
            fish.meanderFrequency *
            Math.PI *
            2 +
            fish.meanderPhase,
        ) *
        BASE_MEANDER_AMPLITUDE *
        fish.meanderAmplitude;
      newY = fish.baseY + meander;
      // Keep rotation from config
      break;
    }

    case "arc": {
      const direction = fish.direction ?? 1;
      const angle =
        Math.min(
          timeSinceSpawn / ((ARC_DURATION_SECONDS * 1) / roundMultiplier),
          1,
        ) * Math.PI;
      newX = 50 + 40 * Math.cos(angle);
      newY = 100 - 40 * Math.sin(angle);
      newRotation = (180 - (Math.PI / 2 + angle) * (180 / Math.PI) + 30) * 0.7;
      if (direction === -1) {
        newX = 100 - newX;
      }
      break;
    }

    case "spiral": {
      const spiralDuration = 4 / roundMultiplier;
      const progress = Math.min(timeSinceSpawn / spiralDuration, 1);

      // Spiral motion: starts at bottom center, spirals up then back down
      const phase = (fish.spiralPhase || 0) - progress * Math.PI * 3; // 4 full rotations (negative for clockwise)
      const spiralRadius = 15 * Math.sin(progress * Math.PI); // Expanding then contracting radius
      const spiralHeight = Math.sin(progress * Math.PI) * 30; // Up to 30% height

      newX = 50 + Math.cos(phase) * spiralRadius; // Center at 50%
      newY = fish.baseY - spiralHeight;

      // Rotate to match spiral direction
      newRotation = phase * (180 / Math.PI) + 90; // Convert to degrees and offset
      break;
    }

    case "pop_out": {
      const popOutDuration = POP_OUT_DURATION / roundMultiplier;
      const progress = Math.min(timeSinceSpawn / popOutDuration, 1);
      const popOutDistance = 30; // Maximum distance to pop out

      // Pop out motion: move out quickly, stay visible for typing, then move back
      let popProgress;
      if (progress < 0.25) {
        // Moving out (0 to 0.25 becomes 0 to 1)
        popProgress = progress * 4;
        isMovingBack = false;
      } else if (progress < 0.75) {
        // Staying visible (0.25 to 0.75 - 3 seconds for typing)
        popProgress = 1;
        isMovingBack = false;
      } else {
        // Moving back in (0.75 to 1 becomes 1 to 0)
        popProgress = 4 - progress * 4;
        isMovingBack = true;
      }

      // Calculate position based on side and progress
      const baseX =
        fish.side === "left"
          ? Math.min(...[5, 15, 12, 25]) - 8 // Leftmost decoration position minus offset
          : Math.max(...[92, 80, 65]) + 8; // Rightmost decoration position plus offset

      if (fish.side === "left") {
        newX = baseX + popProgress * popOutDistance; // Start hidden, move right (out)
      } else {
        newX = baseX - popProgress * popOutDistance; // Start hidden, move left (out)
      }
      newY = fish.baseY; // Keep same Y position
      break;
    }

    default:
      newX = fish.x;
      newY = fish.y;
      isMovingBack = undefined;
      break;
  }

  return { x: newX, y: newY, rotation: newRotation, isMovingBack };
}

export function shouldRemoveFish(
  fish: Fish,
  timeSinceSpawn: number,
  roundNumber: number,
): boolean {
  const roundMultiplier = getRoundMultiplier(roundNumber);
  switch (fish.behavior) {
    case "straight":
    case "rotated_straight": {
      const direction = fish.direction ?? 1;
      return direction === 1 ? fish.x <= -10 : fish.x >= 110;
    }
    case "arc":
      return (
        timeSinceSpawn > 1 &&
        (fish.direction === 1 ? fish.x <= 10 : fish.x >= 90)
      );
    case "spiral":
      return timeSinceSpawn > 1 && fish.y >= 100;
    case "pop_out":
      return timeSinceSpawn >= POP_OUT_DURATION / roundMultiplier;
    default:
      return fish.x <= -10 || fish.x >= 110;
  }
}

export function getInitialFishPosition(behavior: string) {
  let baseY: number;
  let x: number;
  let direction = 1; // Default right-to-left

  // Set initial position based on behavior
  switch (behavior) {
    case "straight":
    case "rotated_straight":
      baseY = 20 + Math.random() * 40; // Random vertical position (20-60%)
      direction = Math.random() > 0.5 ? 1 : -1;
      x = direction === 1 ? 110 : -10; // Start off-screen
      break;
    case "arc":
      baseY = 100; // Start at bottom
      direction = Math.random() > 0.5 ? 1 : -1;
      x = direction === 1 ? 90 : 10;
      break;
    case "spiral":
      baseY = 100; // Start at very bottom
      x = 50; // Start in middle
      break;
    case "pop_out": {
      // Position behind rocks/weeds - choose random decoration location
      const spot =
        DECORATION_SPOTS[Math.floor(Math.random() * DECORATION_SPOTS.length)];
      baseY = spot.y;
      x = spot.side === "left" ? spot.x - 8 : spot.x + 8; // Start hidden behind decoration
      direction = spot.side === "left" ? 1 : -1; // 1 = move right (out), -1 = move left (out)
      break;
    }
    default:
      baseY = 50;
      x = 110;
      break;
  }

  return { baseY, x, direction };
}

export function getRoundMultiplier(roundNumber: number) {
  return roundNumber === 1 ? 1 : ROUND_2_MULTIPLIER;
}
