import { newClient } from "@hunt/public-client";
import { cn } from "@hunt/styled-ui";
import { useCallback, useEffect, useRef, useState } from "react";
import apiUrl from "../../../../utils/apiUrl";
import { IS_STATIC_SITE } from "../../../../utils/staticSite";
import { markTaskSolved } from "../../../puzzleSolveLocalState";
import { BackToArchiveButton } from "../../components/MonarchButton";
import { GameOverScreen } from "../GameOverScreen";
import MonarchTaskWrapper from "../MonarchTaskWrapper";
import { StartScreen } from "../StartScreen";
import TaskSolvedMessage from "../TaskSolvedMessage";
import TaskSuccessAnimation from "../TaskSuccessAnimation";
import { type MonarchTaskProps } from "../monarch_tasks_defs";
import GameStats from "./GameStats";
import Menu from "./Menu";
import PatienceMeter from "./PatienceMeter";
import SmallTalkMeter from "./SmallTalkMeter";
import TypewriterDialog from "./TypewriterDialog";
import AwningImage from "./assets/eland_task_awning.png";
import BackgroundImage from "./assets/eland_task_bg.png";
import CounterImage from "./assets/eland_task_counter.png";
import CupImage from "./assets/eland_task_cup.png";
import CupImageFull from "./assets/eland_task_cup_full.png";
import { TARGET_SCORE, TOTAL_CUSTOMERS, TUTORIAL_TEXT } from "./constants";
import useGameFlow, { GameState } from "./useGameFlow";

const SUBMISSION_ERROR =
  "An unexpected error occurred submitting the task. Please try again later.";

function ElandIslandsTask({
  returnToArchive,
  puzzmonData,
  teamState,
  taskSlug,
}: MonarchTaskProps) {
  const [showWinAnimation, setShowWinAnimation] = useState(false);
  const [submissionError, setSubmissionError] = useState<string | undefined>(
    undefined,
  );
  const patienceDecreaseRateRef = useRef<number>(0);

  const welcomeText = "Welcome to ☆*‧₊˚⋅˖ Novabucks ˖⋅˚₊‧*☆!";

  const hasTeamSubmitted = !!teamState?.puzzles[taskSlug ?? ""]?.solved;

  const submitTask = useCallback(async () => {
    if (hasTeamSubmitted) {
      setShowWinAnimation(true);
      setSubmissionError(undefined);
      return;
    }

    if (IS_STATIC_SITE) {
      const slug = taskSlug ?? "monarch_eland_islands_task";
      markTaskSolved(slug);
      setShowWinAnimation(true);
      setSubmissionError(undefined);
      return;
    }

    setSubmissionError("Submitting...");

    try {
      const apiClient = newClient(apiUrl(), undefined);
      const response = await apiClient.submitGuess({
        body: {
          guess: "",
        },
        params: { slug: taskSlug ?? "monarch_eland_islands_task" },
      });

      if (response.status === 200) {
        const solved = response.body.guesses.some(
          (guess) => guess.status === "correct",
        );
        if (solved) {
          setShowWinAnimation(true);
          setSubmissionError(undefined);
        } else {
          setSubmissionError(SUBMISSION_ERROR);
        }
      } else {
        setSubmissionError(SUBMISSION_ERROR);
      }
    } catch (error: unknown) {
      console.error("Failed to submit score:", error);
      setSubmissionError(SUBMISSION_ERROR);
    }
  }, [hasTeamSubmitted, taskSlug]);

  const {
    puzzmon,
    dialogText,
    gameState,
    selectedBase,
    setSelectedBase,
    selectedSyrup,
    setSelectedSyrup,
    selectedSpice,
    setSelectedSpice,
    patienceLevel,
    setPatienceLevel,
    smallTalkLevel,
    setSmallTalkLevel,
    currentScore,
    customersServed,
    patienceDecreaseRate,
    startGame,
    continueFromTutorial,
    reset,
    showBonusPoint,
  } = useGameFlow(puzzmonData ?? [], submitTask);

  const currentScoreRounded = Math.round(currentScore);

  useEffect(() => {
    patienceDecreaseRateRef.current = patienceDecreaseRate;
  }, [patienceDecreaseRate]);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (gameState !== GameState.TUTORIAL) {
        return;
      }

      if (event.key === "Enter") {
        continueFromTutorial();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [continueFromTutorial, gameState]);

  return (
    <MonarchTaskWrapper
      returnToArchive={returnToArchive}
      taskClassName="md:hidden lg:flex"
      warningClassName="md:flex lg:hidden"
    >
      <style>
        {`
          @keyframes fadeUp {
            0% {
              opacity: 0;
              transform: translate(-50%, -50%) translateY(0);
            }
            20% {
              opacity: 1;
              transform: translate(-50%, -50%) translateY(-20px);
            }
            80% {
              opacity: 1;
              transform: translate(-50%, -50%) translateY(-20px);
            }
            100% {
              opacity: 0;
              transform: translate(-50%, -50%) translateY(-40px);
            }
          }
          @keyframes coffee-top-bit {
            /* Start: nothing */
            0%, 56% {
              opacity: 1;
            }

            56.1%, 100% {
              opacity: 0;
            }
          }
          @keyframes coffee-pour {
            /* Start: nothing */
            0% {
              top: calc(56% + 1.5%);
              height: 0%;
            }

            /* Phase 1: grow downward (bottom moves) */
            28% {
              top: calc(56% + 1.5%);
              height: 11.2%;
            }

            /* Phase 2: hold for 500ms */
            56% {
              top: calc(56% + 1.5%);
              height: 11.2%;
            }

            /* Phase 3: top moves down, bottom fixed */
            100% {
              top: calc(56% + 1.5% + 11.2%);
              height: 0%;
            }
          }
          @keyframes cup-after {
            0% {
              opacity: 0;
            }
            70% {
              opacity: 0;
            }
            80% {
              opacity: 1;
            }
            100% {
              opacity: 1;
            }
          }
        `}
      </style>
      <div className="relative w-full h-full flex flex-col justify-end items-center overflow-x-auto overflow-y-hidden">
        <BackToArchiveButton
          onClick={returnToArchive}
          className="absolute top-4 left-6 z-50"
        />

        <div className="flex flex-col items-center gap-2 lg:gap-4 mt-auto w-full h-full">
          {/* Solved message */}
          <TaskSolvedMessage teamState={teamState} taskSlug={taskSlug} />

          {/* Game UI */}
          <div
            className={cn(
              "relative mb-4 max-w-full max-h-full min-h-0 aspect-[3/2] overflow-hidden",
              !hasTeamSubmitted && "mt-12 md:mt-20",
            )}
          >
            {/* Start Screen */}
            {gameState === GameState.START_SCREEN && (
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50 pointer-events-auto w-full max-w-2xl px-4">
                <StartScreen
                  instructions={
                    <div>
                      {welcomeText}
                      <div className="pt-4">
                        The Eland Island Puzzmon love their coffee, but
                        they&apos;re easily distracted. Keep the small talk
                        flowing while you prep their order!
                      </div>
                    </div>
                  }
                  startGame={startGame}
                />
              </div>
            )}

            {/* Tutorial Screen */}
            {gameState === GameState.TUTORIAL && (
              <div className="absolute w-[90%] top-[8%] left-[50%] -translate-x-2/4 z-40 flex flex-col items-center gap-4">
                <TypewriterDialog
                  className="rounded-lg text-base"
                  text={TUTORIAL_TEXT}
                  showEffect={false}
                />
              </div>
            )}

            {/* Game Over Screen */}
            {(gameState === GameState.WON || gameState === GameState.LOST) && (
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-50 pointer-events-auto w-full max-w-2xl px-4">
                <GameOverScreen
                  score={currentScoreRounded}
                  targetScore={TARGET_SCORE}
                  resetGame={reset}
                  submissionError={submissionError}
                  won={gameState === GameState.WON}
                  customMessage={
                    gameState === GameState.WON
                      ? `Congratulations! You served ${customersServed} customers and earned ${currentScoreRounded} points!`
                      : `Game over! You served ${customersServed} customers and earned ${currentScoreRounded} points. Try to reach ${TARGET_SCORE} points!`
                  }
                />
              </div>
            )}

            {[
              GameState.TUTORIAL,
              GameState.ENTERING,
              GameState.ORDERING,
              GameState.POURING,
              GameState.ORDER_INCORRECT,
              GameState.LEAVING_CORRECT,
              GameState.LEAVING_INCORRECT,
              GameState.BETWEEN_CUSTOMERS,
            ].includes(gameState) && (
              <>
                {/* Small Talk Meter */}
                <SmallTalkMeter
                  value={smallTalkLevel}
                  onChange={setSmallTalkLevel}
                  className="absolute bottom-4 left-4 z-50"
                />
                {/* Game Stats */}
                <GameStats
                  currentScore={currentScoreRounded}
                  targetScore={TARGET_SCORE}
                  customersServed={customersServed}
                  totalCustomers={TOTAL_CUSTOMERS}
                  className="absolute bottom-4 right-4 z-50"
                />
                {/* Bonus Point Indicator */}
                {showBonusPoint && (
                  <div className="absolute top-1/2 left-1/2 z-50 pointer-events-none">
                    <div
                      className="bg-gray-900 text-white text-2xl font-bold px-6 py-3 rounded-lg shadow-lg"
                      style={{ animation: "fadeUp 2s ease-out forwards" }}
                    >
                      +1 time bonus!
                    </div>
                  </div>
                )}
                <Menu
                  selectedBase={selectedBase}
                  setSelectedBase={setSelectedBase}
                  selectedSyrup={selectedSyrup}
                  setSelectedSyrup={setSelectedSyrup}
                  selectedSpice={selectedSpice}
                  setSelectedSpice={setSelectedSpice}
                />
                {/* Dialog and Patience Meter wrapper */}
                {gameState !== GameState.ENTERING &&
                  gameState !== GameState.BETWEEN_CUSTOMERS &&
                  gameState !== GameState.TUTORIAL && (
                    <div className="absolute w-[90%] top-[8%] left-[50%] -translate-x-2/4 z-30 flex flex-col items-center gap-2">
                      <TypewriterDialog text={dialogText} />
                      {gameState !== GameState.LEAVING_CORRECT &&
                        gameState !== GameState.LEAVING_INCORRECT && (
                          <PatienceMeter
                            value={patienceLevel}
                            onChange={setPatienceLevel}
                            decreaseRateRef={patienceDecreaseRateRef}
                          />
                        )}
                    </div>
                  )}

                {puzzmon && (
                  <img
                    className={cn(
                      "z-10 absolute transition-[opacity]",
                      gameState === GameState.BETWEEN_CUSTOMERS ||
                        gameState === GameState.LEAVING_INCORRECT ||
                        gameState === GameState.LEAVING_CORRECT
                        ? "opacity-0"
                        : "opacity-100",
                      gameState === GameState.LEAVING_INCORRECT
                        ? "duration-[2000ms] ease-in"
                        : "duration-1000 ease-linear",
                    )}
                    src={puzzmon.imageSrc}
                    alt={puzzmon.name}
                    style={
                      puzzmon.elandIslandsMonarchTask
                        ? {
                            width: `${puzzmon.elandIslandsMonarchTask.width}%`,
                            top: `${puzzmon.elandIslandsMonarchTask.top}%`,
                            left: `${puzzmon.elandIslandsMonarchTask.left}%`,
                          }
                        : {}
                    }
                  />
                )}
                {/* Top tiny portion - z-20 (2% of viewport) */}
                <div
                  className={cn(
                    "absolute bg-[#604432] w-[3%] z-20 left-[20.5%]",
                    gameState === GameState.POURING ? "h-[2%]" : "h-0",
                  )}
                  style={{
                    top: "56%",
                    animation:
                      gameState === GameState.POURING
                        ? "coffee-top-bit 1200ms linear 100ms forwards"
                        : undefined,
                  }}
                ></div>
                {/* Bottom main portion - z-30 (main animation, 10.6% of viewport) */}
                <div
                  className="absolute bg-[#604432] w-[3%] z-40 left-[20.5%]"
                  style={{
                    animation:
                      gameState === GameState.POURING
                        ? "coffee-pour 1200ms linear 100ms forwards"
                        : undefined,
                  }}
                  key={gameState}
                />
              </>
            )}

            {/* Background images - always shown */}
            <img src={BackgroundImage} alt="" className="w-full h-full" />
            <img
              src={AwningImage}
              alt=""
              className="absolute top-0 left-0 w-full h-full z-20"
            />
            <img
              src={CounterImage}
              alt=""
              className="absolute top-0 left-0 w-full h-full z-20"
            />
            {gameState === GameState.POURING && (
              <>
                <img
                  src={CupImage}
                  alt=""
                  className="absolute top-0 left-0 w-full h-full z-30"
                />
                <img
                  src={CupImageFull}
                  alt=""
                  className="absolute top-0 left-0 w-full h-full z-30"
                  style={{
                    animation:
                      gameState === GameState.POURING
                        ? "cup-after 1200ms linear 0ms forwards"
                        : undefined,
                  }}
                />
              </>
            )}
          </div>
        </div>

        {/* Win animation */}
        {showWinAnimation && (
          <TaskSuccessAnimation
            onComplete={() => {
              setShowWinAnimation(false);
            }}
          />
        )}
      </div>
    </MonarchTaskWrapper>
  );
}

export default ElandIslandsTask;
