// Puzzmon transformation rules

import type {
  Direction,
  LightBeam,
  PuzzmonBeamInfo,
  PuzzmonTransformResult,
  RGBColor,
} from "./beamTypes";
import { reverseDirection, turnLeft, turnRight } from "./beamUtils";
import type { GridPuzzmon } from "./types";

// ============================================================================
// Puzzmon Type IDs
// ============================================================================

// Numeric IDs for puzzmon types (to avoid exposing slugs in frontend)
// These should match the numeric IDs assigned to puzzmon in the backend
const PUZZMON_TYPE_IDS = {
  TYPE_1: 1, // Bumblebeam
  TYPE_2: 2, // Twinkleish (allows multiple inputs)
  TYPE_3: 3, // Knightbulb
  TYPE_4: 4, // Lanternbot
  TYPE_5: 5, // Incandabra
  TYPE_6: 6, // Glimmerpom
  TYPE_7: 7, // Prismoidia
  TYPE_8: 8, // Comettails
  TYPE_9: 9, // Mistermoon
} as const;

// ============================================================================
// Puzzmon Transformation Rules
// ============================================================================

// Type for a puzzmon transformation function
export type PuzzmonTransform = (
  incomingDirection: Direction,
  incomingColor: RGBColor,
  beamInfo: PuzzmonBeamInfo,
) => PuzzmonTransformResult;

// Helper to create a beam (row/col will be set by caller)
const createBeam = (direction: Direction, color: RGBColor): LightBeam => ({
  row: -1, // Will be set by caller
  col: -1,
  direction,
  color,
});

// Bumblebeam: Splits light into RGB components
// - Red component turns right (relative to incoming direction)
// - Green component continues straight
// - Blue component turns left
const puzzmon1Transform: PuzzmonTransform = (
  incomingDirection,
  incomingColor,
  _beamInfo,
) => {
  const beams: LightBeam[] = [];

  // Red component turns right
  if (incomingColor.r > 0.1) {
    beams.push(
      createBeam(turnRight(incomingDirection), {
        r: incomingColor.r,
        g: 0,
        b: 0,
      }),
    );
  }

  // Green component continues straight
  if (incomingColor.g > 0.1) {
    beams.push(
      createBeam(incomingDirection, { r: 0, g: incomingColor.g, b: 0 }),
    );
  }

  // Blue component turns left
  if (incomingColor.b > 0.1) {
    beams.push(
      createBeam(turnLeft(incomingDirection), {
        r: 0,
        g: 0,
        b: incomingColor.b,
      }),
    );
  }

  return { beams };
};

// Twinkleish: Requires exactly 3 inputs
// Once there are 3 inputs, checks if all RGB components are present across all inputs
// If all three components are present, outputs white light in the only remaining side
// If not all three components are present, outputs nothing
const puzzmon2Transform: PuzzmonTransform = (
  _incomingDirection,
  _incomingColor,
  beamInfo,
) => {
  const incomingDirections = Array.from(beamInfo.incoming.keys());

  // Must have exactly 3 inputs
  if (incomingDirections.length !== 3) {
    return { beams: [] };
  }

  // Collect all colors from all incoming directions
  const allColors: RGBColor[] = [];
  for (const direction of incomingDirections) {
    const colors = beamInfo.incoming.get(direction) || [];
    allColors.push(...colors);
  }

  // Check if red, green, and blue components are present
  let hasRed = false;
  let hasGreen = false;
  let hasBlue = false;

  for (const color of allColors) {
    if (color.r > 0.1 && color.b === 0 && color.g === 0) hasRed = true;
    if (color.g > 0.1 && color.r === 0 && color.b === 0) hasGreen = true;
    if (color.b > 0.1 && color.r === 0 && color.g === 0) hasBlue = true;
  }

  // If not all three components are present, output nothing
  if (!hasRed || !hasGreen || !hasBlue) {
    return { beams: [] };
  }

  // Find the remaining side (the direction that's not in incomingDirections)
  const allDirections: Direction[] = ["up", "down", "left", "right"];
  const remainingDirection = allDirections.find(
    (dir) => !incomingDirections.includes(dir),
  );

  if (!remainingDirection) {
    // Shouldn't happen if we have exactly 3 inputs, but handle it
    return { beams: [] };
  }

  // Output white light in the remaining direction
  // We need to reverse the direction because the incoming directions are the direction the beam is traveling in
  return {
    beams: [
      createBeam(reverseDirection(remainingDirection), { r: 1, g: 1, b: 1 }),
    ],
  };
};

// Knightbulb: Keeps the red and green components
// - Red component continues straight
// - Green component continues straight
const puzzmon3Transform: PuzzmonTransform = (
  incomingDirection,
  incomingColor,
  _beamInfo,
) => {
  const beams: LightBeam[] = [];

  if (incomingColor.r > 0.1 || incomingColor.g > 0.1) {
    beams.push(
      createBeam(incomingDirection, {
        r: incomingColor.r,
        g: incomingColor.g,
        b: 0,
      }),
    );
  }

  return { beams };
};

// Lanternbot: Takes still light or single beam input and casts red component to the east
// Still light consumption is handled in beamCalculation.ts
// This transform handles single beam input case
const puzzmon4Transform: PuzzmonTransform = (
  _incomingDirection,
  incomingColor,
  _beamInfo,
) => {
  // Extract red component and output to east (absolute direction "right")
  if (incomingColor.r > 0.1) {
    return {
      beams: [
        createBeam("right", {
          r: incomingColor.r,
          g: 0,
          b: 0,
        }),
      ],
    };
  }
  return { beams: [] };
};

// Incandabra: Takes still light or single beam input and casts blue component to the north
// Still light consumption is handled in beamCalculation.ts
// This transform handles single beam input case
const puzzmon5Transform: PuzzmonTransform = (
  _incomingDirection,
  incomingColor,
  _beamInfo,
) => {
  // Extract blue component and output to north (absolute direction "up")
  if (incomingColor.b > 0.1) {
    return {
      beams: [
        createBeam("up", {
          r: 0,
          g: 0,
          b: incomingColor.b,
        }),
      ],
    };
  }
  return { beams: [] };
};

// TYPE_6: Takes input and casts still light on cells 2 units away
// Still light can go in all 8 directions (including the incoming direction)
// Still light positions relative to puzzmon: (0, 2), (1, 1), (2, 0), (1, -1), (0, -2), (-1, -1), (-2, 0), (-1, 1)
// If Glimmerpom has multiple inputs, it outputs nothing
const puzzmon6Transform: PuzzmonTransform = (
  _incomingDirection,
  incomingColor,
  beamInfo,
) => {
  // Check if Glimmerpom has multiple inputs - if so, output nothing
  const incomingDirections = Array.from(beamInfo.incoming.keys());
  if (incomingDirections.length > 1) {
    return { beams: [], stillLightPositions: [] };
  }

  // This puzzmon doesn't output beams, only still light
  // Get all still light positions (8 positions in a circle 2 units away)
  const allStillLightPositions = [
    { rowOffset: 0, colOffset: 2 },
    { rowOffset: 1, colOffset: 1 },
    { rowOffset: 2, colOffset: 0 },
    { rowOffset: 1, colOffset: -1 },
    { rowOffset: 0, colOffset: -2 },
    { rowOffset: -1, colOffset: -1 },
    { rowOffset: -2, colOffset: 0 },
    { rowOffset: -1, colOffset: 1 },
  ];

  // Return all positions with the incoming color
  // Note: The caller will check if still light already exists at each position
  return {
    beams: [],
    stillLightPositions: allStillLightPositions.map((pos) => ({
      ...pos,
      color: incomingColor,
    })),
  };
};

// Prismoidia: Creates still light at specific positions and continues the beam
// Colors are positioned relative to the direction the beam is coming in from
// Base pattern (when beam comes from top/down):
//   Right side: (1, 1) = magenta, (0, 1) = yellow, (-1, 1) = cyan
//   Left side: (1, -1) = magenta, (0, -1) = yellow, (-1, -1) = cyan
// Only uses color components present in the input beam
// If Prismoidia has more than one input, it outputs nothing
const puzzmon7Transform: PuzzmonTransform = (
  incomingDirection,
  incomingColor,
  beamInfo,
) => {
  // Check if Prismoidia has multiple inputs - if so, output nothing
  const incomingDirections = Array.from(beamInfo.incoming.keys());
  if (incomingDirections.length > 1) {
    return { beams: [], stillLightPositions: [] };
  }
  // Magenta = red + blue = {r: 1, g: 0, b: 1}
  // Yellow = red + green = {r: 1, g: 1, b: 0}
  // Cyan = green + blue = {r: 0, g: 1, b: 1}

  // Extract components for each color based on what's present in input
  // Magenta: uses red and blue components
  const redColor: RGBColor = {
    r: incomingColor.r,
    g: 0,
    b: 0,
  };

  // Yellow: uses red and green components
  const greenColor: RGBColor = {
    r: 0,
    g: incomingColor.g,
    b: 0,
  };

  // Cyan: uses green and blue components
  const blueColor: RGBColor = {
    r: 0,
    g: 0,
    b: incomingColor.b,
  };

  // Base positions relative to Prismoidia (assuming beam comes from top/down)
  // Right side: magenta (1,1), yellow (0,1), cyan (-1,1)
  // Left side: magenta (1,-1), yellow (0,-1), cyan (-1,-1)
  const basePositions = [
    { rowOffset: 1, colOffset: 1, color: redColor }, // Right side - magenta
    { rowOffset: 0, colOffset: 1, color: greenColor }, // Right side - yellow
    { rowOffset: -1, colOffset: 1, color: blueColor }, // Right side - cyan
    { rowOffset: 1, colOffset: -1, color: redColor }, // Left side - magenta
    { rowOffset: 0, colOffset: -1, color: greenColor }, // Left side - yellow
    { rowOffset: -1, colOffset: -1, color: blueColor }, // Left side - cyan
  ];

  // Rotate positions based on incoming beam direction
  // The beam direction is where the beam is traveling TO, so we need to reverse it
  // to get where it's coming FROM
  const beamSourceDirection = reverseDirection(incomingDirection);

  // Transform positions based on beam source direction
  // Base pattern assumes beam comes from top (direction "down")
  // In base pattern: left side = negative col, right side = positive col
  // Cyan is always at the "top" of each side (rowOffset = -1)
  //
  // When beam comes from left (direction "right"):
  //   - Left side relative to Prismoidia = where beam came from = negative col
  //   - Right side relative to Prismoidia = opposite = positive col
  //   - So we rotate 90° clockwise: (row, col) -> (col, -row)
  //
  // When beam comes from right (direction "left"):
  //   - Left side relative to Prismoidia = opposite = positive col
  //   - Right side relative to Prismoidia = where beam came from = negative col
  //   - So we rotate 90° counter-clockwise: (row, col) -> (-col, row)
  //
  // When beam comes from bottom (direction "up"):
  //   - Rotate 180°: (row, col) -> (-row, -col)
  const stillLightPositions = basePositions.map((pos) => {
    switch (beamSourceDirection) {
      case "left":
        // Beam coming from left: rotate 90 degrees clockwise
        // (row, col) -> (col, -row)
        return {
          rowOffset: pos.colOffset,
          colOffset: -pos.rowOffset,
          color: pos.color,
        };
      case "right":
        // Beam coming from right: rotate 90 degrees counter-clockwise
        // (row, col) -> (-col, row)
        return {
          rowOffset: -pos.colOffset,
          colOffset: pos.rowOffset,
          color: pos.color,
        };
      case "up":
        // Beam coming from bottom: rotate 180 degrees
        // (row, col) -> (-row, -col)
        return {
          rowOffset: -pos.rowOffset,
          colOffset: -pos.colOffset,
          color: pos.color,
        };
      case "down":
      default:
        // Beam coming from top (default): no rotation needed
        return pos;
    }
  });

  // Continue the beam in the same direction
  return {
    beams: [createBeam(incomingDirection, incomingColor)],
    stillLightPositions,
  };
};

// Comettails: Redirect the beam in the two perpendicular directions
const puzzmon8Transform: PuzzmonTransform = (
  incomingDirection,
  incomingColor,
  _beamInfo,
) => {
  return {
    beams: [
      createBeam(turnLeft(incomingDirection), incomingColor),
      createBeam(turnRight(incomingDirection), incomingColor),
    ],
  };
};

// Mistermoon: Takes still light and shoots beams in directions with empty spaces
// Still light consumption is handled in beamCalculation.ts
// This transform is not used for beams (Mistermoon only works with still light)
const puzzmon9Transform: PuzzmonTransform = (
  _incomingDirection,
  _incomingColor,
  _beamInfo,
) => {
  // Mistermoon doesn't output beams from beam input, only from still light
  // Beam creation is handled in beamCalculation.ts based on empty adjacent cells
  return { beams: [] };
};

// Default: Beam passes through unchanged
const defaultTransform: PuzzmonTransform = (
  _incomingDirection,
  _incomingColor,
  _beamInfo,
) => {
  return { beams: [] };
};

// ============================================================================
// Puzzmon Rule Registry
// ============================================================================

// Map of puzzmon type IDs to their transformation functions
// To add a new puzzmon type:
// 1. Create a transformation function above (like puzzmon1Transform)
// 2. Add a type ID constant above
// 3. Add an entry to this map: [typeId, transformFunction]
const PUZZMON_RULES = new Map<number, PuzzmonTransform>([
  [PUZZMON_TYPE_IDS.TYPE_1, puzzmon1Transform],
  [PUZZMON_TYPE_IDS.TYPE_2, puzzmon2Transform],
  [PUZZMON_TYPE_IDS.TYPE_3, puzzmon3Transform],
  [PUZZMON_TYPE_IDS.TYPE_4, puzzmon4Transform],
  [PUZZMON_TYPE_IDS.TYPE_5, puzzmon5Transform],
  [PUZZMON_TYPE_IDS.TYPE_6, puzzmon6Transform],
  [PUZZMON_TYPE_IDS.TYPE_7, puzzmon7Transform],
  [PUZZMON_TYPE_IDS.TYPE_8, puzzmon8Transform],
  [PUZZMON_TYPE_IDS.TYPE_9, puzzmon9Transform],
]);

// Helper to get puzzmon type ID from GridPuzzmon
// IMPORTANT: The backend must send numeric type IDs in the `id` field
// (e.g., "1" for TYPE_1, "2" for TYPE_2, "3" for TYPE_3)
// If the id field contains a UUID or other non-numeric identifier,
// the type cannot be determined and default transform will be used
const getPuzzmonTypeId = (puzzmon: GridPuzzmon): number | null => {
  // Try parsing the id field directly as a number
  const idNum = puzzmon.order;

  // Check if it's a valid positive integer
  if (!Number.isNaN(idNum) && Number.isInteger(idNum) && idNum > 0) {
    return idNum;
  }

  // If id is not numeric, we can't determine the type
  // This will cause the puzzmon to use the default transform (pass through)
  return null;
};

// Check if a puzzmon allows multiple inputs
// TYPE_2 (Twinkleish) requires exactly 3 inputs
// TYPE_3 (Knightbulb) allows multiple inputs
// TYPE_6 allows multiple inputs (mixes colors)
const allowsMultipleInputs = (typeId: number): boolean => {
  return (
    typeId === PUZZMON_TYPE_IDS.TYPE_3 || typeId === PUZZMON_TYPE_IDS.TYPE_6
  );
};

// Check if a puzzmon requires exactly N inputs
const requiresExactlyNInputs = (typeId: number): number | null => {
  if (typeId === PUZZMON_TYPE_IDS.TYPE_2) {
    return 3; // Twinkleish requires exactly 3 inputs
  }
  return null;
};

// Apply puzzmon transformation rules
export function applyPuzzmonTransformation(
  puzzmon: GridPuzzmon,
  incomingDirection: Direction,
  incomingColor: RGBColor,
  beamInfo: PuzzmonBeamInfo,
): PuzzmonTransformResult {
  const typeId = getPuzzmonTypeId(puzzmon);

  // Check if puzzmon has multiple incoming beam directions
  // Note: beamInfo.incoming already includes the current beam being processed
  const incomingDirections = Array.from(beamInfo.incoming.keys());
  const hasMultipleInputs = incomingDirections.length > 1;

  // Check if puzzmon requires exactly N inputs
  const requiredInputs =
    typeId !== null ? requiresExactlyNInputs(typeId) : null;
  if (requiredInputs !== null) {
    // If puzzmon requires exactly N inputs and we don't have that many, return no beams
    // The transform function will handle checking if we have exactly N
    if (incomingDirections.length < requiredInputs) {
      return { beams: [] };
    }
  } else if (hasMultipleInputs) {
    // If puzzmon has multiple inputs and doesn't allow them, return no beams
    if (typeId === null || !allowsMultipleInputs(typeId)) {
      return { beams: [] };
    }
  }

  // If type ID is invalid, use default transform (pass through)
  if (typeId === null) {
    return defaultTransform(incomingDirection, incomingColor, beamInfo);
  }

  // Find matching transformation rule
  const transform = PUZZMON_RULES.get(typeId);
  if (transform) {
    // Apply the transform - this will split RGB for TYPE_1, etc.
    return transform(incomingDirection, incomingColor, beamInfo);
  }

  // Default: beam passes through unchanged
  return defaultTransform(incomingDirection, incomingColor, beamInfo);
}
