import { type PuzzmonPreferences } from "@hunt/puzzle-components";
import React from "react";
import { ScoreDisplay } from "./ScoreDisplay";

type PreferencesTabProps = {
  score: number;
  goal: number;
  preferences: PuzzmonPreferences[];
};

const PuzzmonPreferencesCard: React.FC<{
  puzzmonData: PuzzmonPreferences;
}> = ({ puzzmonData }) => {
  const { name, imageSrc, preferences } = puzzmonData;

  return (
    <div className="flex gap-4 p-4 border-2 border-monarch-dark rounded-lg bg-gray-25 text-monarch-dark">
      <div className="flex-shrink-0">
        <div className="w-20 h-20 overflow-hidden">
          <img
            src={imageSrc}
            alt={name}
            className="w-full h-full object-contain"
          />
        </div>
      </div>

      <div className="flex flex-col gap-1">
        <div>
          <b>{name}</b> prefers:
        </div>
        <ul className="ml-4 list-disc">
          {preferences.map((preference) => (
            <li key={preference.id} className="text-base">
              {preference.description}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export const PreferencesTab: React.FC<PreferencesTabProps> = ({
  score,
  goal,
  preferences,
}) => {
  return (
    <div className="p-6 h-full w-full overflow-y-auto">
      <div className="flex items-center justify-between mb-4 mt-0">
        <h2 className="text-2xl font-bold text-secondary">Preferences</h2>
        <ScoreDisplay score={score} goal={goal} />
      </div>

      <div className="grid grid-cols-1 monarch-medium:grid-cols-2 gap-4">
        {preferences.map((puzzmonData) => (
          <PuzzmonPreferencesCard
            key={puzzmonData.id}
            puzzmonData={puzzmonData}
          />
        ))}
      </div>
    </div>
  );
};
