import { cn } from "@hunt/styled-ui";
import { useMemo } from "react";
import { type Direction, type Position } from "./types";

type SnakeSegmentProps = {
  previous?: Position;
  current: Position;
  next?: Position;
  movementDirection: Direction;
  className?: string;
  lineClassName?: string;
};

const NARROW_DIRECTION_CLASSES: Record<Direction, string> = {
  UP: "top-0 left-[45%] w-[10%] h-[55%]",
  DOWN: "bottom-0 left-[45%] w-[10%] h-[55%]",
  LEFT: "top-[45%] left-0 w-[55%] h-[10%]",
  RIGHT: "top-[45%] right-0 w-[55%] h-[10%]",
};

const DIRECTION_CLASSES: Record<Direction, string> = {
  UP: "top-0 left-1/4 w-1/2 h-3/4",
  DOWN: "bottom-0 left-1/4 w-1/2 h-3/4",
  LEFT: "top-1/4 left-0 w-3/4 h-1/2",
  RIGHT: "top-1/4 right-0 w-3/4 h-1/2",
};

function getDirection(t1: Position, t2: Position): Direction | undefined {
  const deltaX = t2.x - t1.x;
  const deltaY = t2.y - t1.y;
  if (Math.abs(deltaX) > 1 || Math.abs(deltaY) > 1) {
    return undefined;
  }

  if (deltaX === 0 && deltaY < 0) {
    return "UP";
  }
  if (deltaX === 0 && deltaY > 0) {
    return "DOWN";
  }
  if (deltaX > 0 && deltaY === 0) {
    return "RIGHT";
  }
  if (deltaX < 0 && deltaY === 0) {
    return "LEFT";
  }

  throw new Error("oops!");
}

function oppositeDirection(d: Direction | undefined): Direction | undefined {
  if (d === "LEFT") {
    return "RIGHT";
  }
  if (d === "RIGHT") {
    return "LEFT";
  }
  if (d === "UP") {
    return "DOWN";
  }
  if (d === "DOWN") {
    return "UP";
  }

  return undefined;
}

function SnakeSegment({
  previous,
  current,
  next,
  movementDirection,
  className,
  lineClassName,
}: SnakeSegmentProps) {
  const [d1, d2] = useMemo(() => {
    let d1: Direction | undefined;
    let d2: Direction | undefined;

    if (previous !== undefined) {
      d1 = getDirection(current, previous);
    }

    if (next !== undefined) {
      d2 = getDirection(current, next);
    }

    if (d1 === undefined && d2 !== undefined) {
      d1 = oppositeDirection(d2);
    } else if (d1 !== undefined && d2 === undefined) {
      d2 = oppositeDirection(d1);
    } else if (d1 === undefined && d2 === undefined) {
      if (movementDirection === "RIGHT" || movementDirection === "LEFT") {
        d1 = "LEFT";
        d2 = "RIGHT";
      } else {
        d1 = "UP";
        d2 = "DOWN";
      }
    }

    if (d1 === undefined || d2 === undefined) {
      throw new Error("oops!");
    }

    return [d1, d2];
  }, [previous, next, current, movementDirection]);

  return (
    <>
      {previous !== undefined && (
        <>
          <div className={cn("absolute", DIRECTION_CLASSES[d1], className)} />
          {lineClassName !== undefined && (
            <div
              className={cn(
                "absolute z-[15]",
                NARROW_DIRECTION_CLASSES[d1],
                lineClassName,
              )}
            />
          )}
        </>
      )}
      <div className={cn("absolute", DIRECTION_CLASSES[d2], className)} />
      {lineClassName !== undefined && (
        <div
          className={cn(
            "absolute z-[15]",
            NARROW_DIRECTION_CLASSES[d2],
            lineClassName,
          )}
        />
      )}
    </>
  );
}

export default SnakeSegment;
