import { type MonsterDetails } from "@hunt/hunt-data/monarch";
import { X } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import React from "react";
import type { Photo } from "../types";

type PhotoAlbumProps = {
  isOpen: boolean;
  onClose: () => void;
  photos: Photo[];
  cats: MonsterDetails[];
};

export function PhotoAlbum({ isOpen, onClose, photos, cats }: PhotoAlbumProps) {
  return (
    <AnimatePresence>
      {isOpen && (
        <div className="absolute inset-x-0 bottom-0 flex justify-center h-full z-[300]">
          <motion.div
            initial={{ y: "100%" }}
            animate={{ y: 0 }}
            exit={{ y: "100%" }}
            transition={{ type: "spring", damping: 25, stiffness: 200 }}
            className="rounded-t-2xl shadow-2xl w-full max-w-4xl overflow-y-auto bg-gray-200"
          >
            <div className="p-6 relative text-black">
              {/* Close button */}
              <button
                type="button"
                onClick={onClose}
                className="absolute top-4 right-4 text-gray-500 hover:text-gray-700 text-2xl"
                aria-label="Close photo album"
              >
                <X size={24} />
              </button>

              <h2 className="text-2xl font-bold mb-2 text-center">
                Photo Album
              </h2>

              {/* Photos grid */}
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-6 pt-2">
                {cats.map((cat, index) => {
                  const photo = photos.find((p) => p.catName === cat.name);
                  return (
                    <div key={index} className="flex flex-col items-center">
                      <div
                        className="bg-white p-2 pb-4 shadow-lg flex flex-col items-center justify-center text-gray-500 text-xs w-full"
                        style={{
                          transform: `rotate(${(index % 3) * 2 - 2}deg)`,
                        }}
                      >
                        {photo ? (
                          <>
                            <img
                              src={photo.photoSrc}
                              alt={cat.name}
                              className="w-full h-auto object-contain"
                            />
                            <div className="pt-2 px-2 text-center text-black">
                              <div className="text-sm font-bold">
                                {cat.name}
                              </div>
                            </div>
                          </>
                        ) : (
                          <>
                            <div className="flex-1 flex items-center justify-center h-full w-full aspect-square">
                              No photo
                            </div>
                            <div className="pt-2 px-2 text-center text-black">
                              <div className="text-sm font-bold">
                                {cat.name}
                              </div>
                            </div>
                          </>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}
