import {
  MONSTER_ZONES,
  type MonsterDetails,
  type MonarchData,
  ALL_ZONES,
  zoneToSlug,
} from "@hunt/hunt-data/monarch";
import { type TeamHuntState } from "@hunt/public-client";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import MonarchPageLayout from "../../MonarchPageLayout";
import { expandMonarchDataToShowAll } from "../../expandMonarchDataToShowAll";
import { matchesSlug, slugify } from "../../lib/slug";
import { deleteQueryParam } from "../../lib/url";
import AviariaTask from "../../tasks/aviaria/AviariaTask";
import aviaria_task_bg from "../../tasks/aviaria/assets/background.png";
import BubbleCoveTask from "../../tasks/bubble_cove/BubbleCoveTask";
import ElandIslandsTask from "../../tasks/eland_islands/ElandIslandsTask";
import ElderDriftsTask from "../../tasks/elder_drifts/ElderDriftsTask";
import elder_drifts_task_bg from "../../tasks/elder_drifts/assets/elder_drifts_task_bg.png";
import KittyCityTask from "../../tasks/kitty_city/KittyCityTask";
import kitty_city_task_bg from "../../tasks/kitty_city/assets/background.png";
import { type MonarchTaskProps } from "../../tasks/monarch_tasks_defs";
import OldBarkTownTask from "../../tasks/old_bark_town/OldBarkTownTask";
import PrismaticPathsTask from "../../tasks/prismatic_paths/PrismaticPathsTask";
import RoyalGrovesTask from "../../tasks/royal_groves/RoyalGrovesTask";
import SerpentineHillsTask from "../../tasks/serpentine_hills/SerpentineHillsTask";
import useMonarchData from "../../useMonarchData";
import {
  MONARCH_QUERY_KEYS,
  getQueryParam,
  requireString,
} from "../../useMonarchQueryParams";
import MonarchErrorPageContent from "../MonarchErrorPageContent";
import AllPuzzmonPage from "./AllPuzzmonPage";
import HelpPage from "./HelpPage";
import IndividualPuzzmonPage from "./IndividualPuzzmonPage/IndividualPuzzmonPage";

export const ZONE_TO_TASK: Partial<
  Record<
    string,
    {
      zone: MONSTER_ZONES;
      component: null | ((props: MonarchTaskProps) => React.JSX.Element);
      background?: string;
      taskSlug: string;
    }
  >
> = {
  [slugify(MONSTER_ZONES.AVIARIA)]: {
    zone: MONSTER_ZONES.AVIARIA,
    component: AviariaTask,
    background: aviaria_task_bg,
    taskSlug: "monarch_aviaria_task",
  },
  [slugify(MONSTER_ZONES.ROYAL_GROVES)]: {
    zone: MONSTER_ZONES.ROYAL_GROVES,
    component: RoyalGrovesTask,
    taskSlug: "monarch_royal_groves_task",
  },
  [slugify(MONSTER_ZONES.OLD_BARK_TOWN)]: {
    zone: MONSTER_ZONES.OLD_BARK_TOWN,
    component: OldBarkTownTask,
    taskSlug: "monarch_old_bark_town_task",
  },
  [slugify(MONSTER_ZONES.ELDER_DRIFTS)]: {
    zone: MONSTER_ZONES.ELDER_DRIFTS,
    component: ElderDriftsTask,
    background: elder_drifts_task_bg,
    taskSlug: "monarch_elder_drifts_task",
  },
  [slugify(MONSTER_ZONES.KITTY_CITY)]: {
    zone: MONSTER_ZONES.KITTY_CITY,
    component: KittyCityTask,
    background: kitty_city_task_bg,
    taskSlug: "monarch_kitty_city_task",
  },
  [slugify(MONSTER_ZONES.BUBBLE_COVE)]: {
    zone: MONSTER_ZONES.BUBBLE_COVE,
    component: BubbleCoveTask,
    taskSlug: "monarch_bubble_cove_task",
  },
  [slugify(MONSTER_ZONES.THE_BRIGHTS)]: {
    zone: MONSTER_ZONES.THE_BRIGHTS,
    component: PrismaticPathsTask,
    taskSlug: "monarch_the_brights_task",
  },
  [slugify(MONSTER_ZONES.ELAND_ISLANDS)]: {
    zone: MONSTER_ZONES.ELAND_ISLANDS,
    component: ElandIslandsTask,
    taskSlug: "monarch_eland_islands_task",
  },
  [slugify(MONSTER_ZONES.SERPENTINE_HILLS)]: {
    zone: MONSTER_ZONES.SERPENTINE_HILLS,
    component: SerpentineHillsTask,
    taskSlug: "monarch_serpentine_hills_task",
  },
};

type MonarchContentProps = {
  initialMonsterSlug?: string;
  initialSearchTerm?: string;
  initialZoneFilter?: string;
  initialTask?: string;
  initialPage?: string;
  monarchData?: MonarchData;
  teamState?: TeamHuntState;
};

const MONARCH_SHOW_ALL_PUZZMON_KEY = "monarchShowAllPuzzmon";

const getStoredShowAllPuzzmon = (): boolean => {
  if (typeof window === "undefined") return false;
  return window.localStorage.getItem(MONARCH_SHOW_ALL_PUZZMON_KEY) === "true";
};

const getPrefersDark = (): boolean => {
  if (typeof window === "undefined") {
    return false;
  }
  return window.matchMedia("(prefers-color-scheme: dark)").matches;
};

function MonarchContent({
  initialMonsterSlug,
  initialSearchTerm,
  initialZoneFilter,
  initialTask,
  initialPage,
  monarchData,
  teamState,
}: MonarchContentProps) {
  const [showAllPuzzmon, setShowAllPuzzmonState] = useState(
    getStoredShowAllPuzzmon,
  );

  const setShowAllPuzzmon = useCallback(
    (value: React.SetStateAction<boolean>) => {
      setShowAllPuzzmonState((prev) => {
        const next = typeof value === "function" ? value(prev) : value;
        if (typeof window !== "undefined") {
          window.localStorage.setItem(
            MONARCH_SHOW_ALL_PUZZMON_KEY,
            String(next),
          );
        }
        return next;
      });
    },
    [],
  );

  const displayedMonarchData = useMemo(() => {
    if (showAllPuzzmon && monarchData) {
      return expandMonarchDataToShowAll(monarchData);
    }
    return monarchData;
  }, [showAllPuzzmon, monarchData]);

  const {
    allMonsterData,
    displayedMonsterData,
    numMonstersBefriended,
    searchTerm,
    handleSearchInput,
    selectedZone,
    handleZoneUpdate,
    zoneDetails,
  } = useMonarchData(
    initialSearchTerm,
    initialZoneFilter,
    displayedMonarchData,
  );

  const [systemPrefersDark, setSystemPrefersDark] = useState(getPrefersDark());
  const [selectedMonsterName, setSelectedMonsterName] =
    useState(initialMonsterSlug);
  const [zoneTaskSelected, setZoneTaskSelected] = useState<string | undefined>(
    initialTask,
  );
  const [helpPageOpen, setHelpPageOpen] = useState(initialPage === "help");

  useEffect(() => {
    // Check URL for Puzzmon slug when component mounts or when monarch opens.
    // This will allow us to link directly to a Puzzmon page.
    if (typeof window !== "undefined") {
      const urlParams = new URLSearchParams(window.location.search);
      const puzzmonSlugFromUrl = urlParams.get(MONARCH_QUERY_KEYS.PUZZMON_SLUG);
      if (puzzmonSlugFromUrl) {
        setSelectedMonsterName(puzzmonSlugFromUrl);
      }
      const taskFromUrl = urlParams.get(MONARCH_QUERY_KEYS.TASK);
      if (taskFromUrl) {
        setZoneTaskSelected(taskFromUrl);
      }
      const pageFromUrl = urlParams.get(MONARCH_QUERY_KEYS.PAGE);
      if (pageFromUrl === "help") {
        setHelpPageOpen(true);
      }
    }
  }, []);

  useEffect(() => {
    // This will only be relevant on client-side, when `window` is defined.
    // Since we define routing in the backend, the page does not rerender when the
    // Back button or Forward button is clicked. Thus, we need to manually add a
    // listener to handle the state update (or switch to React Router).
    let listener: (this: Window, ev: PopStateEvent) => void;
    let monarchOpenListener: () => void;
    if (window) {
      listener = () => {
        setSelectedMonsterName(
          requireString(
            // We pass in undefined so the hook will read from window.location.search.
            getQueryParam(undefined, MONARCH_QUERY_KEYS.PUZZMON_SLUG),
          ),
        );
        const taskFromUrl = requireString(
          getQueryParam(undefined, MONARCH_QUERY_KEYS.TASK),
        );
        if (taskFromUrl) {
          setZoneTaskSelected(taskFromUrl);
        }
        const pageFromUrl = requireString(
          getQueryParam(undefined, MONARCH_QUERY_KEYS.PAGE),
        );
        setHelpPageOpen(pageFromUrl === "help");
      };
      monarchOpenListener = () => {
        // When monarch opens, check URL for task param
        const urlParams = new URLSearchParams(window.location.search);
        const taskFromUrl = urlParams.get(MONARCH_QUERY_KEYS.TASK);
        if (taskFromUrl) {
          setZoneTaskSelected(taskFromUrl);
        }
      };
      window.addEventListener("popstate", listener);
      window.addEventListener("monarch-open", monarchOpenListener);
    }

    return () => {
      if (listener) {
        window.removeEventListener("popstate", listener);
      }
      if (monarchOpenListener) {
        window.removeEventListener("monarch-open", monarchOpenListener);
      }
    };
  }, []);

  useEffect(() => {
    if (typeof window === "undefined") {
      return;
    }
    const mql = window.matchMedia("(prefers-color-scheme: dark)");
    const listener = (event: MediaQueryListEvent) => {
      setSystemPrefersDark(event.matches);
    };
    mql.addEventListener("change", listener);
    return () => {
      mql.removeEventListener("change", listener);
    };
  }, []);

  const isDarkMode = systemPrefersDark;

  const selectedMonsterDetails = useMemo(() => {
    return allMonsterData.find(({ name }: MonsterDetails) => {
      return matchesSlug(name, selectedMonsterName ?? "");
    });
  }, [allMonsterData, selectedMonsterName]);

  const { previousMonsterSlug, nextMonsterSlug } = useMemo(() => {
    const currentIndex = allMonsterData.findIndex(
      ({ name }: MonsterDetails) => {
        return matchesSlug(name, selectedMonsterName ?? "");
      },
    );
    return {
      previousMonsterSlug:
        currentIndex > 0 &&
        allMonsterData[currentIndex - 1].zone === selectedMonsterDetails?.zone
          ? allMonsterData[currentIndex - 1].name
          : undefined,
      nextMonsterSlug:
        currentIndex < allMonsterData.length - 1 &&
        allMonsterData[currentIndex + 1].zone === selectedMonsterDetails?.zone
          ? allMonsterData[currentIndex + 1].name
          : undefined,
    };
  }, [allMonsterData, selectedMonsterDetails?.zone, selectedMonsterName]);

  if (selectedMonsterName && !selectedMonsterDetails) {
    return <MonarchErrorPageContent text="Puzzmon does not exist." />;
  }

  let contents: React.ReactNode;
  if (helpPageOpen) {
    contents = (
      <HelpPage
        onBack={() => {
          setHelpPageOpen(false);
          setSelectedMonsterName(undefined);
        }}
      />
    );
  } else if (selectedMonsterDetails) {
    contents = (
      <IndividualPuzzmonPage
        puzzmonDetails={selectedMonsterDetails}
        setSelectedMonsterName={setSelectedMonsterName}
        capstoneSlug={
          selectedMonsterDetails.zone === MONSTER_ZONES.THE_GLITCH
            ? ""
            : Object.entries(teamState?.puzzles ?? {}).find(
                (puzzle) =>
                  puzzle[1].round === zoneToSlug(selectedMonsterDetails.zone) &&
                  puzzle[1].is_meta,
              )?.[0]
        }
        previousPuzzmon={previousMonsterSlug}
        nextPuzzmon={nextMonsterSlug}
        isDarkMode={isDarkMode}
      />
    );
  } else if (zoneTaskSelected && zoneTaskSelected in ZONE_TO_TASK) {
    const taskInfo = ZONE_TO_TASK[zoneTaskSelected as MONSTER_ZONES];
    const Component = taskInfo?.component;
    contents = Component ? (
      <Component
        returnToArchive={() => {
          deleteQueryParam(MONARCH_QUERY_KEYS.TASK);
          setZoneTaskSelected(undefined);
        }}
        puzzmonData={allMonsterData.filter(
          ({ zone }) => zone === taskInfo?.zone,
        )}
        backgroundImageSrc={taskInfo?.background}
        teamState={teamState}
        taskSlug={taskInfo?.taskSlug}
      />
    ) : null;
  } else {
    contents = (
      <AllPuzzmonPage
        numMonstersBefriended={numMonstersBefriended}
        searchTerm={searchTerm}
        handleSearchInput={handleSearchInput}
        monstersByZone={displayedMonsterData}
        setSelectedMonsterName={setSelectedMonsterName}
        selectedZone={selectedZone}
        setSelectedZone={handleZoneUpdate}
        setZoneTaskSelected={setZoneTaskSelected}
        zoneDetails={zoneDetails}
        activeZones={[ALL_ZONES, ...Object.keys(displayedMonarchData ?? {})]}
        showAllPuzzmon={showAllPuzzmon}
        setShowAllPuzzmon={setShowAllPuzzmon}
        teamState={teamState}
        isDarkMode={isDarkMode}
        setHelpPageOpen={setHelpPageOpen}
      />
    );
  }

  return <MonarchPageLayout>{contents}</MonarchPageLayout>;
}

export default MonarchContent;
