import { useEffect } from "react";
import getConfetti from "./confetti";

function TaskSuccessAnimation({ onComplete }: { onComplete: () => void }) {
  // Automatically trigger onComplete after animation finishes
  useEffect(() => {
    getConfetti();

    const timeout = setTimeout(onComplete, 2000);
    return () => {
      clearTimeout(timeout);
    };
  }, [onComplete]);

  return null;
}

export default TaskSuccessAnimation;
