import { ALL_ZONES } from "@hunt/hunt-data/monarch";
import { Select, SelectContent, SelectItem, SelectTrigger } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { Funnel } from "lucide-react";
import React from "react";

const MONARCH_SELECT_TRIGGER_STYLING = `
  w-60 justify-start gap-2 text-white text-base
  items-center rounded-full px-3 py-1
  bg-monarch-input-bg border-2 border-monarch-input-border
  box-border shadow-[0_0_10px_rgba(0,179,255,0.4)]
  focus:outline-none focus-visible:outline-none
  focus-visible:border-monarch-light focus-visible:shadow-[0_0_12px_rgba(0,179,255,0.8)]
`;

type FilterByZoneProps = {
  selectedItem: string;
  onValueChange: (value: string) => void;
  menuOptions: string[];
};

function FilterByZone({
  selectedItem,
  onValueChange,
  menuOptions,
}: FilterByZoneProps) {
  return (
    <Select value={selectedItem} onValueChange={onValueChange}>
      <SelectTrigger
        className={MONARCH_SELECT_TRIGGER_STYLING}
        chevronClassName="text-monarch-light opacity-100"
      >
        <Funnel width={18} height={18} className="text-monarch-light" />
        <div className="flex items-center gap-1 flex-1">
          <span className="text-monarch-input-placeholder italic">Zone: </span>
          <span
            className={cn(
              "text-left",
              selectedItem === ALL_ZONES &&
                "text-monarch-input-placeholder italic",
            )}
          >
            {selectedItem}
          </span>
        </div>
      </SelectTrigger>
      <SelectContent className="w-60 bg-monarch-input-bg border-2 border-monarch-input-border shadow-[0_2px_8px_black]">
        {Object.values(menuOptions).map((text) => {
          return (
            <SelectItem
              value={text}
              key={text}
              className="cursor-pointer text-white focus:bg-monarch-light focus:text-monarch-dark"
            >
              {text}
            </SelectItem>
          );
        })}
      </SelectContent>
    </Select>
  );
}

export default FilterByZone;
