import {
  type CriterionWithScore,
  type ScoringLevelWithAchieved,
} from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import { Check } from "lucide-react";
import React from "react";
import { ScoreDisplay } from "./ScoreDisplay";

type ScoringTabProps = {
  goal: number;
  score: number;
  criteria: CriterionWithScore[];
};

const ScoringLevelCell: React.FC<{
  level: ScoringLevelWithAchieved;
}> = ({ level }) => {
  return (
    <td className="py-4 text-center">
      <div className="flex items-center justify-center">
        <div className="w-6 h-6 flex items-center justify-center">
          {level.achieved && (
            <Check className="text-green-600" strokeWidth={4} />
          )}
        </div>
        <span
          className={cn(
            "font-mono min-w-6 text-center",
            level.achieved
              ? "text-green-700 font-semibold"
              : "text-monarch-dark",
          )}
        >
          {level.threshold}
        </span>
      </div>
    </td>
  );
};

export const ScoringTab: React.FC<ScoringTabProps> = ({
  score,
  goal,
  criteria,
}) => {
  const headerPoints = [1, 2, 3, 4, 5];

  return (
    <div className="p-6 h-full w-full overflow-y-auto">
      <div className="flex items-center justify-between mb-4 mt-0">
        <h2 className="text-2xl font-bold text-secondary">Scoring</h2>
        <ScoreDisplay score={score} goal={goal} />
      </div>

      <table className="w-full text-lg border-collapse text-monarch-dark">
        <thead>
          <tr className="border-b-2 border-monarch-dark">
            <th className="text-left font-normal"></th>
            <th className="text-center font-bold min-w-[3rem] border-l-2 border-r-2 border-monarch-dark">
              #
            </th>
            {headerPoints.map((points, index) => (
              <th
                key={`header-${index}`}
                className="text-center font-bold text-primary"
              >
                <div className="flex items-center justify-center gap-1">
                  <div className="w-6 h-6"></div>
                  {points}pt
                </div>
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {criteria.map((criterion) => (
            <tr
              key={criterion.id}
              className="border-b border-monarch-dark last:border-b-0"
            >
              <td className="py-4 pr-2">
                <div className="flex gap-3 items-center">
                  <p className="font-normal text-secondary">{criterion.name}</p>
                  {criterion.id === "c1" && (
                    <div className="px-2 py-0.5 text-sm text-white font-bold rounded-md bg-monarch-dark whitespace-nowrap">
                      2× POINTS
                    </div>
                  )}
                </div>
              </td>
              <td className="py-4 text-center border-l-2 border-r-2 border-monarch-dark">
                <div className="font-bold">{criterion.metric}</div>
              </td>
              {criterion.levels.map((level) => (
                <ScoringLevelCell
                  key={`${criterion.id}-${level.threshold}`}
                  level={level}
                />
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};
