// Beam utility functions

import type { Direction, RGBColor } from "./beamTypes";

// Color mixing: additive color mixing (red + green = yellow, etc.)
// For light colors (like lightred = 2R + 1G + 1B), we normalize by the maximum component
// when it exceeds 1, rather than clamping each component individually
export function mixColors(colors: RGBColor[]): RGBColor {
  if (colors.length === 0) return { r: 0, g: 0, b: 0 };
  if (colors.length === 1) return colors[0];

  // Additive mixing: sum all components first
  const summed = colors.reduce(
    (acc, color) => ({
      r: acc.r + color.r,
      g: acc.g + color.g,
      b: acc.b + color.b,
    }),
    { r: 0, g: 0, b: 0 },
  );

  // Find the maximum component
  const maxComponent = Math.max(summed.r, summed.g, summed.b);

  // If max > 1, normalize all components by dividing by max
  // This allows creating light colors like lightred (2R+1G+1B normalized to 1R+0.5G+0.5B)
  if (maxComponent > 1) {
    return {
      r: summed.r / maxComponent,
      g: summed.g / maxComponent,
      b: summed.b / maxComponent,
    };
  }

  // If max <= 1, clamp each component to 1 (standard additive mixing)
  return {
    r: Math.min(1, summed.r),
    g: Math.min(1, summed.g),
    b: Math.min(1, summed.b),
  };
}

// Convert RGB to CSS color string
export function rgbToCss(color: RGBColor, opacity = 1): string {
  return `rgba(${Math.round(color.r * 255)}, ${Math.round(color.g * 255)}, ${Math.round(color.b * 255)}, ${opacity})`;
}

// Convert RGB to hex color string (e.g., "#FF7F7F")
export function rgbToHex(color: RGBColor): string {
  const r = Math.round(color.r * 255)
    .toString(16)
    .padStart(2, "0");
  const g = Math.round(color.g * 255)
    .toString(16)
    .padStart(2, "0");
  const b = Math.round(color.b * 255)
    .toString(16)
    .padStart(2, "0");
  return `#${r}${g}${b}`.toUpperCase();
}

export function rgbToComponents(color: RGBColor): string {
  const components: [string, number][] = [
    ["R", color.r],
    ["G", color.g],
    ["B", color.b],
  ];

  // Filter out zero components
  const nonZero = components.filter(([, v]) => v >= 0.1);
  if (nonZero.length === 0) return "";

  // Find smallest non-zero value
  const min = Math.min(...nonZero.map(([, v]) => v));

  // Convert to integer counts
  const units = nonZero.map(([k, v]) => ({
    k,
    count: Math.round(v / min),
  }));

  // Build string
  return units
    .flatMap(({ k, count }) => Array.from({ length: count }, () => k))
    .join("");
}

// ============================================================================
// Direction Utilities
// ============================================================================

// Helper functions for direction manipulation
export const turnLeft = (dir: Direction): Direction => {
  switch (dir) {
    case "down":
      return "right";
    case "up":
      return "left";
    case "right":
      return "up";
    case "left":
      return "down";
  }
};

export const turnRight = (dir: Direction): Direction => {
  switch (dir) {
    case "down":
      return "left";
    case "up":
      return "right";
    case "right":
      return "down";
    case "left":
      return "up";
  }
};

export const getPerpendicularLeft = (dir: Direction): Direction => {
  switch (dir) {
    case "down":
      return "right";
    case "up":
      return "left";
    case "right":
      return "up";
    case "left":
      return "down";
  }
};

export const getPerpendicularRight = (dir: Direction): Direction => {
  switch (dir) {
    case "down":
      return "left";
    case "up":
      return "right";
    case "right":
      return "down";
    case "left":
      return "up";
  }
};

// Reverse a direction (get the opposite direction)
export const reverseDirection = (dir: Direction): Direction => {
  switch (dir) {
    case "down":
      return "up";
    case "up":
      return "down";
    case "right":
      return "left";
    case "left":
      return "right";
  }
};

// ============================================================================
// Color Name Detection
// ============================================================================

export type ColorName =
  | "red"
  | "green"
  | "blue"
  | "yellow"
  | "magenta"
  | "cyan"
  | "lightred"
  | "lightgreen"
  | "lightblue"
  | "white";

// Convert color name to RGB color value
export function colorNameToRgb(colorName: ColorName): RGBColor {
  switch (colorName) {
    case "red":
      return { r: 1, g: 0, b: 0 };
    case "green":
      return { r: 0, g: 1, b: 0 };
    case "blue":
      return { r: 0, g: 0, b: 1 };
    case "yellow":
      return { r: 1, g: 1, b: 0 };
    case "magenta":
      return { r: 1, g: 0, b: 1 };
    case "cyan":
      return { r: 0, g: 1, b: 1 };
    case "lightred":
      // #FF7F7F = RGB(255, 127, 127) = 2 parts red, 1 part green, 1 part blue
      return { r: 1, g: 0.5, b: 0.5 };
    case "lightgreen":
      // #7FFF7F = RGB(127, 255, 127) = 1 part red, 2 parts green, 1 part blue
      return { r: 0.5, g: 1, b: 0.5 };
    case "lightblue":
      // #7F7FFF = RGB(127, 127, 255) = 1 part red, 1 part green, 2 parts blue
      return { r: 0.5, g: 0.5, b: 1 };
    case "white":
      return { r: 1, g: 1, b: 1 };
  }
}

// Calculate relative luminance of a color (0-1)
// Returns true if color is light (should use dark text), false if dark (should use light text)
export function isLightColor(color: RGBColor): boolean {
  // Calculate relative luminance using standard formula
  // L = 0.2126 * R + 0.587 * G + 0.1144 * B
  const luminance = 0.2126 * color.r + 0.587 * color.g + 0.1144 * color.b;
  // If luminance is above 0.5, it's considered light
  return luminance > 0.5;
}
