import { type MonarchData } from "@hunt/hunt-data/monarch";
import { type TeamHuntState } from "@hunt/public-client";
import {
  MonarchDevice,
  MonarchDeviceTopLeft,
  MonarchDeviceTopRight,
  MonarchDeviceBottomLeft,
  MonarchDeviceBottomRight,
  MonarchGem,
} from "@hunt/puzzle-components";
import {
  Dialog,
  DialogTitle,
  DialogTrigger,
  DialogContent,
} from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { X } from "lucide-react";
import { type ParsedQs } from "qs";
import React, { useCallback, useState, useEffect } from "react";
import { deleteQueryParam, updateQueryParam } from "./lib/url";
import MonarchContent from "./tabs/MonarchContent/MonarchContent";
import useMonarchQueryParams, {
  MONARCH_QUERY_KEYS,
} from "./useMonarchQueryParams";

export const MONARCH_OPEN_EVENT = "monarchOpen";
export const MONARCH_CLOSE_EVENT = "monarchClose";

type EmbeddedMonarchProps = {
  queryParams?: ParsedQs | undefined;
  monarchData?: MonarchData;
  teamState?: TeamHuntState;
};

/**
 * This component is a wrapper for the embedded Monarch entrypoint that shows up on every page.
 * The open/close state of the device is defined by the URL query parameters.
 */
function EmbeddedMonarch({
  queryParams,
  monarchData,
  teamState,
}: EmbeddedMonarchProps) {
  const {
    isOpen: initialIsOpen,
    puzzmonSlug,
    search,
    zone,
    page,
    task,
  } = useMonarchQueryParams(queryParams);

  const [isOpen, setIsOpen] = useState(initialIsOpen);

  // Listen for URL changes to update monarch state.
  useEffect(() => {
    if (typeof window === "undefined") return;

    const handleUrlChange = () => {
      const urlParams = new URLSearchParams(window.location.search);
      const isOpenFromUrl =
        urlParams.get(MONARCH_QUERY_KEYS.IS_OPEN) === "true";
      setIsOpen(isOpenFromUrl);
    };

    // Listen for both popstate (back/forward buttons) and custom monarch-open events.
    window.addEventListener("popstate", handleUrlChange);
    window.addEventListener("monarch-open", handleUrlChange);

    return () => {
      window.removeEventListener("popstate", handleUrlChange);
      window.removeEventListener("monarch-open", handleUrlChange);
    };
  }, []);

  const openMonarch = useCallback(() => {
    setIsOpen(true);
    updateQueryParam(MONARCH_QUERY_KEYS.IS_OPEN, "true");
  }, []);
  const closeMonarch = useCallback(() => {
    setIsOpen(false);
    // Clear all Monarch related query params, so that the next time the embedded Monarch gets
    // opened, it opens to the initial state.
    Object.values(MONARCH_QUERY_KEYS).map((monarchQuerykey) => {
      deleteQueryParam(monarchQuerykey);
    });
  }, []);

  useEffect(() => {
    if (isOpen) {
      window.dispatchEvent(new CustomEvent(MONARCH_OPEN_EVENT));
    } else {
      window.dispatchEvent(new CustomEvent(MONARCH_CLOSE_EVENT));
    }
  }, [isOpen]);

  return (
    <>
      <Dialog open={isOpen} modal>
        <DialogTrigger asChild aria-controls="monarch-modal">
          <button
            onClick={openMonarch}
            aria-label="Open Monster Archive"
            className={cn(
              "fixed bottom-4 left-4 z-[101] print:hidden",
              isOpen && "invisible",
            )}
          >
            <MonarchDevice />
          </button>
        </DialogTrigger>
        <DialogContent
          onEscapeKeyDown={closeMonarch}
          onPointerDownOutside={closeMonarch}
          onCloseAutoFocus={(event: Event) => {
            event.preventDefault();
          }}
        >
          <DialogTitle className="sr-only">Monster Archive</DialogTitle>
          {/* The z-index should be above the navbar in NavBar.tsx, which has z-index 100. */}
          <div
            className={`
              max-w-[1277px] min-w-[412px] w-[calc(min(90vw,90vh*16/9))] max-sm:w-[80vw] max-sm:aspect-auto max-sm:h-[90vh]
              fixed top-1/2 left-1/2 rounded-2xl font-body
              transform -translate-x-1/2 -translate-y-1/2 aspect-video z-[101]
              bg-gradient-to-b from-monarch-device-top to-monarch-device-bottom
              shadow-[inset_0_0_24px_#518CD2] border-2 border-monarch-device-border
              dark:from-monarch-device-dark-top dark:to-monarch-device-dark-bottom
              dark:shadow-[inset_0_0_24px_#2A61A2] dark:border-monarch-device-dark-border
            `}
            id="monarch-content"
          >
            <MonarchContent
              initialMonsterSlug={puzzmonSlug}
              initialSearchTerm={search}
              initialZoneFilter={zone}
              initialTask={task}
              initialPage={page}
              monarchData={monarchData}
              teamState={teamState}
            />
            <MonarchDeviceTopLeft className="absolute w-[4.4%] h-auto -top-2.5 -left-4 transform-gpu drop-shadow-[0_3px_3px_rgba(0,0,0,0.25)] pointer-events-none" />
            <div className="absolute w-[13.7%] -top-2.5 -right-4 transform-gpu drop-shadow-[0_3px_3px_rgba(0,0,0,0.25)] ">
              <MonarchDeviceTopRight className="w-full h-auto pointer-events-none" />
              <button
                onClick={closeMonarch}
                className="absolute flex items-center justify-center aspect-square bottom-[9.5%] left-[6%] w-[30%] hover:brightness-125 hover:drop-shadow-[0_0_8px_rgba(46,167,253,0.25)] focus-visible:brightness-125 focus-visible:drop-shadow-[0_0_8px_rgba(46,167,253,0.25)]"
                aria-label="Close MonArch"
              >
                <MonarchGem className="absolute left-0 bottom-0 w-full h-full" />
                <X
                  strokeWidth={2.5}
                  className="text-monarch-accent transform-gpu drop-shadow-[0_4px_4px_rgba(0,0,0,0.25)]"
                  width="80%"
                  height="80%"
                />
              </button>
            </div>
            <MonarchDeviceBottomLeft className="absolute w-[10.4%] h-auto -bottom-2.5 -left-4 transform-gpu drop-shadow-[0_3px_3px_rgba(0,0,0,0.25)] pointer-events-none" />
            <MonarchDeviceBottomRight className="absolute w-[4.7%] h-auto -bottom-2.5 -right-4 transform-gpu drop-shadow-[0_3px_3px_rgba(0,0,0,0.25)] pointer-events-none" />
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

export default EmbeddedMonarch;
