import { type MonsterDetails } from "@hunt/hunt-data/monarch";
import { type TeamHuntState } from "@hunt/public-client";
import { cn } from "@hunt/styled-ui";
import { RotateCcw } from "lucide-react";
import React, { useCallback } from "react";
import TaskSolvedMessage from "../TaskSolvedMessage";
import flowTile from "./assets/flow_tile.png";
import useFlowGame, { PipeType } from "./useFlowGame";

type FlowBoardProps = {
  puzzmonData: MonsterDetails[];
  onComplete: () => void;
  teamState?: TeamHuntState;
  taskSlug?: string;
};

export default function FlowBoard({
  puzzmonData,
  onComplete,
  teamState,
  taskSlug,
}: FlowBoardProps) {
  const {
    onCellEnter,
    onDragStart,
    onDragEnd,
    getPipeType,
    getNodeColorMask,
    clear,
    complete,
  } = useFlowGame(puzzmonData, onComplete);

  const findNode = useCallback(
    (x: number, y: number) => {
      for (const puzzmon of puzzmonData) {
        if (puzzmon.position?.x === x && puzzmon.position?.y === y) {
          return {
            id: puzzmon.name,
            imageSrc: puzzmon.imageSrc,
          };
        }

        for (const item of puzzmon.fetchableItems ?? []) {
          if (item.position?.x === x && item.position?.y === y) {
            return {
              id: item.alt,
              imageSrc: item.src,
            };
          }
        }
      }

      return undefined;
    },
    [puzzmonData],
  );

  const getImage = useCallback(
    (x: number, y: number): React.ReactNode => {
      const found = findNode(x, y);
      if (found) {
        if (found.imageSrc) {
          return (
            <img
              src={found.imageSrc}
              alt={found.id}
              className="absolute top-0 left-0 h-full w-full z-20 object-contain"
              draggable={false}
            />
          );
        } else {
          return (
            <div
              lang="en"
              className="text-black font-semibold p-1 text-xs break-words hyphens-auto absolute w-[calc(90%+2px)] left-[calc(5%-1px)] top-1/2 -translate-y-1/2"
            >
              {found.id}
            </div>
          );
        }
      }

      return null;
    },
    [findNode],
  );

  const getPipe = (x: number, y: number): React.ReactNode => {
    const pipeType = getPipeType({ x, y });
    const color = "bg-monarch-light";
    // Ideally we could just do like `h-${width}` but that doesn't work with tailwind.
    const sizeHeight = "h-3";
    const sizeWidth = "w-3";
    const zIndex = "z-30";

    const endpointDot = (
      <div
        className={cn(
          color,
          zIndex,
          "absolute top-1/2 left-1/2 h-5 w-5 rounded-full translate-x-[-50%] translate-y-[-50%]",
        )}
      />
    );

    if (pipeType === PipeType.ENDPOINT) {
      return endpointDot;
    } else if (
      pipeType === PipeType.ENDPOINT_LEFT ||
      pipeType === PipeType.ENDPOINT_RIGHT ||
      pipeType === PipeType.ENDPOINT_UP ||
      pipeType === PipeType.ENDPOINT_DOWN
    ) {
      const mapping = {
        [PipeType.ENDPOINT_LEFT]: "",
        [PipeType.ENDPOINT_RIGHT]: "rotate-180",
        [PipeType.ENDPOINT_UP]: "rotate-90",
        [PipeType.ENDPOINT_DOWN]: "rotate-[-90deg]",
      };
      const rotate = mapping[pipeType];
      return (
        <div
          className={cn(rotate, zIndex, "w-full h-full absolute top-0 left-0")}
        >
          {endpointDot}
          <div
            className={cn(
              color,
              sizeHeight,
              "absolute top-1/2 w-1/2 left-0 translate-y-[-50%]",
            )}
          />
        </div>
      );
    } else if (
      pipeType === PipeType.HORIZONTAL ||
      pipeType === PipeType.VERTICAL
    ) {
      let rotate = "";
      if (pipeType === PipeType.VERTICAL) {
        rotate = "rotate-90";
      }

      return (
        <div
          className={cn(
            color,
            sizeHeight,
            rotate,
            zIndex,
            "absolute top-1/2 left-0 w-full translate-y-[-50%]",
          )}
        />
      );
    } else if (
      pipeType === PipeType.NE_CORNER ||
      pipeType === PipeType.NW_CORNER ||
      pipeType === PipeType.SE_CORNER ||
      pipeType === PipeType.SW_CORNER
    ) {
      const mapping = {
        [PipeType.NW_CORNER]: "",
        [PipeType.NE_CORNER]: "rotate-90",
        [PipeType.SE_CORNER]: "rotate-180",
        [PipeType.SW_CORNER]: "rotate-[-90deg]",
      };
      const rotate = mapping[pipeType];

      return (
        <div
          className={cn(zIndex, rotate, "w-full h-full absolute top-0 left-0")}
        >
          <div
            className={cn(
              color,
              sizeWidth,
              "absolute top-0 h-[calc(50%+6px)] left-1/2 translate-x-[-50%]",
            )}
          />
          <div
            className={cn(
              color,
              sizeHeight,
              "absolute top-1/2 w-1/2 left-0 translate-y-[-50%]",
            )}
          />
        </div>
      );
    } else {
      return null;
    }
  };

  const getColorMask = useCallback(
    (x: number, y: number): React.ReactNode => {
      const maskColor = getNodeColorMask({ x, y });
      if (maskColor === undefined) {
        return null;
      }

      return (
        <div
          className={cn(
            maskColor,
            // Weird values are because we don't want the mask to cover the border between cells, but
            // the border is in an image so there's no straightforward way to achieve this.
            "absolute w-[calc(90%+2px)] h-[calc(90%+2px)] top-[calc(5%-1px)] left-[calc(5%-1px)] z-10",
          )}
        />
      );
    },
    [getNodeColorMask],
  );

  return (
    <div className="w-full h-full flex flex-col gap-2">
      {/* Solved message and reset button in same row */}
      <div className="relative flex items-end justify-end">
        <TaskSolvedMessage
          teamState={teamState}
          taskSlug={taskSlug}
          className="m-0 absolute top-4 left-1/2 -translate-x-1/2"
        />
        <button
          className="flex items-center gap-2 text-sm lg:text-base mr-28 lg:mr-36 xl:mr-40 mt-8 text-monarch-dark border-[3px] border-[#e6cfa2] font-bold rounded-full pl-3 pr-4 py-1 bg-[#fcefc0] hover:brightness-90 focus-visible:brightness-90 active:brightness-75"
          onClick={clear}
        >
          <RotateCcw height={16} width={16} strokeWidth={3} />
          Reset
        </button>
      </div>

      <div className="flex justify-center items-center min-h-0">
        <div className="object-contain grid grid-cols-12 grid-rows-8 max-w-full max-h-full aspect-[3/2] overflow-hidden">
          {Array.from(Array(8).keys()).map((r) =>
            Array.from(
              Array.from(Array(12).keys()).map((c) => (
                <button
                  key={`cell-bg-${r}-${c}`}
                  className="relative bg-[#e6cfa2]"
                  onMouseDown={
                    complete
                      ? undefined
                      : () => {
                          onDragStart({ x: r, y: c });
                        }
                  }
                  onMouseUp={
                    complete
                      ? undefined
                      : () => {
                          onDragEnd({ x: r, y: c });
                        }
                  }
                  onMouseEnter={
                    complete
                      ? undefined
                      : () => {
                          onCellEnter({ x: r, y: c });
                        }
                  }
                >
                  <img src={flowTile} alt="Tile" draggable={false} />
                  {getColorMask(r, c)}
                  {getImage(r, c)}
                  {getPipe(r, c)}
                </button>
              )),
            ),
          )}
        </div>
      </div>
    </div>
  );
}
